window.__CONTENT_EN__=window.__CONTENT_EN__||{};window.__CONTENT_EN__[5]={"500":{"example:500:exzh":"You need to be careful when moving.","example:500:exzh2":"He is planning a big move.","example:500:exzh3":"I move around every day.","example:500:exzh4":"This move is fun.","example:500:exzh5":"You need to consider how to get around."},"502":{"example:502:exzh":"Are you ready?","example:502:exzh2":"I'll get it ready right away.","example:502:exzh3":"Is there anything I need to prepare?","example:502:exzh4":"I'm right in the middle of preparing.","example:502:exzh5":"I'll get things ready in advance for that."},"503":{"example:503:exzh":"I play games every day.","example:503:exzh2":"This game is very interesting.","example:503:exzh3":"I like playing games with my friends.","example:503:exzh4":"A new game has been released.","example:503:exzh5":"I'll take part in a gaming tournament.","grammar:503:ex:trans":"I play games every day.","grammar:503:ex:structure":"〜をします","grammar:503:ex:explain":"This is an action sentence of the 「〜をします」 type, and the key point is the set collocation 「ゲームをする」 (\"play games\"). The noun 「ゲーム」 (\"game\") takes 「を」 and then 「する」, forming the action \"play games\"; 「します」 is the polite form of 「する」. 「毎日」 (\"every day\") is a frequency adverb, and 「私は」 sets the topic. The whole sentence means \"I play games every day\". Many actions built on nouns are expressed with 「名詞＋を＋する」, such as 「ゲームをする」 and 「勉強をする」; this is the basic pattern for making action sentences.","grammar:503:ex:words:0:zh":"I","grammar:503:ex:words:0:note":"わたし","grammar:503:ex:words:0:pos":"pronoun","grammar:503:ex:words:1:zh":"(topic)","grammar:503:ex:words:1:pos":"particle","grammar:503:ex:words:2:zh":"every day","grammar:503:ex:words:2:note":"まいにち","grammar:503:ex:words:2:pos":"adverb","grammar:503:ex:words:3:zh":"game","grammar:503:ex:words:3:note":"loanword","grammar:503:ex:words:3:pos":"noun","grammar:503:ex:words:4:zh":"(object marker)","grammar:503:ex:words:4:pos":"particle","grammar:503:ex:words:5:zh":"do","grammar:503:ex:words:5:pos":"verb","grammar:503:ex:points:0":"ゲームをする: play games.","grammar:503:ex:points:1":"毎日: every day.","grammar:503:ex2:trans":"This game is very interesting.","grammar:503:ex2:structure":"〜はとても〜です","grammar:503:ex2:words:0:zh":"this","grammar:503:ex2:words:0:pos":"pre-noun adjectival","grammar:503:ex2:words:1:zh":"game","grammar:503:ex2:words:1:note":"loanword","grammar:503:ex2:words:1:pos":"noun","grammar:503:ex2:words:2:zh":"(topic)","grammar:503:ex2:words:2:pos":"particle","grammar:503:ex2:words:3:zh":"extremely","grammar:503:ex2:words:3:pos":"adverb","grammar:503:ex2:words:4:zh":"interesting","grammar:503:ex2:words:4:note":"おもしろい","grammar:503:ex2:words:4:pos":"adjective","grammar:503:ex2:words:5:zh":"(polite form)","grammar:503:ex2:words:5:pos":"copula","grammar:503:ex2:points:0":"このゲーム: this game.","grammar:503:ex2:points:1":"面白い: interesting, fun.","grammar:503:ex3:trans":"I like playing games with friends.","grammar:503:ex3:structure":"〜のが好きです","grammar:503:ex3:words:0:zh":"friend","grammar:503:ex3:words:0:note":"ともだち","grammar:503:ex3:words:0:pos":"noun","grammar:503:ex3:words:1:zh":"with","grammar:503:ex3:words:1:pos":"particle","grammar:503:ex3:words:2:zh":"together","grammar:503:ex3:words:2:note":"いっしょに","grammar:503:ex3:words:2:pos":"adverb","grammar:503:ex3:words:3:zh":"game","grammar:503:ex3:words:3:note":"loanword","grammar:503:ex3:words:3:pos":"noun","grammar:503:ex3:words:4:zh":"(object marker)","grammar:503:ex3:words:4:pos":"particle","grammar:503:ex3:words:5:zh":"hang out","grammar:503:ex3:words:5:note":"あそぶ","grammar:503:ex3:words:5:pos":"verb","grammar:503:ex3:words:6:zh":"(nominalizer)","grammar:503:ex3:words:6:pos":"particle","grammar:503:ex3:words:7:zh":"(object)","grammar:503:ex3:words:7:pos":"particle","grammar:503:ex3:words:8:zh":"to like","grammar:503:ex3:words:8:note":"すき","grammar:503:ex3:words:8:pos":"na-adjective","grammar:503:ex3:words:9:zh":"(polite form)","grammar:503:ex3:words:9:pos":"copula","grammar:503:ex3:points:0":"〜のが好き: to like doing…","grammar:503:ex3:points:1":"(ゲームをする is more natural; here 遊ぶ is used.)","grammar:503:ex4:trans":"A new game has been released.","grammar:503:ex4:structure":"〜が発売されました","grammar:503:ex4:words:0:zh":"new","grammar:503:ex4:words:0:note":"あたらしい","grammar:503:ex4:words:0:pos":"adjective","grammar:503:ex4:words:1:zh":"game","grammar:503:ex4:words:1:note":"loanword","grammar:503:ex4:words:1:pos":"noun","grammar:503:ex4:words:2:zh":"(nominative)","grammar:503:ex4:words:2:pos":"particle","grammar:503:ex4:words:3:zh":"be released","grammar:503:ex4:words:3:note":"はつばいされました (passive form)","grammar:503:ex4:words:3:pos":"verb","grammar:503:ex4:points:0":"発売される: be released, go on sale (passive form).","grammar:503:ex4:points:1":"新しいゲーム: a new game.","grammar:503:ex5:trans":"I'll take part in a gaming tournament.","grammar:503:ex5:structure":"〜に参加します","grammar:503:ex5:words:0:zh":"game","grammar:503:ex5:words:0:note":"loanword","grammar:503:ex5:words:0:pos":"noun","grammar:503:ex5:words:1:zh":"'s","grammar:503:ex5:words:1:pos":"particle","grammar:503:ex5:words:2:zh":"tournament","grammar:503:ex5:words:2:note":"たいかい","grammar:503:ex5:words:2:pos":"noun","grammar:503:ex5:words:3:zh":"(object)","grammar:503:ex5:words:3:pos":"particle","grammar:503:ex5:words:4:zh":"join","grammar:503:ex5:words:4:note":"さんかします","grammar:503:ex5:words:4:pos":"verb","grammar:503:ex5:points:0":"「〜に参加する」: to take part in … (the target takes に).","grammar:503:ex5:points:1":"ゲームの大会: a gaming tournament.","exam:503:zh":"My little brother and I used a machine connected to the TV to play a game where you drive a car and score points.","exam:503:why":"Operating a machine to control a car and score points is playing a 「ゲーム」. 「ニュース」 is news content, not an activity where players operate something to score."},"504":{"example:504:exzh":"The park is nearby.","example:504:exzh2":"I shopped at a nearby store.","example:504:exzh3":"He lives nearby.","example:504:exzh4":"There's a great restaurant nearby.","example:504:exzh5":"You can walk to the nearby station.","grammar:504:ex:trans":"The park is nearby.","grammar:504:ex:structure":"〜は近くにあります","grammar:504:ex:explain":"This is the location-existence pattern 「〜にあります」. The place where something exists, 「近く」 (\"nearby\"), is marked with 「に」, and the verb 「あります」 is used for inanimate things. The key word 「近く（ちかく）」 is a noun of location meaning \"nearby\". 「公園は」 uses 「は」 to set \"the park\" as the topic, which is like saying \"the park — it's nearby\". The whole sentence means \"The park is nearby\". Remember the basic combination for existence sentences: the topic takes 「は」, the location of existence takes 「に」, and 「ある」 is used for inanimate things.","grammar:504:ex:words:0:zh":"park","grammar:504:ex:words:0:note":"こうえん","grammar:504:ex:words:0:pos":"noun","grammar:504:ex:words:1:zh":"(topic)","grammar:504:ex:words:1:pos":"particle","grammar:504:ex:words:2:zh":"nearby","grammar:504:ex:words:2:note":"ちかく","grammar:504:ex:words:2:pos":"noun","grammar:504:ex:words:3:zh":"(location of existence)","grammar:504:ex:words:3:pos":"particle","grammar:504:ex:words:4:zh":"there is / are","grammar:504:ex:words:4:pos":"verb","grammar:504:ex:points:0":"近く（ちかく）: nearby.","grammar:504:ex:points:1":"〜にあります: be at/in … (inanimate things).","grammar:504:ex2:trans":"I shopped at a nearby store.","grammar:504:ex2:structure":"〜で〜をしました","grammar:504:ex2:words:0:zh":"nearby","grammar:504:ex2:words:0:note":"ちかく","grammar:504:ex2:words:0:pos":"noun","grammar:504:ex2:words:1:zh":"'s","grammar:504:ex2:words:1:pos":"particle","grammar:504:ex2:words:2:zh":"store","grammar:504:ex2:words:2:note":"みせ","grammar:504:ex2:words:2:pos":"noun","grammar:504:ex2:words:3:zh":"(place of the action)","grammar:504:ex2:words:3:pos":"particle","grammar:504:ex2:words:4:zh":"shopping","grammar:504:ex2:words:4:note":"かいもの","grammar:504:ex2:words:4:pos":"noun","grammar:504:ex2:words:5:zh":"(object marker)","grammar:504:ex2:words:5:pos":"particle","grammar:504:ex2:words:6:zh":"did","grammar:504:ex2:words:6:pos":"verb","grammar:504:ex2:points:0":"近くの店: a nearby store.","grammar:504:ex2:points:1":"❓で: the place where the shopping happens.","grammar:504:ex3:trans":"He lives nearby.","grammar:504:ex3:structure":"〜に住んでいます","grammar:504:ex3:words:0:zh":"he","grammar:504:ex3:words:0:note":"かれ","grammar:504:ex3:words:0:pos":"pronoun","grammar:504:ex3:words:1:zh":"(topic)","grammar:504:ex3:words:1:pos":"particle","grammar:504:ex3:words:2:zh":"nearby","grammar:504:ex3:words:2:note":"ちかく","grammar:504:ex3:words:2:pos":"noun","grammar:504:ex3:words:3:zh":"(location of existence)","grammar:504:ex3:words:3:pos":"particle","grammar:504:ex3:words:4:zh":"live (there)","grammar:504:ex3:words:4:note":"すんでいます","grammar:504:ex3:words:4:pos":"verb","grammar:504:ex3:points:0":"近くに住む: live nearby.","grammar:504:ex3:points:1":"〜ている: a state.","grammar:504:ex4:trans":"There's a great restaurant nearby.","grammar:504:ex4:structure":"〜に〜があります","grammar:504:ex4:words:0:zh":"nearby","grammar:504:ex4:words:0:note":"ちかく","grammar:504:ex4:words:0:pos":"noun","grammar:504:ex4:words:1:zh":"(location of existence)","grammar:504:ex4:words:1:pos":"particle","grammar:504:ex4:words:2:zh":"great","grammar:504:ex4:words:2:note":"すばらしい","grammar:504:ex4:words:2:pos":"adjective","grammar:504:ex4:words:3:zh":"restaurant","grammar:504:ex4:words:3:note":"loanword","grammar:504:ex4:words:3:pos":"noun","grammar:504:ex4:words:4:zh":"(nominative)","grammar:504:ex4:words:4:pos":"particle","grammar:504:ex4:words:5:zh":"there is / are","grammar:504:ex4:words:5:pos":"verb","grammar:504:ex4:points:0":"近くに: nearby; in the area.","grammar:504:ex4:points:1":"素晴らしいレストラン: a wonderful restaurant.","grammar:504:ex5:trans":"You can walk to the nearby station.","grammar:504:ex5:structure":"〜まで歩いて行けます","grammar:504:ex5:words:0:zh":"nearby","grammar:504:ex5:words:0:note":"ちかく","grammar:504:ex5:words:0:pos":"noun","grammar:504:ex5:words:1:zh":"'s","grammar:504:ex5:words:1:pos":"particle","grammar:504:ex5:words:2:zh":"station","grammar:504:ex5:words:2:note":"えき","grammar:504:ex5:words:2:pos":"noun","grammar:504:ex5:words:3:zh":"until","grammar:504:ex5:words:3:pos":"particle","grammar:504:ex5:words:4:zh":"walk","grammar:504:ex5:words:4:note":"あるいて","grammar:504:ex5:words:4:pos":"verb","grammar:504:ex5:words:5:zh":"can go","grammar:504:ex5:words:5:note":"いけます","grammar:504:ex5:words:5:pos":"verb","grammar:504:ex5:points:0":"〜まで: up to … (end point).","grammar:504:ex5:points:1":"歩いて行ける: can walk (there) (歩いて + 行ける, potential form).","exam:504:zh":"The station is right near my house, so I get there in one minute on foot.","exam:504:why":"Being one minute away on foot means the station is 「近く」 (near) the house. 「中」 means inside, which would put the station inside the house and doesn't fit the location here."},"505":{"example:505:exzh":"My husband is kind.","example:505:exzh2":"I'll travel with my husband.","example:505:exzh3":"My husband works every day.","example:505:exzh4":"His husband is a doctor.","example:505:exzh5":"My husband is good at cooking.","grammar:505:ex:trans":"My husband is gentle.","grammar:505:ex:structure":"〜は〜です","grammar:505:ex:explain":"This is a 「〜は〜です」 sentence with an i-adjective as the predicate. 「私の夫」 is joined with 「の」 into \"my husband\" and set as the topic with 「は」; 「優しい」 (\"gentle\") is an i-adjective that takes 「です」 to become polite. The key word 「夫（おっと）」 is the humble way to refer to one's own husband — for someone else's husband you use 「ご主人」 or 「旦那さん」. The whole sentence means \"My husband is gentle\". As with 「弟」 and 「妹」 above, family terms have humble and respectful versions; 「夫」 is used for your own husband.","grammar:505:ex:words:0:zh":"I","grammar:505:ex:words:0:note":"わたし","grammar:505:ex:words:0:pos":"pronoun","grammar:505:ex:words:1:zh":"'s","grammar:505:ex:words:1:pos":"particle","grammar:505:ex:words:2:zh":"husband","grammar:505:ex:words:2:note":"おっと","grammar:505:ex:words:2:pos":"noun","grammar:505:ex:words:3:zh":"(topic)","grammar:505:ex:words:3:pos":"particle","grammar:505:ex:words:4:zh":"kind","grammar:505:ex:words:4:note":"やさしい","grammar:505:ex:words:4:pos":"adjective","grammar:505:ex:words:5:zh":"(polite form)","grammar:505:ex:words:5:pos":"copula","grammar:505:ex:points:0":"❗夫（おっと）: (humble) one's own husband; for someone else's husband use ご主人 or 旦那さん.","grammar:505:ex:points:1":"優しい: gentle, kind.","grammar:505:ex2:trans":"I'll travel with my husband.","grammar:505:ex2:structure":"〜と一緒に旅行します","grammar:505:ex2:words:0:zh":"husband","grammar:505:ex2:words:0:note":"おっと","grammar:505:ex2:words:0:pos":"noun","grammar:505:ex2:words:1:zh":"with","grammar:505:ex2:words:1:pos":"particle","grammar:505:ex2:words:2:zh":"together","grammar:505:ex2:words:2:note":"いっしょに","grammar:505:ex2:words:2:pos":"adverb","grammar:505:ex2:words:3:zh":"travel / trip","grammar:505:ex2:words:3:note":"りょこうします","grammar:505:ex2:words:3:pos":"verb","grammar:505:ex2:points:0":"〜と一緒に: together with…","grammar:505:ex2:points:1":"旅行する: travel.","grammar:505:ex3:trans":"My husband works every day.","grammar:505:ex3:structure":"〜は〜ています","grammar:505:ex3:words:0:zh":"husband","grammar:505:ex3:words:0:note":"おっと","grammar:505:ex3:words:0:pos":"noun","grammar:505:ex3:words:1:zh":"(topic)","grammar:505:ex3:words:1:pos":"particle","grammar:505:ex3:words:2:zh":"every day","grammar:505:ex3:words:2:note":"まいにち","grammar:505:ex3:words:2:pos":"adverb","grammar:505:ex3:words:3:zh":"is working","grammar:505:ex3:words:3:note":"はたらいています","grammar:505:ex3:words:3:pos":"verb","grammar:505:ex3:points:0":"夫: (my) husband.","grammar:505:ex3:points:1":"〜ている: the state of (working).","grammar:505:ex4:trans":"His husband is a doctor.","grammar:505:ex4:structure":"〜は〜です","grammar:505:ex4:words:0:zh":"he","grammar:505:ex4:words:0:note":"かれ","grammar:505:ex4:words:0:pos":"pronoun","grammar:505:ex4:words:1:zh":"'s","grammar:505:ex4:words:1:pos":"particle","grammar:505:ex4:words:2:zh":"husband","grammar:505:ex4:words:2:note":"おっと","grammar:505:ex4:words:2:pos":"noun","grammar:505:ex4:words:3:zh":"(topic)","grammar:505:ex4:words:3:pos":"particle","grammar:505:ex4:words:4:zh":"doctor","grammar:505:ex4:words:4:note":"いしゃ","grammar:505:ex4:words:4:pos":"noun","grammar:505:ex4:words:5:zh":"is","grammar:505:ex4:words:5:pos":"copula","grammar:505:ex4:points:0":"医者（いしゃ）: doctor.","grammar:505:ex4:points:1":"彼の夫: his husband.","grammar:505:ex5:trans":"My husband is good at cooking.","grammar:505:ex5:structure":"〜は〜が得意です","grammar:505:ex5:words:0:zh":"I","grammar:505:ex5:words:0:note":"わたし","grammar:505:ex5:words:0:pos":"pronoun","grammar:505:ex5:words:1:zh":"'s","grammar:505:ex5:words:1:pos":"particle","grammar:505:ex5:words:2:zh":"husband","grammar:505:ex5:words:2:note":"おっと","grammar:505:ex5:words:2:pos":"noun","grammar:505:ex5:words:3:zh":"(topic)","grammar:505:ex5:words:3:pos":"particle","grammar:505:ex5:words:4:zh":"cooking","grammar:505:ex5:words:4:note":"りょうり","grammar:505:ex5:words:4:pos":"noun","grammar:505:ex5:words:5:zh":"(object)","grammar:505:ex5:words:5:pos":"particle","grammar:505:ex5:words:6:zh":"good at","grammar:505:ex5:words:6:note":"とくい","grammar:505:ex5:words:6:pos":"na-adjective","grammar:505:ex5:words:7:zh":"(polite form)","grammar:505:ex5:words:7:pos":"copula","grammar:505:ex5:points:0":"The object of 「得意」 takes が.","grammar:505:ex5:points:1":"私の夫: my husband."},"506":{"example:506:exzh":"The work is already done.","example:506:exzh2":"Have all the procedures been completed?","example:506:exzh3":"The homework is already done.","example:506:exzh4":"All the problems have been resolved.","example:506:exzh5":"This might settle everything."},"507":{"example:507:exzh":"The Earth is our home.","example:507:exzh2":"There are many living creatures on Earth.","example:507:exzh3":"Protecting the Earth is important.","example:507:exzh4":"Global warming is getting worse.","example:507:exzh5":"Our actions affect the Earth."},"509":{"example:509:exzh":"That guy is interesting.","example:509:exzh2":"Has that guy come already?","example:509:exzh3":"Let's leave it to that guy.","example:509:exzh4":"That guy and that guy are the same.","example:509:exzh5":"That guy is really trustworthy."},"510":{"example:510:exzh":"I have two brothers.","example:510:exzh2":"The brothers get along well.","example:510:exzh3":"Is his brother doing well?","example:510:exzh4":"He is the oldest of the brothers.","example:510:exzh5":"The brothers support each other.","grammar:510:ex:trans":"I have two siblings.","grammar:510:ex:structure":"〜には〜がいます","grammar:510:ex:explain":"This is the possession pattern 「〜には〜がいます」 with a number of people. 「には」 marks \"as for me\", and 「私には」 carries a contrastive nuance. The thing possessed, 「兄弟」 (\"siblings\"), is a person, so the animate verb 「います」 is used, with 「が」 marking it. The number 「二人」 (\"two people\") goes directly before the verb without a particle. The key word 「兄弟（きょうだい）」 refers generally to brothers and sisters. The whole sentence means \"I have two siblings\". When saying how many people someone has, putting the counter directly before the verb is the usual pattern.","grammar:510:ex:words:0:zh":"I","grammar:510:ex:words:0:note":"わたし","grammar:510:ex:words:0:pos":"pronoun","grammar:510:ex:words:1:zh":"(object)","grammar:510:ex:words:1:pos":"particle","grammar:510:ex:words:2:zh":"(contrast)","grammar:510:ex:words:2:pos":"particle","grammar:510:ex:words:3:zh":"siblings","grammar:510:ex:words:3:note":"きょうだい","grammar:510:ex:words:3:pos":"noun","grammar:510:ex:words:4:zh":"(nominative)","grammar:510:ex:words:4:pos":"particle","grammar:510:ex:words:5:zh":"two people","grammar:510:ex:words:5:note":"ふたり","grammar:510:ex:words:5:pos":"noun","grammar:510:ex:words:6:zh":"there is / are","grammar:510:ex:words:6:pos":"verb","grammar:510:ex:points:0":"兄弟（きょうだい）: siblings; brothers and sisters.","grammar:510:ex:points:1":"〜には〜がいる: (someone) has … (a person).","grammar:510:ex2:trans":"The siblings get along well.","grammar:510:ex2:structure":"〜仲が良いです","grammar:510:ex2:words:0:zh":"siblings","grammar:510:ex2:words:0:note":"きょうだい","grammar:510:ex2:words:0:pos":"noun","grammar:510:ex2:words:1:zh":"relationship","grammar:510:ex2:words:1:note":"なか","grammar:510:ex2:words:1:pos":"noun","grammar:510:ex2:words:2:zh":"(nominative)","grammar:510:ex2:words:2:pos":"particle","grammar:510:ex2:words:3:zh":"good","grammar:510:ex2:words:3:note":"いい","grammar:510:ex2:words:3:pos":"adjective","grammar:510:ex2:words:4:zh":"(polite form)","grammar:510:ex2:words:4:pos":"copula","grammar:510:ex2:points:0":"兄弟仲: the relationship between siblings.","grammar:510:ex2:points:1":"仲が良い: to be close, to get along well (the subject takes が).","grammar:510:ex3:trans":"Are his siblings doing well?","grammar:510:ex3:structure":"〜は元気ですか","grammar:510:ex3:words:0:zh":"he","grammar:510:ex3:words:0:note":"かれ","grammar:510:ex3:words:0:pos":"pronoun","grammar:510:ex3:words:1:zh":"'s","grammar:510:ex3:words:1:pos":"particle","grammar:510:ex3:words:2:zh":"siblings","grammar:510:ex3:words:2:note":"きょうだい","grammar:510:ex3:words:2:pos":"noun","grammar:510:ex3:words:3:zh":"(topic)","grammar:510:ex3:words:3:pos":"particle","grammar:510:ex3:words:4:zh":"well / healthy","grammar:510:ex3:words:4:note":"げんき","grammar:510:ex3:words:4:pos":"na-adjective","grammar:510:ex3:words:5:zh":"(polite form)","grammar:510:ex3:words:5:pos":"copula","grammar:510:ex3:words:6:zh":"(question)","grammar:510:ex3:words:6:pos":"particle","grammar:510:ex3:points:0":"彼の兄弟: his siblings.","grammar:510:ex3:points:1":"元気ですか: are you well?; how are you?","grammar:510:ex4:trans":"He is the oldest of the siblings.","grammar:510:ex4:structure":"〜の中で一番〜です","grammar:510:ex4:words:0:zh":"he","grammar:510:ex4:words:0:note":"かれ","grammar:510:ex4:words:0:pos":"pronoun","grammar:510:ex4:words:1:zh":"(topic)","grammar:510:ex4:words:1:pos":"particle","grammar:510:ex4:words:2:zh":"siblings","grammar:510:ex4:words:2:note":"きょうだい","grammar:510:ex4:words:2:pos":"noun","grammar:510:ex4:words:3:zh":"'s","grammar:510:ex4:words:3:pos":"particle","grammar:510:ex4:words:4:zh":"inside","grammar:510:ex4:words:4:note":"なか","grammar:510:ex4:words:4:pos":"noun","grammar:510:ex4:words:5:zh":"(scope)","grammar:510:ex4:words:5:pos":"particle","grammar:510:ex4:words:6:zh":"the most","grammar:510:ex4:words:6:note":"いちばん","grammar:510:ex4:words:6:pos":"adverb","grammar:510:ex4:words:7:zh":"older","grammar:510:ex4:words:7:note":"としうえ","grammar:510:ex4:words:7:pos":"noun","grammar:510:ex4:words:8:zh":"(polite form)","grammar:510:ex4:words:8:pos":"copula","grammar:510:ex4:points:0":"〜の中で一番〜: the most … among … (superlative).","grammar:510:ex4:points:1":"年上: older.","grammar:510:ex5:trans":"The siblings support each other.","grammar:510:ex5:structure":"〜で支え合っています","grammar:510:ex5:words:0:zh":"siblings","grammar:510:ex5:words:0:note":"きょうだい","grammar:510:ex5:words:0:pos":"noun","grammar:510:ex5:words:1:zh":"(the whole group)","grammar:510:ex5:words:1:pos":"particle","grammar:510:ex5:words:2:zh":"are supporting each other","grammar:510:ex5:words:2:note":"ささえあっています","grammar:510:ex5:words:2:pos":"verb","grammar:510:ex5:points:0":"兄弟で: as siblings / among the siblings (で marks the group as a whole).","grammar:510:ex5:points:1":"〜合う: do … to each other (支え合う = to support each other)."},"511":{"example:511:exzh":"Please look behind you.","example:511:exzh2":"Is there anyone behind you?","example:511:exzh3":"He is hiding behind.","example:511:exzh4":"There is a park behind the movie theater.","example:511:exzh5":"I spoke to the person behind me.","grammar:511:ex:trans":"Please look behind you.","grammar:511:ex:structure":"noun＋を＋verbてください. 「後ろを見る」 = to look behind.","grammar:511:ex:explain":"This is the request pattern noun＋を＋verbてください. The te-form of the transitive verb 「見る」 (to look) is 「見て」, which with 「ください」 becomes please look. The object 「後ろ」 (behind) is marked with 「を」. The key word 「後ろ」 (うしろ) is a noun of position meaning behind, at the back. The whole sentence means please look behind you. This 「〜を〜てください」 pattern is the basic polite way to ask someone to do something; here a position noun (後ろ) is treated as the object with 「を」, marking what the action of looking is directed at.","grammar:511:ex:words:0:zh":"behind, the back","grammar:511:ex:words:0:note":"うしろ","grammar:511:ex:words:0:pos":"noun","grammar:511:ex:words:1:zh":"(object marker)","grammar:511:ex:words:1:pos":"particle","grammar:511:ex:words:2:zh":"look","grammar:511:ex:words:2:note":"みて; te-form","grammar:511:ex:words:2:pos":"verb","grammar:511:ex:words:3:zh":"please","grammar:511:ex:words:3:note":"〜てください","grammar:511:ex:words:3:pos":"verb","grammar:511:ex:points:0":"後ろ: behind, the back (a position noun)","grammar:511:ex:points:1":"〜てください: please do…","grammar:511:ex2:trans":"Is anyone at the back?","grammar:511:ex2:structure":"place＋に＋誰か＋いますか. 「誰か」 = someone / anyone; existence takes いる.","grammar:511:ex2:words:0:zh":"behind, the back","grammar:511:ex2:words:0:note":"うしろ","grammar:511:ex2:words:0:pos":"noun","grammar:511:ex2:words:1:zh":"(the place where something exists)","grammar:511:ex2:words:1:pos":"particle","grammar:511:ex2:words:2:zh":"someone / anyone","grammar:511:ex2:words:2:note":"だれか","grammar:511:ex2:words:2:pos":"pronoun","grammar:511:ex2:words:3:zh":"exist","grammar:511:ex2:words:3:note":"a living thing is present","grammar:511:ex2:words:3:pos":"verb","grammar:511:ex2:words:4:zh":"(question)","grammar:511:ex2:words:4:pos":"particle","grammar:511:ex2:points:0":"誰か: someone (an unspecified person)","grammar:511:ex2:points:1":"placeに〜がいる: there is (a person) somewhere","grammar:511:ex3:trans":"He is hiding behind.","grammar:511:ex3:structure":"nounは＋place＋に＋verbています. 「隠れている」 expresses the state of hiding.","grammar:511:ex3:words:0:zh":"he","grammar:511:ex3:words:0:note":"かれ","grammar:511:ex3:words:0:pos":"pronoun","grammar:511:ex3:words:1:zh":"(topic marker)","grammar:511:ex3:words:1:pos":"particle","grammar:511:ex3:words:2:zh":"behind, the back","grammar:511:ex3:words:2:note":"うしろ","grammar:511:ex3:words:2:pos":"noun","grammar:511:ex3:words:3:zh":"(the destination)","grammar:511:ex3:words:3:pos":"particle","grammar:511:ex3:words:4:zh":"is hiding","grammar:511:ex3:words:4:note":"かくれています; 〜ている marks a state","grammar:511:ex3:words:4:pos":"verb","grammar:511:ex3:points:0":"〜に隠れる: to hide behind…","grammar:511:ex3:points:1":"〜ている: state (隠れている = is hidden)","grammar:511:ex4:trans":"There is a park behind the movie theater.","grammar:511:ex4:structure":"〔nounの後ろ〕＋に＋noun＋が＋あります. 「〜の後ろ」 marks relative position.","grammar:511:ex4:words:0:zh":"Movie theater","grammar:511:ex4:words:0:note":"えいがかん","grammar:511:ex4:words:0:pos":"noun","grammar:511:ex4:words:1:zh":"'s","grammar:511:ex4:words:1:pos":"particle","grammar:511:ex4:words:2:zh":"behind, the back","grammar:511:ex4:words:2:note":"うしろ","grammar:511:ex4:words:2:pos":"noun","grammar:511:ex4:words:3:zh":"(the place where something exists)","grammar:511:ex4:words:3:pos":"particle","grammar:511:ex4:words:4:zh":"park","grammar:511:ex4:words:4:note":"こうえん","grammar:511:ex4:words:4:pos":"noun","grammar:511:ex4:words:5:zh":"(nominative)","grammar:511:ex4:words:5:pos":"particle","grammar:511:ex4:words:6:zh":"there is / are","grammar:511:ex4:words:6:note":"exists / there is","grammar:511:ex4:words:6:pos":"verb","grammar:511:ex4:points:0":"〜の後ろ: behind…","grammar:511:ex4:points:1":"placeに〜がある: there is … somewhere","grammar:511:ex5:trans":"I spoke to the person behind me.","grammar:511:ex5:structure":"〔後ろの人〕＋に＋声をかけました. 「〜に声をかける」 = to call out to…","grammar:511:ex5:words:0:zh":"behind, the back","grammar:511:ex5:words:0:note":"うしろ","grammar:511:ex5:words:0:pos":"noun","grammar:511:ex5:words:1:zh":"'s","grammar:511:ex5:words:1:pos":"particle","grammar:511:ex5:words:2:zh":"person","grammar:511:ex5:words:2:note":"ひと","grammar:511:ex5:words:2:pos":"noun","grammar:511:ex5:words:3:zh":"(object)","grammar:511:ex5:words:3:pos":"particle","grammar:511:ex5:words:4:zh":"spoke to him","grammar:511:ex5:words:4:note":"こえをかけました; a set phrase","grammar:511:ex5:words:4:pos":"verb","grammar:511:ex5:points:0":"〜に声をかける: to call out to…","grammar:511:ex5:points:1":"後ろの人: the person behind","exam:511:zh":"In the classroom, my older brother is sitting right in front of me, so I'm sitting behind him.","exam:511:why":"My older brother is in front of me, so from his point of view I'm 「後ろ」. 「前」 would reverse the positions of the two people."},"513":{"example:513:exzh":"I like eating sweets.","example:513:exzh2":"I gave the children snacks.","example:513:exzh3":"This sweet is very sweet.","example:513:exzh4":"I went to a candy shop.","example:513:exzh5":"I'll bring snacks to my friend tomorrow.","grammar:513:ex:trans":"I like eating sweets.","grammar:513:ex:structure":"〜のが好きです","grammar:513:ex:explain":"The key point here is the nominalizing pattern 「〜のが好きだ」 (\"like doing …\"). The formal noun 「の」 turns the verb 「食べる」 (\"eat\") into a noun phrase, and 「が」 marks it as what 「好き」 (\"like\") refers to. So 「食べるのが好き」 means \"like eating\". Note that the thing you like takes 「が」, not 「を」. The object 「おかし」 (\"sweets\") takes 「を」 and connects to 「食べる」. The whole sentence means \"I like eating sweets\". 「動詞辭書形＋のが好きだ」 is a very common frame for saying you like doing something.","grammar:513:ex:words:0:zh":"sweets","grammar:513:ex:words:0:pos":"noun","grammar:513:ex:words:1:zh":"(object marker)","grammar:513:ex:words:1:pos":"particle","grammar:513:ex:words:2:zh":"eat","grammar:513:ex:words:2:note":"たべる","grammar:513:ex:words:2:pos":"verb","grammar:513:ex:words:3:zh":"(nominalizer)","grammar:513:ex:words:3:pos":"particle","grammar:513:ex:words:4:zh":"(object)","grammar:513:ex:words:4:pos":"particle","grammar:513:ex:words:5:zh":"to like","grammar:513:ex:words:5:note":"すき","grammar:513:ex:words:5:pos":"na-adjective","grammar:513:ex:words:6:zh":"(polite form)","grammar:513:ex:words:6:pos":"copula","grammar:513:ex:points:0":"お菓子（おかし）: sweets, snacks.","grammar:513:ex:points:1":"〜のが好き: to like doing…","grammar:513:ex2:trans":"I gave the children sweets.","grammar:513:ex2:structure":"〜に〜をあげました","grammar:513:ex2:words:0:zh":"children","grammar:513:ex2:words:0:note":"こどもたち","grammar:513:ex2:words:0:pos":"noun","grammar:513:ex2:words:1:zh":"(object)","grammar:513:ex2:words:1:pos":"particle","grammar:513:ex2:words:2:zh":"sweets","grammar:513:ex2:words:2:note":"おかし","grammar:513:ex2:words:2:pos":"noun","grammar:513:ex2:words:3:zh":"(object marker)","grammar:513:ex2:words:3:pos":"particle","grammar:513:ex2:words:4:zh":"gave","grammar:513:ex2:words:4:pos":"verb","grammar:513:ex2:points:0":"❗〜に〜をあげる: (I) give … to (someone else) (giving and receiving).","grammar:513:ex2:points:1":"あげる→あげました。","grammar:513:ex3:trans":"This snack is very sweet.","grammar:513:ex3:structure":"〜はとても〜です","grammar:513:ex3:words:0:zh":"this","grammar:513:ex3:words:0:pos":"pre-noun adjectival","grammar:513:ex3:words:1:zh":"sweets","grammar:513:ex3:words:1:note":"おかし","grammar:513:ex3:words:1:pos":"noun","grammar:513:ex3:words:2:zh":"(topic)","grammar:513:ex3:words:2:pos":"particle","grammar:513:ex3:words:3:zh":"extremely","grammar:513:ex3:words:3:pos":"adverb","grammar:513:ex3:words:4:zh":"sweet","grammar:513:ex3:words:4:note":"あまい","grammar:513:ex3:words:4:pos":"adjective","grammar:513:ex3:words:5:zh":"(polite form)","grammar:513:ex3:words:5:pos":"copula","grammar:513:ex3:points:0":"甘い: sweet (i-adjective).","grammar:513:ex3:points:1":"このお菓子: this snack.","grammar:513:ex4:trans":"I went to a candy shop.","grammar:513:ex4:structure":"〜に行きました","grammar:513:ex4:words:0:zh":"candy shop","grammar:513:ex4:words:0:note":"おかしやさん","grammar:513:ex4:words:0:pos":"noun","grammar:513:ex4:words:1:zh":"(destination)","grammar:513:ex4:words:1:pos":"particle","grammar:513:ex4:words:2:zh":"went","grammar:513:ex4:words:2:note":"いきました","grammar:513:ex4:words:2:pos":"verb","grammar:513:ex4:points:0":"〜屋さん: a … shop (お菓子屋さん = a candy/sweet shop).","grammar:513:ex4:points:1":"に：destination of movement.","grammar:513:ex5:trans":"Tomorrow I'll take some sweets to a friend.","grammar:513:ex5:structure":"〜に〜を持っていきます","grammar:513:ex5:words:0:zh":"tomorrow","grammar:513:ex5:words:0:note":"あした","grammar:513:ex5:words:0:pos":"noun","grammar:513:ex5:words:1:zh":"friend","grammar:513:ex5:words:1:note":"ともだち","grammar:513:ex5:words:1:pos":"noun","grammar:513:ex5:words:2:zh":"(object)","grammar:513:ex5:words:2:pos":"particle","grammar:513:ex5:words:3:zh":"sweets","grammar:513:ex5:words:3:note":"おかし","grammar:513:ex5:words:3:pos":"noun","grammar:513:ex5:words:4:zh":"(object marker)","grammar:513:ex5:words:4:pos":"particle","grammar:513:ex5:words:5:zh":"take (to)","grammar:513:ex5:words:5:note":"もっていきます","grammar:513:ex5:words:5:pos":"verb","grammar:513:ex5:points:0":"〜に〜を持っていく: take … to …","grammar:513:ex5:points:1":"持っていく: take (something) along."},"514":{"example:514:exzh":"The next meeting is next week.","example:514:exzh2":"Do you want to go see a movie together next time?","example:514:exzh3":"I'm looking forward to the next trip.","example:514:exzh4":"I'm busy next weekend.","example:514:exzh5":"Next time, please invite me.","grammar:514:ex:trans":"The next meeting is next week.","grammar:514:ex:structure":"〔今度のnoun〕＋は＋time noun＋です. 「今度の会議」 = the next meeting.","grammar:514:ex:explain":"This is a noun judgment sentence, and the key word is 「今度」 (こんど). The meaning of 「今度」 shifts with context — it can mean next time, this time, or recently; paired here with 「会議」 and 「来週」 (next week), it reads most naturally as the next meeting. 「今度の会議」 is joined with 「の」. The 「来週です」 at the end uses a time noun plus 「です」 to say it is next week, and 「は」 up front marks the topic. The whole sentence means the next meeting is next week. 「今度」 is a word with several meanings that you have to judge from context, so keep an eye on it.","grammar:514:ex:words:0:zh":"next time","grammar:514:ex:words:0:note":"こんど","grammar:514:ex:words:0:pos":"noun","grammar:514:ex:words:1:zh":"'s","grammar:514:ex:words:1:pos":"particle","grammar:514:ex:words:2:zh":"meeting","grammar:514:ex:words:2:note":"かいぎ","grammar:514:ex:words:2:pos":"noun","grammar:514:ex:words:3:zh":"(topic marker)","grammar:514:ex:words:3:pos":"particle","grammar:514:ex:words:4:zh":"next week","grammar:514:ex:words:4:note":"らいしゅう","grammar:514:ex:words:4:pos":"noun","grammar:514:ex:words:5:zh":"is","grammar:514:ex:words:5:pos":"copula","grammar:514:ex:points:0":"今度: next time (can also mean this time, depending on context)","grammar:514:ex:points:1":"time noun＋です: is at … (a time)","grammar:514:ex2:trans":"Shall we go see a movie next time?","grammar:514:ex2:structure":"今度、〔verb masu-stem＋に〕＋行きませんか. 「〜ませんか」 is a gentle invitation.","grammar:514:ex2:words:0:zh":"next time","grammar:514:ex2:words:0:note":"こんど","grammar:514:ex2:words:0:pos":"noun","grammar:514:ex2:words:1:zh":"movie","grammar:514:ex2:words:1:note":"えいが","grammar:514:ex2:words:1:pos":"noun","grammar:514:ex2:words:2:zh":"(object marker)","grammar:514:ex2:words:2:pos":"particle","grammar:514:ex2:words:3:zh":"go to see","grammar:514:ex2:words:3:note":"みに; masu-stem＋に marks purpose","grammar:514:ex2:words:3:pos":"verb","grammar:514:ex2:words:4:zh":"shall we go","grammar:514:ex2:words:4:note":"〜ませんか: invitation","grammar:514:ex2:words:4:pos":"verb","grammar:514:ex2:points:0":"〜ませんか: won't you…? (invitation)","grammar:514:ex2:points:1":"見に行く: to go to see","grammar:514:ex3:trans":"I'm looking forward to the next trip.","grammar:514:ex3:structure":"〔今度の旅行〕＋を＋楽しみにしています. 「〜を楽しみにする」 = to look forward to…","grammar:514:ex3:words:0:zh":"next time","grammar:514:ex3:words:0:note":"こんど","grammar:514:ex3:words:0:pos":"noun","grammar:514:ex3:words:1:zh":"'s","grammar:514:ex3:words:1:pos":"particle","grammar:514:ex3:words:2:zh":"travel / trip","grammar:514:ex3:words:2:note":"りょこう","grammar:514:ex3:words:2:pos":"noun","grammar:514:ex3:words:3:zh":"(object marker)","grammar:514:ex3:words:3:pos":"particle","grammar:514:ex3:words:4:zh":"looking forward to","grammar:514:ex3:words:4:note":"たのしみにしています; a set phrase","grammar:514:ex3:words:4:pos":"verb","grammar:514:ex3:points:0":"〜を楽しみにする: to look forward to…","grammar:514:ex3:points:1":"楽しみにしています: I'm (still) looking forward to it","grammar:514:ex4:trans":"I'm busy this coming weekend.","grammar:514:ex4:structure":"〔今度の週末〕＋は＋i-adjective＋です.","grammar:514:ex4:words:0:zh":"this / next","grammar:514:ex4:words:0:note":"こんど","grammar:514:ex4:words:0:pos":"noun","grammar:514:ex4:words:1:zh":"'s","grammar:514:ex4:words:1:pos":"particle","grammar:514:ex4:words:2:zh":"weekend","grammar:514:ex4:words:2:note":"しゅうまつ","grammar:514:ex4:words:2:pos":"noun","grammar:514:ex4:words:3:zh":"(topic marker)","grammar:514:ex4:words:3:pos":"particle","grammar:514:ex4:words:4:zh":"busy","grammar:514:ex4:words:4:note":"いそがしい","grammar:514:ex4:words:4:pos":"adjective","grammar:514:ex4:words:5:zh":"(polite form)","grammar:514:ex4:words:5:pos":"copula","grammar:514:ex4:points:0":"今度の週末: this / next weekend","grammar:514:ex4:points:1":"忙しいです: polite form of an i-adjective","grammar:514:ex5:trans":"Next time, please invite me.","grammar:514:ex5:structure":"今度は＋nounが＋verbてください. 「今度は」 carries the contrast of this time it's your turn, and 「が」 emphasizes that it's you.","grammar:514:ex5:words:0:zh":"next time","grammar:514:ex5:words:0:note":"こんど","grammar:514:ex5:words:0:pos":"noun","grammar:514:ex5:words:1:zh":"(contrastive topic)","grammar:514:ex5:words:1:pos":"particle","grammar:514:ex5:words:2:zh":"you","grammar:514:ex5:words:2:pos":"pronoun","grammar:514:ex5:words:3:zh":"(nominative)","grammar:514:ex5:words:3:note":"emphasizes that it's you","grammar:514:ex5:words:3:pos":"particle","grammar:514:ex5:words:4:zh":"invite","grammar:514:ex5:words:4:note":"さそって; te-form","grammar:514:ex5:words:4:pos":"verb","grammar:514:ex5:words:5:zh":"please","grammar:514:ex5:words:5:note":"〜てください","grammar:514:ex5:words:5:pos":"verb","grammar:514:ex5:points:0":"今度は: this time (someone else's turn) / next time (contrastive)","grammar:514:ex5:points:1":"〜が＋てください: please … (emphasizing who does it)"},"515":{"example:515:exzh":"This matter is very important.","example:515:exzh2":"I'll value your opinion.","example:515:exzh3":"I have something important to tell you.","example:515:exzh4":"Health is the most important thing.","example:515:exzh5":"I cherish the time I spend with important people.","grammar:515:ex:trans":"This matter is very important.","grammar:515:ex:structure":"〜はとても大事です","grammar:515:ex:explain":"This is an adjective predicate sentence, and the key word is 「大事（だいじ）」. 「大事」 is a na-adjective meaning \"important, crucial\", close in meaning to 「重要」, and takes 「です」 in the polite form as a predicate. 「とても (very)」 is an adverb of degree modifying it. 「このことは」 uses 「は」 to mark the topic \"this matter\". The whole sentence is \"This matter is very important\". Note that 「大事」 read as 「だいじ」 is a na-adjective meaning \"important\"; it can also be a noun, but here it is used as an adjective, and 「とても大事です」 expresses emphasis.","grammar:515:ex:words:0:zh":"this","grammar:515:ex:words:0:pos":"pre-noun adjectival","grammar:515:ex:words:1:zh":"thing / matter","grammar:515:ex:words:1:pos":"noun","grammar:515:ex:words:2:zh":"(topic)","grammar:515:ex:words:2:pos":"particle","grammar:515:ex:words:3:zh":"extremely","grammar:515:ex:words:3:pos":"adverb","grammar:515:ex:words:4:zh":"important","grammar:515:ex:words:4:note":"だいじ","grammar:515:ex:words:4:pos":"na-adjective","grammar:515:ex:words:5:zh":"(polite form)","grammar:515:ex:words:5:pos":"copula","grammar:515:ex:points:1":"大事: important.","grammar:515:ex2:trans":"I'll value your opinion.","grammar:515:ex2:structure":"〜を大事にします","grammar:515:ex2:words:0:zh":"you","grammar:515:ex2:words:0:pos":"pronoun","grammar:515:ex2:words:1:zh":"'s","grammar:515:ex2:words:1:pos":"particle","grammar:515:ex2:words:2:zh":"opinion","grammar:515:ex2:words:2:note":"いけん","grammar:515:ex2:words:2:pos":"noun","grammar:515:ex2:words:3:zh":"(topic)","grammar:515:ex2:words:3:pos":"particle","grammar:515:ex2:words:4:zh":"to value","grammar:515:ex2:words:4:note":"だいじに","grammar:515:ex2:words:4:pos":"adverb","grammar:515:ex2:words:5:zh":"do","grammar:515:ex2:words:5:pos":"verb","grammar:515:ex2:points:0":"❗〜を大事にする: to value, to treasure …; 意見を大事に = to value an opinion.","grammar:515:ex2:points:1":"大事にする: to value.","grammar:515:ex3:trans":"I have something important to discuss.","grammar:515:ex3:structure":"大事な話があります","grammar:515:ex3:words:0:zh":"important","grammar:515:ex3:words:0:note":"だいじ","grammar:515:ex3:words:0:pos":"na-adjective","grammar:515:ex3:words:1:zh":"(attributive form)","grammar:515:ex3:words:1:pos":"auxiliary verb","grammar:515:ex3:words:2:zh":"thing / matter","grammar:515:ex3:words:2:note":"はなし","grammar:515:ex3:words:2:pos":"noun","grammar:515:ex3:words:3:zh":"(nominative)","grammar:515:ex3:words:3:pos":"particle","grammar:515:ex3:words:4:zh":"there is / are","grammar:515:ex3:words:4:pos":"verb","grammar:515:ex3:points:0":"❗大事な話: an important matter, something serious; 話 = topic, matter.","grammar:515:ex3:points:1":"大事な話: an important matter.","grammar:515:ex4:trans":"Health is the most important thing.","grammar:515:ex4:structure":"〜が一番大事です","grammar:515:ex4:words:0:zh":"health","grammar:515:ex4:words:0:note":"けんこう","grammar:515:ex4:words:0:pos":"noun","grammar:515:ex4:words:1:zh":"(nominative)","grammar:515:ex4:words:1:pos":"particle","grammar:515:ex4:words:2:zh":"the most","grammar:515:ex4:words:2:note":"いちばん","grammar:515:ex4:words:2:pos":"noun","grammar:515:ex4:words:3:zh":"important","grammar:515:ex4:words:3:note":"だいじ","grammar:515:ex4:words:3:pos":"na-adjective","grammar:515:ex4:words:4:zh":"(polite form)","grammar:515:ex4:words:4:pos":"copula","grammar:515:ex4:points:0":"❗一番大事: the most important; 一番 = most.","grammar:515:ex4:points:1":"一番大事: the most important.","grammar:515:ex5:trans":"I'll cherish the time I spend with the people who matter.","grammar:515:ex5:structure":"大事な人と過ごす時間を大切にします","grammar:515:ex5:words:0:zh":"important","grammar:515:ex5:words:0:note":"だいじ","grammar:515:ex5:words:0:pos":"na-adjective","grammar:515:ex5:words:1:zh":"(attributive form)","grammar:515:ex5:words:1:pos":"auxiliary verb","grammar:515:ex5:words:2:zh":"person","grammar:515:ex5:words:2:note":"ひと","grammar:515:ex5:words:2:pos":"noun","grammar:515:ex5:words:3:zh":"(object)","grammar:515:ex5:words:3:pos":"particle","grammar:515:ex5:words:4:zh":"getting along","grammar:515:ex5:words:4:note":"すごす","grammar:515:ex5:words:4:pos":"verb","grammar:515:ex5:words:5:zh":"time","grammar:515:ex5:words:5:note":"じかん","grammar:515:ex5:words:5:pos":"noun","grammar:515:ex5:words:6:zh":"(object marker)","grammar:515:ex5:words:6:pos":"particle","grammar:515:ex5:words:7:zh":"cherish","grammar:515:ex5:words:7:note":"たいせつに","grammar:515:ex5:words:7:pos":"adverb","grammar:515:ex5:words:8:zh":"do","grammar:515:ex5:words:8:pos":"verb","grammar:515:ex5:points:0":"❗大事な人: someone important; 〜を大切にする = to cherish …","grammar:515:ex5:points:1":"大事な人: someone important."},"516":{"example:516:exzh":"I consulted a doctor.","example:516:exzh2":"This doctor can be trusted.","example:516:exzh3":"I want to become a doctor.","example:516:exzh4":"Doctors cure illnesses.","example:516:exzh5":"When you're sick, let's go to the doctor.","grammar:516:ex:trans":"I consulted a doctor.","grammar:516:ex:structure":"〜に相談しました","grammar:516:ex:explain":"This sentence uses the set collocation 「〜に相談する」 (to consult with …). The person you consult is marked with 「に」, so 「医者に相談する」 means 'to talk it over with a doctor.' The verb 「相談する」 is an irregular サ変 verb, and its polite past form is 「相談しました」. The key point is that the person you consult takes 「に」. The whole sentence means 'I consulted a doctor.' Just like 「〜に怒る」 and 「〜に慣れる」 above, the target or direction of this kind of action usually takes 「に」, and the person you consult with 「相談」 is no exception.","grammar:516:ex:words:0:zh":"doctor","grammar:516:ex:words:0:note":"いしゃ","grammar:516:ex:words:0:pos":"noun","grammar:516:ex:words:1:zh":"(object)","grammar:516:ex:words:1:pos":"particle","grammar:516:ex:words:2:zh":"consulted","grammar:516:ex:words:2:note":"そうだんしました","grammar:516:ex:words:2:pos":"verb","grammar:516:ex:points:0":"❗〜に相談する: to consult with … (the target takes に).","grammar:516:ex:points:1":"医者に相談: to consult a doctor.","grammar:516:ex2:trans":"This doctor can be trusted.","grammar:516:ex2:structure":"〜は信頼できます","grammar:516:ex2:words:0:zh":"this","grammar:516:ex2:words:0:pos":"pre-noun adjectival","grammar:516:ex2:words:1:zh":"doctor","grammar:516:ex2:words:1:note":"いしゃ","grammar:516:ex2:words:1:pos":"noun","grammar:516:ex2:words:2:zh":"(topic)","grammar:516:ex2:words:2:pos":"particle","grammar:516:ex2:words:3:zh":"can be trusted","grammar:516:ex2:words:3:note":"しんらいできます","grammar:516:ex2:words:3:pos":"verb","grammar:516:ex2:points:0":"❗信頼できる: trustworthy (potential form of 信頼する).","grammar:516:ex2:points:1":"この医者: this doctor.","grammar:516:ex3:trans":"I want to become a doctor.","grammar:516:ex3:structure":"〜になりたいと思っています","grammar:516:ex3:words:0:zh":"doctor","grammar:516:ex3:words:0:note":"いしゃ","grammar:516:ex3:words:0:pos":"noun","grammar:516:ex3:words:1:zh":"(result)","grammar:516:ex3:words:1:pos":"particle","grammar:516:ex3:words:2:zh":"want to become","grammar:516:ex3:words:2:note":"なりたい","grammar:516:ex3:words:2:pos":"verb","grammar:516:ex3:words:3:zh":"(quotation)","grammar:516:ex3:words:3:pos":"particle","grammar:516:ex3:words:4:zh":"thinking","grammar:516:ex3:words:4:note":"おもっています","grammar:516:ex3:words:4:pos":"verb","grammar:516:ex3:points:0":"❗〜になりたい: to want to become … (に + なる + たい).","grammar:516:ex3:points:1":"医者になる: to become a doctor.","grammar:516:ex4:trans":"Doctors treat illness.","grammar:516:ex4:structure":"〜を治します","grammar:516:ex4:words:0:zh":"doctor","grammar:516:ex4:words:0:note":"いしゃ","grammar:516:ex4:words:0:pos":"noun","grammar:516:ex4:words:1:zh":"(topic)","grammar:516:ex4:words:1:pos":"particle","grammar:516:ex4:words:2:zh":"disease","grammar:516:ex4:words:2:note":"びょうき","grammar:516:ex4:words:2:pos":"noun","grammar:516:ex4:words:3:zh":"(object marker)","grammar:516:ex4:words:3:pos":"particle","grammar:516:ex4:words:4:zh":"treatment","grammar:516:ex4:words:4:note":"なおします","grammar:516:ex4:words:4:pos":"verb","grammar:516:ex4:points:0":"❗治す (transitive verb, to cure …); vs 治る (intransitive verb, to heal).","grammar:516:ex4:points:1":"病気を治す: to cure an illness.","grammar:516:ex5:trans":"When you're sick, go see a doctor.","grammar:516:ex5:structure":"〜の時は〜に行きましょう","grammar:516:ex5:words:0:zh":"disease","grammar:516:ex5:words:0:note":"びょうき","grammar:516:ex5:words:0:pos":"noun","grammar:516:ex5:words:1:zh":"'s","grammar:516:ex5:words:1:pos":"particle","grammar:516:ex5:words:2:zh":"time","grammar:516:ex5:words:2:note":"とき","grammar:516:ex5:words:2:pos":"noun","grammar:516:ex5:words:3:zh":"(topic)","grammar:516:ex5:words:3:pos":"particle","grammar:516:ex5:words:4:zh":"doctor","grammar:516:ex5:words:4:note":"いしゃ","grammar:516:ex5:words:4:pos":"noun","grammar:516:ex5:words:5:zh":"(destination)","grammar:516:ex5:words:5:pos":"particle","grammar:516:ex5:words:6:zh":"let's go","grammar:516:ex5:words:6:pos":"verb","grammar:516:ex5:points:0":"❗病気の時: when you are sick.","grammar:516:ex5:points:1":"医者に行く: see a doctor."},"517":{"example:517:exzh":"What do we do in this case?","example:517:exzh2":"I'll be prepared for every case.","example:517:exzh3":"In special cases, permission is required.","example:517:exzh4":"If there's a problem, please contact me.","example:517:exzh5":"In that case, let's think of another way.","grammar:517:ex:trans":"What should we do in this case?","grammar:517:ex:structure":"この場合は、どうしますか","grammar:517:ex:explain":"The key point of this sentence is the pattern 「〜場合は (in the case of …)」, a common N3 expression. 「場合（ばあい）」 means \"case, situation\", so 「この場合は」 means \"in this case\", used to set a condition or assume a situation. The following 「どうしますか」 asks \"what should we do?\". The whole sentence is \"What should we do in this case?\". 「〜場合は」 is often used when discussing assumptions, rules, or how to respond; remember 「この場合 = in this case」 first — it's a very practical pattern.","grammar:517:ex:words:0:zh":"this","grammar:517:ex:words:0:pos":"pre-noun adjectival","grammar:517:ex:words:1:zh":"case","grammar:517:ex:words:1:note":"ばあい","grammar:517:ex:words:1:pos":"noun","grammar:517:ex:words:2:zh":"(topic)","grammar:517:ex:words:2:pos":"particle","grammar:517:ex:words:3:zh":"how","grammar:517:ex:words:3:pos":"adverb","grammar:517:ex:words:4:zh":"do","grammar:517:ex:words:4:pos":"verb","grammar:517:ex:words:5:zh":"(question)","grammar:517:ex:words:5:pos":"particle","grammar:517:ex:points:0":"❗場合（ばあい）: case, situation; 〜場合は = in the case of … (important N3 pattern).","grammar:517:ex:points:1":"この場合: this case.","grammar:517:ex2:trans":"I'll prepare for every case.","grammar:517:ex2:structure":"〜に備えておきます","grammar:517:ex2:words:0:zh":"all","grammar:517:ex2:words:0:note":"すべて","grammar:517:ex2:words:0:pos":"noun","grammar:517:ex2:words:1:zh":"'s","grammar:517:ex2:words:1:pos":"particle","grammar:517:ex2:words:2:zh":"case","grammar:517:ex2:words:2:note":"ばあい","grammar:517:ex2:words:2:pos":"noun","grammar:517:ex2:words:3:zh":"(object)","grammar:517:ex2:words:3:pos":"particle","grammar:517:ex2:words:4:zh":"prepare","grammar:517:ex2:words:4:note":"そなえて","grammar:517:ex2:words:4:pos":"verb","grammar:517:ex2:words:5:zh":"(do in advance)","grammar:517:ex2:words:5:pos":"auxiliary verb","grammar:517:ex2:points:0":"❗〜に備える: to prepare for …, to guard against; 〜ておく = to do in advance.","grammar:517:ex2:points:1":"場合に備える: to prepare for any eventuality.","grammar:517:ex3:trans":"Special cases require permission.","grammar:517:ex3:structure":"特別な場合には〜が必要です","grammar:517:ex3:words:0:zh":"special","grammar:517:ex3:words:0:note":"とくべつ","grammar:517:ex3:words:0:pos":"na-adjective","grammar:517:ex3:words:1:zh":"(attributive form)","grammar:517:ex3:words:1:pos":"auxiliary verb","grammar:517:ex3:words:2:zh":"case","grammar:517:ex3:words:2:note":"ばあい","grammar:517:ex3:words:2:pos":"noun","grammar:517:ex3:words:3:zh":"(point in time)","grammar:517:ex3:words:3:pos":"particle","grammar:517:ex3:words:4:zh":"(contrast)","grammar:517:ex3:words:4:pos":"particle","grammar:517:ex3:words:5:zh":"permission","grammar:517:ex3:words:5:note":"きょか","grammar:517:ex3:words:5:pos":"noun","grammar:517:ex3:words:6:zh":"(nominative)","grammar:517:ex3:words:6:pos":"particle","grammar:517:ex3:words:7:zh":"necessary","grammar:517:ex3:words:7:note":"ひつよう","grammar:517:ex3:words:7:pos":"na-adjective","grammar:517:ex3:words:8:zh":"(polite form)","grammar:517:ex3:words:8:pos":"copula","grammar:517:ex3:points:0":"❗特別な場合には: in special cases; 許可が必要 = permission is required.","grammar:517:ex3:points:1":"特別な場合: a special case.","grammar:517:ex4:trans":"If there's a problem, please contact me.","grammar:517:ex4:structure":"〜があった場合は、連絡してください","grammar:517:ex4:words:0:zh":"problem","grammar:517:ex4:words:0:note":"もんだい","grammar:517:ex4:words:0:pos":"noun","grammar:517:ex4:words:1:zh":"(nominative)","grammar:517:ex4:words:1:pos":"particle","grammar:517:ex4:words:2:zh":"there is / are","grammar:517:ex4:words:2:pos":"verb","grammar:517:ex4:words:3:zh":"case","grammar:517:ex4:words:3:note":"ばあい","grammar:517:ex4:words:3:pos":"noun","grammar:517:ex4:words:4:zh":"(topic)","grammar:517:ex4:words:4:pos":"particle","grammar:517:ex4:words:5:zh":"contact","grammar:517:ex4:words:5:note":"れんらくして","grammar:517:ex4:words:5:pos":"verb","grammar:517:ex4:words:6:zh":"please","grammar:517:ex4:words:6:pos":"auxiliary verb","grammar:517:ex4:points:0":"❗〜た場合は: when … happens (just in case); 問題があった場合 = if there is a problem.","grammar:517:ex4:points:1":"あった場合: when it happens.","grammar:517:ex5:trans":"In that case, let's think of another way.","grammar:517:ex5:structure":"その場合は、別の方法を考えましょう","grammar:517:ex5:words:0:zh":"that","grammar:517:ex5:words:0:pos":"pre-noun adjectival","grammar:517:ex5:words:1:zh":"case","grammar:517:ex5:words:1:note":"ばあい","grammar:517:ex5:words:1:pos":"noun","grammar:517:ex5:words:2:zh":"(topic)","grammar:517:ex5:words:2:pos":"particle","grammar:517:ex5:words:3:zh":"another","grammar:517:ex5:words:3:note":"べつ","grammar:517:ex5:words:3:pos":"noun","grammar:517:ex5:words:4:zh":"'s","grammar:517:ex5:words:4:pos":"particle","grammar:517:ex5:words:5:zh":"way, method","grammar:517:ex5:words:5:note":"ほうほう","grammar:517:ex5:words:5:pos":"noun","grammar:517:ex5:words:6:zh":"(object marker)","grammar:517:ex5:words:6:pos":"particle","grammar:517:ex5:words:7:zh":"let's think","grammar:517:ex5:words:7:note":"かんがえましょう","grammar:517:ex5:words:7:pos":"verb","grammar:517:ex5:points:0":"❗その場合は: in that case; 別の方法 = another way.","grammar:517:ex5:points:1":"その場合: that case."},"518":{"example:518:exzh":"The government made a new law.","example:518:exzh2":"This policy is decided by the government.","example:518:exzh3":"Trust in the government is declining.","example:518:exzh4":"The government supports local development.","example:518:exzh5":"It's important to understand the government's policy."},"519":{"example:519:exzh":"Don't miss a good opportunity.","example:519:exzh2":"This is my chance.","example:519:exzh3":"If I get a chance, I'll give it a try.","example:519:exzh4":"A new job opportunity has come up.","example:519:exzh5":"The harder you work, the more chances you get.","grammar:519:ex:trans":"Please don't miss a good chance.","grammar:519:ex:structure":"〜を見逃さないでください","grammar:519:ex:explain":"This is the negative request 「〜ないでください」 used with the idiom 「見逃す」. 「見逃す（みのがす）」 means \"to miss, to let go, to overlook\", so 「チャンスを見逃す」 is \"to miss a chance\". To make the negative request, the nai-form of 「見逃す」, 「見逃さない」, takes 「でください」 to become 「見逃さないでください」 (\"please don't miss it\"). The object 「良いチャンス」 (\"a good chance\") takes 「を」. The whole sentence means \"Please don't miss a good chance\" — a common way to remind someone to seize an opportunity.","grammar:519:ex:words:0:zh":"good","grammar:519:ex:words:0:note":"いい","grammar:519:ex:words:0:pos":"adjective","grammar:519:ex:words:1:zh":"chance","grammar:519:ex:words:1:note":"loanword","grammar:519:ex:words:1:pos":"noun","grammar:519:ex:words:2:zh":"(object marker)","grammar:519:ex:words:2:pos":"particle","grammar:519:ex:words:3:zh":"don't miss","grammar:519:ex:words:3:note":"みのがさないで","grammar:519:ex:words:3:pos":"verb","grammar:519:ex:words:4:zh":"please","grammar:519:ex:words:4:pos":"auxiliary verb","grammar:519:ex:points:0":"チャンスを見逃す: miss a chance.","grammar:519:ex:points:1":"「〜ないでください」: please don't …","grammar:519:ex2:trans":"This is my chance.","grammar:519:ex2:structure":"これは〜のチャンスです","grammar:519:ex2:words:0:zh":"this","grammar:519:ex2:words:0:pos":"pronoun","grammar:519:ex2:words:1:zh":"(topic)","grammar:519:ex2:words:1:pos":"particle","grammar:519:ex2:words:2:zh":"I","grammar:519:ex2:words:2:note":"わたし","grammar:519:ex2:words:2:pos":"pronoun","grammar:519:ex2:words:3:zh":"'s","grammar:519:ex2:words:3:pos":"particle","grammar:519:ex2:words:4:zh":"chance","grammar:519:ex2:words:4:note":"loanword","grammar:519:ex2:words:4:pos":"noun","grammar:519:ex2:words:5:zh":"is","grammar:519:ex2:words:5:pos":"copula","grammar:519:ex2:points:0":"私のチャンス: my chance.","grammar:519:ex2:points:1":"チャンス: chance, opportunity.","grammar:519:ex3:trans":"If I get a chance, I'll give it a try.","grammar:519:ex3:structure":"〜ば、〜てみます","grammar:519:ex3:words:0:zh":"chance","grammar:519:ex3:words:0:note":"loanword","grammar:519:ex3:words:0:pos":"noun","grammar:519:ex3:words:1:zh":"(nominative)","grammar:519:ex3:words:1:pos":"particle","grammar:519:ex3:words:2:zh":"if there is","grammar:519:ex3:words:2:pos":"verb","grammar:519:ex3:words:3:zh":"challenge; try","grammar:519:ex3:words:3:note":"ちょうせんして","grammar:519:ex3:words:3:pos":"verb","grammar:519:ex3:words:4:zh":"try","grammar:519:ex3:words:4:pos":"auxiliary verb","grammar:519:ex3:points:0":"❗〜ば: if … (ある → あれば, conditional form).","grammar:519:ex3:points:1":"〜てみます: try doing …","grammar:519:ex4:trans":"A new job opportunity has come up.","grammar:519:ex4:structure":"〜が来ました","grammar:519:ex4:words:0:zh":"new","grammar:519:ex4:words:0:note":"あたらしい","grammar:519:ex4:words:0:pos":"adjective","grammar:519:ex4:words:1:zh":"work","grammar:519:ex4:words:1:note":"しごと","grammar:519:ex4:words:1:pos":"noun","grammar:519:ex4:words:2:zh":"'s","grammar:519:ex4:words:2:pos":"particle","grammar:519:ex4:words:3:zh":"chance","grammar:519:ex4:words:3:note":"loanword","grammar:519:ex4:words:3:pos":"noun","grammar:519:ex4:words:4:zh":"(nominative)","grammar:519:ex4:words:4:pos":"particle","grammar:519:ex4:words:5:zh":"came","grammar:519:ex4:words:5:note":"きました","grammar:519:ex4:words:5:pos":"verb","grammar:519:ex4:points:0":"仕事のチャンス: a job opportunity.","grammar:519:ex4:points:1":"チャンスが来る: a chance comes.","grammar:519:ex5:trans":"If you try harder, chances increase.","grammar:519:ex5:structure":"〜ば〜が増えます","grammar:519:ex5:words:0:zh":"more","grammar:519:ex5:words:0:pos":"adverb","grammar:519:ex5:words:1:zh":"if you try hard","grammar:519:ex5:words:1:note":"がんばれば","grammar:519:ex5:words:1:pos":"verb","grammar:519:ex5:words:2:zh":"chance","grammar:519:ex5:words:2:note":"loanword","grammar:519:ex5:words:2:pos":"noun","grammar:519:ex5:words:3:zh":"(nominative)","grammar:519:ex5:words:3:pos":"particle","grammar:519:ex5:words:4:zh":"increase","grammar:519:ex5:words:4:note":"ふえます","grammar:519:ex5:words:4:pos":"verb","grammar:519:ex5:points:0":"〜ば: if … (頑張る → 頑張れば).","grammar:519:ex5:points:1":"増える: to increase (intransitive verb; the subject takes が)."},"522":{"example:522:exzh":"Let's talk about past events.","example:522:exzh2":"He's trying to forget the past.","example:522:exzh3":"Past experience is still useful now.","example:522:exzh4":"I like looking at old photos.","example:522:exzh5":"It's important to look back on the past."},"523":{"example:523:exzh":"This town is very quiet.","example:523:exzh2":"There's a restaurant in the center of town.","example:523:exzh3":"She moved to a new town.","example:523:exzh4":"I'm looking forward to the town festival.","example:523:exzh5":"There are many parks in the town.","grammar:523:ex:trans":"This town is very quiet.","grammar:523:ex:structure":"この＋noun＋は＋とても＋na-adjective＋です.","grammar:523:ex:explain":"This is a sentence with a na-adjective predicate, using a demonstrative and an adverb of degree. 「この＋noun」 means this…, and 「この町」 (this town) is presented as the topic with 「は」. 「とても」 (very) is an adverb of degree, and 「静か」 (quiet) is a na-adjective acting as the predicate with 「です」. The whole sentence means this town is very quiet. It is a typical sentence combining the previously learned 「この＋nounは」 and 「とても＋na-adjectiveです」, with a clear structure: demonstrative topic ＋ adverb of degree ＋ na-adjective predicate.","grammar:523:ex:words:0:zh":"this","grammar:523:ex:words:0:pos":"pre-noun adjectival","grammar:523:ex:words:1:zh":"town","grammar:523:ex:words:1:note":"まち","grammar:523:ex:words:1:pos":"noun","grammar:523:ex:words:2:zh":"(topic marker)","grammar:523:ex:words:2:pos":"particle","grammar:523:ex:words:3:zh":"extremely","grammar:523:ex:words:3:pos":"adverb","grammar:523:ex:words:4:zh":"quiet","grammar:523:ex:words:4:note":"しずか","grammar:523:ex:words:4:pos":"na-adjective","grammar:523:ex:words:5:zh":"(polite form)","grammar:523:ex:words:5:pos":"copula","grammar:523:ex:points:0":"とても静か: very quiet","grammar:523:ex:points:1":"na-adjective predicate + です","grammar:523:ex2:trans":"There is a restaurant in the center of town.","grammar:523:ex2:structure":"〔町の中心〕＋に＋noun＋が＋あります. 「町の中心」 = the center of town.","grammar:523:ex2:words:0:zh":"town","grammar:523:ex2:words:0:note":"まち","grammar:523:ex2:words:0:pos":"noun","grammar:523:ex2:words:1:zh":"'s","grammar:523:ex2:words:1:pos":"particle","grammar:523:ex2:words:2:zh":"center","grammar:523:ex2:words:2:note":"ちゅうしん","grammar:523:ex2:words:2:pos":"noun","grammar:523:ex2:words:3:zh":"(the place where something exists)","grammar:523:ex2:words:3:pos":"particle","grammar:523:ex2:words:4:zh":"restaurant","grammar:523:ex2:words:4:note":"loanword","grammar:523:ex2:words:4:pos":"noun","grammar:523:ex2:words:5:zh":"(nominative)","grammar:523:ex2:words:5:pos":"particle","grammar:523:ex2:words:6:zh":"there is / are","grammar:523:ex2:words:6:note":"exists / there is","grammar:523:ex2:words:6:pos":"verb","grammar:523:ex2:points:0":"〜の中心: the center of…","grammar:523:ex2:points:1":"placeに〜がある: there is … somewhere","grammar:523:ex3:trans":"She moved to a new town.","grammar:523:ex3:structure":"nounは＋〔新しい町〕＋に＋引っ越しました. 「〜に引っ越す」 = to move to…","grammar:523:ex3:words:0:zh":"she","grammar:523:ex3:words:0:note":"かのじょ","grammar:523:ex3:words:0:pos":"pronoun","grammar:523:ex3:words:1:zh":"(topic marker)","grammar:523:ex3:words:1:pos":"particle","grammar:523:ex3:words:2:zh":"new","grammar:523:ex3:words:2:note":"あたらしい","grammar:523:ex3:words:2:pos":"adjective","grammar:523:ex3:words:3:zh":"town","grammar:523:ex3:words:3:note":"まち","grammar:523:ex3:words:3:pos":"noun","grammar:523:ex3:words:4:zh":"(the destination)","grammar:523:ex3:words:4:pos":"particle","grammar:523:ex3:words:5:zh":"moved","grammar:523:ex3:words:5:note":"ひっこしました","grammar:523:ex3:words:5:pos":"verb","grammar:523:ex3:points:0":"〜に引っ越す: to move to… (に marks the destination)","grammar:523:ex3:points:1":"引っ越す: to move house","grammar:523:ex4:trans":"I'm looking forward to the town festival.","grammar:523:ex4:structure":"〔町の祭り〕＋が＋楽しみです. 「〜が楽しみです」 = to look forward to…","grammar:523:ex4:words:0:zh":"town","grammar:523:ex4:words:0:note":"まち","grammar:523:ex4:words:0:pos":"noun","grammar:523:ex4:words:1:zh":"'s","grammar:523:ex4:words:1:pos":"particle","grammar:523:ex4:words:2:zh":"festival","grammar:523:ex4:words:2:note":"まつり","grammar:523:ex4:words:2:pos":"noun","grammar:523:ex4:words:3:zh":"(nominative)","grammar:523:ex4:words:3:pos":"particle","grammar:523:ex4:words:4:zh":"looking forward to / enjoyment","grammar:523:ex4:words:4:note":"たのしみ","grammar:523:ex4:words:4:pos":"noun","grammar:523:ex4:words:5:zh":"(polite form)","grammar:523:ex4:words:5:pos":"copula","grammar:523:ex4:points:0":"〜が楽しみです: to look forward to…","grammar:523:ex4:points:1":"町の祭り: the town festival","grammar:523:ex5:trans":"There are many parks in the town.","grammar:523:ex5:structure":"placeには＋〔たくさんのnoun〕＋が＋あります. 「たくさんの」 modifies a noun and expresses a large quantity.","grammar:523:ex5:words:0:zh":"town","grammar:523:ex5:words:0:note":"まち","grammar:523:ex5:words:0:pos":"noun","grammar:523:ex5:words:1:zh":"(the place where something exists)","grammar:523:ex5:words:1:pos":"particle","grammar:523:ex5:words:2:zh":"(emphasis)","grammar:523:ex5:words:2:pos":"particle","grammar:523:ex5:words:3:zh":"a lot","grammar:523:ex5:words:3:pos":"adverb","grammar:523:ex5:words:4:zh":"'s","grammar:523:ex5:words:4:pos":"particle","grammar:523:ex5:words:5:zh":"park","grammar:523:ex5:words:5:note":"こうえん","grammar:523:ex5:words:5:pos":"noun","grammar:523:ex5:words:6:zh":"(nominative)","grammar:523:ex5:words:6:pos":"particle","grammar:523:ex5:words:7:zh":"there is / are","grammar:523:ex5:words:7:note":"exists / there is","grammar:523:ex5:words:7:pos":"verb","grammar:523:ex5:points:0":"たくさんの＋noun: many…","grammar:523:ex5:points:1":"町には〜がある: there is … in the town","exam:523:zh":"The small town where I live has one station and lots of schools, shops and houses.","exam:523:why":"An area to live in that has a station, schools, shops and houses can be called a 「町」. 「公園」 is a place for people to relax, which doesn't fit the description of a whole settlement."},"525":{"example:525:exzh":"This project was a complete success.","example:525:exzh2":"His explanation was complete.","example:525:exzh3":"It wasn't perfect, but the result was good.","example:525:exzh4":"Making a perfect plan is difficult.","example:525:exzh5":"It takes time to fully understand."},"526":{"example:526:exzh":"He's looking for a new job.","example:526:exzh2":"I'm studying in pursuit of knowledge.","example:526:exzh3":"She's traveling in pursuit of her dream.","example:526:exzh4":"To seek better results.","example:526:exzh5":"He's seeking stability."},"528":{"example:528:exzh":"A security guard came.","example:528:exzh2":"He works in security.","example:528:exzh3":"Security is strict.","example:528:exzh4":"Security has been strengthened at this building.","example:528:exzh5":"Security is needed for the event."},"529":{"example:529:exzh":"This movie is interesting.","example:529:exzh2":"His stories are always interesting.","example:529:exzh3":"I found an interesting book.","example:529:exzh4":"I'm playing a fun game.","example:529:exzh5":"That exhibition was interesting.","grammar:529:ex:trans":"This movie is interesting.","grammar:529:ex:structure":"〜は面白いです","grammar:529:ex:explain":"This is an i-adjective predicate sentence, 「〜は面白いです」. 「面白い（おもしろい）」 is an i-adjective meaning interesting or fun, and as a predicate it takes 「です」 directly to become the polite form. 「この映画は」 at the front uses 「は」 to mark the topic, this movie. The whole sentence means this movie is interesting. This is the most basic pattern for describing what something is like: topic は + i-adjective + です. Remember that an i-adjective such as 面白い already contains its own ending, so you simply add 「です」 — unlike a na-adjective, which structurally needs a connector.","grammar:529:ex:words:0:zh":"this","grammar:529:ex:words:0:pos":"pre-noun adjectival","grammar:529:ex:words:1:zh":"movie","grammar:529:ex:words:1:note":"えいが","grammar:529:ex:words:1:pos":"noun","grammar:529:ex:words:2:zh":"(topic)","grammar:529:ex:words:2:pos":"particle","grammar:529:ex:words:3:zh":"interesting","grammar:529:ex:words:3:note":"おもしろい","grammar:529:ex:words:3:pos":"adjective","grammar:529:ex:words:4:zh":"(polite form)","grammar:529:ex:words:4:pos":"copula","grammar:529:ex:points:0":"❗面白い（おもしろい）: interesting, fun.","grammar:529:ex:points:1":"この映画: this movie.","grammar:529:ex2:trans":"His stories are always interesting.","grammar:529:ex2:structure":"〜はいつも面白い","grammar:529:ex2:words:0:zh":"he","grammar:529:ex2:words:0:note":"かれ","grammar:529:ex2:words:0:pos":"pronoun","grammar:529:ex2:words:1:zh":"'s","grammar:529:ex2:words:1:pos":"particle","grammar:529:ex2:words:2:zh":"story","grammar:529:ex2:words:2:note":"はなし","grammar:529:ex2:words:2:pos":"noun","grammar:529:ex2:words:3:zh":"(topic)","grammar:529:ex2:words:3:pos":"particle","grammar:529:ex2:words:4:zh":"always","grammar:529:ex2:words:4:pos":"adverb","grammar:529:ex2:words:5:zh":"interesting","grammar:529:ex2:words:5:note":"おもしろい","grammar:529:ex2:words:5:pos":"adjective","grammar:529:ex2:points:0":"彼の話: his talk / his stories.","grammar:529:ex2:points:1":"いつも面白い: always interesting.","grammar:529:ex3:trans":"I found an interesting book.","grammar:529:ex3:structure":"面白い〜を見つけました","grammar:529:ex3:words:0:zh":"interesting","grammar:529:ex3:words:0:note":"おもしろい","grammar:529:ex3:words:0:pos":"adjective","grammar:529:ex3:words:1:zh":"book","grammar:529:ex3:words:1:note":"ほん","grammar:529:ex3:words:1:pos":"noun","grammar:529:ex3:words:2:zh":"(object marker)","grammar:529:ex3:words:2:pos":"particle","grammar:529:ex3:words:3:zh":"found","grammar:529:ex3:words:3:note":"みつけました","grammar:529:ex3:words:3:pos":"verb","grammar:529:ex3:points:0":"面白い本: an interesting book.","grammar:529:ex3:points:1":"見つける: to find.","grammar:529:ex4:trans":"I'm playing an interesting game.","grammar:529:ex4:structure":"〜をしています","grammar:529:ex4:words:0:zh":"interesting","grammar:529:ex4:words:0:note":"おもしろい","grammar:529:ex4:words:0:pos":"adjective","grammar:529:ex4:words:1:zh":"game","grammar:529:ex4:words:1:note":"loanword","grammar:529:ex4:words:1:pos":"noun","grammar:529:ex4:words:2:zh":"(object marker)","grammar:529:ex4:words:2:pos":"particle","grammar:529:ex4:words:3:zh":"is doing","grammar:529:ex4:words:3:pos":"verb","grammar:529:ex4:points:0":"❗ゲームをする: play a game.","grammar:529:ex4:points:1":"面白いゲーム: an interesting game.","grammar:529:ex5:trans":"That exhibition was interesting.","grammar:529:ex5:structure":"〜は面白かった","grammar:529:ex5:words:0:zh":"that","grammar:529:ex5:words:0:pos":"pre-noun adjectival","grammar:529:ex5:words:1:zh":"exhibition","grammar:529:ex5:words:1:note":"てんらんかい","grammar:529:ex5:words:1:pos":"noun","grammar:529:ex5:words:2:zh":"(topic)","grammar:529:ex5:words:2:pos":"particle","grammar:529:ex5:words:3:zh":"(past) was interesting","grammar:529:ex5:words:3:note":"おもしろかった","grammar:529:ex5:words:3:pos":"adjective","grammar:529:ex5:points:0":"❗展覧会: exhibition.","grammar:529:ex5:points:1":"面白かった: was interesting (past).","exam:529:zh":"This movie is interesting, so it's fun no matter how many times I watch it.","exam:529:why":"「面白い」 means interesting, which matches 「何度見ても楽しい」. 「忙しい」 means busy, so it can't express that a movie's content is interesting."},"530":{"example:530:exzh":"The weather has been nice lately.","example:530:exzh2":"Do you know the latest news?","example:530:exzh3":"I've been busy lately.","example:530:exzh4":"Recent survey results have been published.","example:530:exzh5":"I've been meeting friends lately.","grammar:530:ex:trans":"The weather has been nice lately.","grammar:530:ex:structure":"最近、〜がいいです","grammar:530:ex:explain":"This is an adjective-predicate sentence, and the key point is how 「が」 is used. In expressions like 「天気がいい」 (the weather is good) that describe how some attribute is doing, the subject 「天気」 is marked with 「が」. The word at the front, 「最近（さいきん）」, is the time word \"lately,\" and the comma after it leads into the main clause. 「いい」 is the i-adjective meaning \"good\" (= 良い). The whole sentence means \"The weather has been nice lately.\" Note that when you say something like \"the weather is good\" or \"someone is in a good mood\"—describing how some attribute stands—the subject of that attribute customarily takes 「が」. This works the same way as 「運が良い」 and 「気分がいい」 above.","grammar:530:ex:words:0:zh":"lately","grammar:530:ex:words:0:note":"さいきん","grammar:530:ex:words:0:pos":"adverb","grammar:530:ex:words:1:zh":"weather","grammar:530:ex:words:1:note":"てんき","grammar:530:ex:words:1:pos":"noun","grammar:530:ex:words:2:zh":"(nominative)","grammar:530:ex:words:2:pos":"particle","grammar:530:ex:words:3:zh":"good","grammar:530:ex:words:3:pos":"adjective","grammar:530:ex:words:4:zh":"(polite form)","grammar:530:ex:words:4:pos":"copula","grammar:530:ex:points:0":"最近（さいきん）: lately.","grammar:530:ex:points:1":"天気がいい: the weather is good (the subject takes が).","grammar:530:ex2:trans":"Do you know the latest news?","grammar:530:ex2:structure":"〜を知っていますか","grammar:530:ex2:words:0:zh":"lately","grammar:530:ex2:words:0:note":"さいきん","grammar:530:ex2:words:0:pos":"noun","grammar:530:ex2:words:1:zh":"'s","grammar:530:ex2:words:1:pos":"particle","grammar:530:ex2:words:2:zh":"news","grammar:530:ex2:words:2:note":"loanword","grammar:530:ex2:words:2:pos":"noun","grammar:530:ex2:words:3:zh":"(object marker)","grammar:530:ex2:words:3:pos":"particle","grammar:530:ex2:words:4:zh":"know","grammar:530:ex2:words:4:note":"しっています","grammar:530:ex2:words:4:pos":"verb","grammar:530:ex2:words:5:zh":"(question)","grammar:530:ex2:words:5:pos":"particle","grammar:530:ex2:points:0":"最近のニュース: the latest news.","grammar:530:ex2:points:1":"知っていますか: do you know?","grammar:530:ex3:trans":"I've been busy lately.","grammar:530:ex3:structure":"最近、〜です","grammar:530:ex3:words:0:zh":"lately","grammar:530:ex3:words:0:note":"さいきん","grammar:530:ex3:words:0:pos":"adverb","grammar:530:ex3:words:1:zh":"busy","grammar:530:ex3:words:1:note":"いそがしい","grammar:530:ex3:words:1:pos":"adjective","grammar:530:ex3:words:2:zh":"(polite form)","grammar:530:ex3:words:2:pos":"copula","grammar:530:ex3:points:0":"最近忙しい: I've been busy lately.","grammar:530:ex3:points:1":"忙しい: busy.","grammar:530:ex4:trans":"The results of the recent survey have been announced.","grammar:530:ex4:structure":"〜が公表されました","grammar:530:ex4:words:0:zh":"lately","grammar:530:ex4:words:0:note":"さいきん","grammar:530:ex4:words:0:pos":"noun","grammar:530:ex4:words:1:zh":"'s","grammar:530:ex4:words:1:pos":"particle","grammar:530:ex4:words:2:zh":"survey results","grammar:530:ex4:words:2:note":"ちょうさけっか","grammar:530:ex4:words:2:pos":"noun","grammar:530:ex4:words:3:zh":"(nominative)","grammar:530:ex4:words:3:pos":"particle","grammar:530:ex4:words:4:zh":"be announced","grammar:530:ex4:words:4:note":"こうひょうされました (passive form)","grammar:530:ex4:words:4:pos":"verb","grammar:530:ex4:points:0":"公表される: to be announced (passive form).","grammar:530:ex4:points:1":"調査結果: survey results.","grammar:530:ex5:trans":"I've been meeting friends lately.","grammar:530:ex5:structure":"〜と会っています","grammar:530:ex5:words:0:zh":"lately","grammar:530:ex5:words:0:note":"さいきん","grammar:530:ex5:words:0:pos":"adverb","grammar:530:ex5:words:1:zh":"friend","grammar:530:ex5:words:1:note":"ともだち","grammar:530:ex5:words:1:pos":"noun","grammar:530:ex5:words:2:zh":"with","grammar:530:ex5:words:2:pos":"particle","grammar:530:ex5:words:3:zh":"be meeting","grammar:530:ex5:words:3:note":"あっています","grammar:530:ex5:words:3:pos":"verb","grammar:530:ex5:points:0":"〜と会う: to meet with … (the person you meet 会う takes と／に).","grammar:530:ex5:points:1":"〜ている: (continuing recently)."},"531":{"example:531:exzh":"He appeared in court.","example:531:exzh2":"The results of the trial were announced.","example:531:exzh3":"This case will go to trial.","example:531:exzh4":"I testified in court.","example:531:exzh5":"I'm waiting for the trial to end."},"532":{"example:532:exzh":"He can't understand at all.","example:532:exzh2":"No problem at all.","example:532:exzh3":"She's not interested at all.","example:532:exzh4":"Completely different.","example:532:exzh5":"This is a completely new idea."},"533":{"example:533:exzh":"Please go straight down this street.","example:533:exzh2":"Is it the way I said?","example:533:exzh3":"Things are going according to plan.","example:533:exzh4":"Let's meet on that street.","example:533:exzh5":"If you do as he says, it'll be fine.","grammar:533:ex:trans":"Please go straight down this street.","grammar:533:ex:structure":"〜をまっすぐ進んでください","grammar:533:ex:explain":"The key point here is the particle 「を」 marking the path of movement. When the verb 「進む」 (to go forward) is used with a route of movement, the road you pass along is marked with 「を」: 「通りを進む」 means \"go along this street,\" and here 「を」 is not an object marker but marks the place you move through. 「まっすぐ」 (straight) is an adverb modifying the direction. The ending 「進んでください」 is a request. The whole sentence means \"Please go straight along this street.\" Intransitive verbs of passing or going through a place (進む, 歩く, 渡る) commonly take 「を」 for the route.","grammar:533:ex:words:0:zh":"this","grammar:533:ex:words:0:pos":"pre-noun adjectival","grammar:533:ex:words:1:zh":"street","grammar:533:ex:words:1:note":"とおり","grammar:533:ex:words:1:pos":"noun","grammar:533:ex:words:2:zh":"(path)","grammar:533:ex:words:2:pos":"particle","grammar:533:ex:words:3:zh":"straight","grammar:533:ex:words:3:pos":"adverb","grammar:533:ex:words:4:zh":"move forward","grammar:533:ex:words:4:note":"すすんで","grammar:533:ex:words:4:pos":"verb","grammar:533:ex:words:5:zh":"please","grammar:533:ex:words:5:pos":"auxiliary verb","grammar:533:ex:points:0":"❓通りを進む: to go along the street (the route takes を).","grammar:533:ex:points:1":"まっすぐ: straight.","grammar:533:ex2:trans":"Is it the way I said?","grammar:533:ex2:structure":"〜通りですか","grammar:533:ex2:words:0:zh":"I","grammar:533:ex2:words:0:note":"わたし","grammar:533:ex2:words:0:pos":"pronoun","grammar:533:ex2:words:1:zh":"'s","grammar:533:ex2:words:1:pos":"particle","grammar:533:ex2:words:2:zh":"said","grammar:533:ex2:words:2:note":"いった","grammar:533:ex2:words:2:pos":"verb","grammar:533:ex2:words:3:zh":"according to","grammar:533:ex2:words:3:note":"とおり","grammar:533:ex2:words:3:pos":"noun","grammar:533:ex2:words:4:zh":"is","grammar:533:ex2:words:4:pos":"copula","grammar:533:ex2:words:5:zh":"(question)","grammar:533:ex2:words:5:pos":"particle","grammar:533:ex2:points:0":"❗〜通り: just as …, in accordance with … (言った通り = just as (someone) said).","grammar:533:ex2:points:1":"通り is read とおり.","grammar:533:ex3:trans":"It's proceeding according to plan.","grammar:533:ex3:structure":"予定通りに＋進んでいます","grammar:533:ex3:words:0:zh":"as scheduled","grammar:533:ex3:words:0:note":"よていどおり; exactly as planned","grammar:533:ex3:words:0:pos":"noun","grammar:533:ex3:words:1:zh":"adverbial marker","grammar:533:ex3:words:1:pos":"particle","grammar:533:ex3:words:2:zh":"carry out","grammar:533:ex3:words:2:note":"すすんで; te-form","grammar:533:ex3:words:2:pos":"verb","grammar:533:ex3:words:3:zh":"in progress","grammar:533:ex3:words:3:pos":"auxiliary verb","grammar:533:ex3:points:0":"「予定通り」 means following the original plan; here 「通り」 is read 「どおり」 because of sequential voicing.","grammar:533:ex3:points:1":"「進んでいます」 shows that things are in progress.","grammar:533:ex4:trans":"Let's meet on that street.","grammar:533:ex4:structure":"〜で会いましょう","grammar:533:ex4:words:0:zh":"that","grammar:533:ex4:words:0:pos":"pre-noun adjectival","grammar:533:ex4:words:1:zh":"street","grammar:533:ex4:words:1:note":"とおり","grammar:533:ex4:words:1:pos":"noun","grammar:533:ex4:words:2:zh":"(place)","grammar:533:ex4:words:2:pos":"particle","grammar:533:ex4:words:3:zh":"let's meet","grammar:533:ex4:words:3:note":"あいましょう","grammar:533:ex4:words:3:pos":"verb","grammar:533:ex4:points:0":"通り: street; 〜で会う: to meet at …","grammar:533:ex4:points:1":"会う → 会いましょう: a suggestion.","grammar:533:ex5:trans":"It'll be fine if you do as he says.","grammar:533:ex5:structure":"〜通りにすれば大丈夫です","grammar:533:ex5:words:0:zh":"he","grammar:533:ex5:words:0:note":"かれ","grammar:533:ex5:words:0:pos":"pronoun","grammar:533:ex5:words:1:zh":"(nominative)","grammar:533:ex5:words:1:pos":"particle","grammar:533:ex5:words:2:zh":"tell","grammar:533:ex5:words:2:note":"いう","grammar:533:ex5:words:2:pos":"verb","grammar:533:ex5:words:3:zh":"according to","grammar:533:ex5:words:3:note":"とおり","grammar:533:ex5:words:3:pos":"noun","grammar:533:ex5:words:4:zh":"(made adverbial)","grammar:533:ex5:words:4:pos":"particle","grammar:533:ex5:words:5:zh":"if you do","grammar:533:ex5:words:5:pos":"verb","grammar:533:ex5:words:6:zh":"it's fine","grammar:533:ex5:words:6:pos":"na-adjective","grammar:533:ex5:words:7:zh":"(polite form)","grammar:533:ex5:words:7:pos":"copula","grammar:533:ex5:points:0":"〜通りにする: to do as …","grammar:533:ex5:points:1":"〜ば: if … (する → すれば)."},"534":{"example:534:exzh":"He sacrificed himself for it.","example:534:exzh2":"Sometimes sacrifice is necessary.","example:534:exzh3":"It's a success won through sacrifice.","example:534:exzh4":"I'm grateful for the sacrifice.","example:534:exzh5":"The many sacrifices paid off."},"535":{"example:535:exzh":"It rained yesterday.","example:535:exzh2":"I met a friend yesterday.","example:535:exzh3":"Yesterday's event was fun.","example:535:exzh4":"Work finished late yesterday.","example:535:exzh5":"Yesterday's dinner was delicious.","grammar:535:ex:trans":"It rained yesterday.","grammar:535:ex:structure":"昨日は〜ました","grammar:535:ex:explain":"This sentence uses the fixed collocation 「雨が降る」 (it rains). For weather phenomena such as rain and snow, the verb 「降る」 is used, the subject 「雨」 is marked with 「が」, and the polite past form is 「降りました」. At the front, 「昨日は」 uses 「は」 to present \"yesterday\" as the topic. The key word 「昨日（きのう）」 means yesterday. The whole sentence means \"It rained yesterday.\" Remember that Japanese says 「雨が降る」 for \"it rains,\" marking the rain with 「が」 and using the verb 「降る」; this is the most basic fixed pattern for describing weather.","grammar:535:ex:words:0:zh":"yesterday","grammar:535:ex:words:0:note":"きのう","grammar:535:ex:words:0:pos":"noun","grammar:535:ex:words:1:zh":"(topic)","grammar:535:ex:words:1:pos":"particle","grammar:535:ex:words:2:zh":"rain","grammar:535:ex:words:2:note":"あめ","grammar:535:ex:words:2:pos":"noun","grammar:535:ex:words:3:zh":"(nominative)","grammar:535:ex:words:3:pos":"particle","grammar:535:ex:words:4:zh":"fell","grammar:535:ex:words:4:note":"ふりました","grammar:535:ex:words:4:pos":"verb","grammar:535:ex:points:0":"昨日（きのう）: yesterday.","grammar:535:ex:points:1":"雨が降る: it rains; 降る → 降りました (past).","grammar:535:ex2:trans":"I met a friend yesterday.","grammar:535:ex2:structure":"昨日、〜に会いました","grammar:535:ex2:words:0:zh":"yesterday","grammar:535:ex2:words:0:note":"きのう","grammar:535:ex2:words:0:pos":"noun","grammar:535:ex2:words:1:zh":"friend","grammar:535:ex2:words:1:note":"ともだち","grammar:535:ex2:words:1:pos":"noun","grammar:535:ex2:words:2:zh":"(object)","grammar:535:ex2:words:2:pos":"particle","grammar:535:ex2:words:3:zh":"met","grammar:535:ex2:words:3:note":"あいました","grammar:535:ex2:words:3:pos":"verb","grammar:535:ex2:points:0":"友達に会う: to meet a friend (the object of 会う takes に).","grammar:535:ex2:points:1":"会う → 会いました.","grammar:535:ex3:trans":"Yesterday's event was fun.","grammar:535:ex3:structure":"〜は楽しかったです","grammar:535:ex3:words:0:zh":"yesterday","grammar:535:ex3:words:0:note":"きのう","grammar:535:ex3:words:0:pos":"noun","grammar:535:ex3:words:1:zh":"'s","grammar:535:ex3:words:1:pos":"particle","grammar:535:ex3:words:2:zh":"event","grammar:535:ex3:words:2:note":"loanword","grammar:535:ex3:words:2:pos":"noun","grammar:535:ex3:words:3:zh":"(topic)","grammar:535:ex3:words:3:pos":"particle","grammar:535:ex3:words:4:zh":"(past) was fun","grammar:535:ex3:words:4:note":"たのしかった","grammar:535:ex3:words:4:pos":"adjective","grammar:535:ex3:words:5:zh":"(polite form)","grammar:535:ex3:words:5:pos":"copula","grammar:535:ex3:points:0":"昨日のイベント: yesterday's event.","grammar:535:ex3:points:1":"楽しかった: was fun (past form of an i-adjective).","grammar:535:ex4:trans":"Work finished late yesterday.","grammar:535:ex4:structure":"〜が遅く終わりました","grammar:535:ex4:words:0:zh":"yesterday","grammar:535:ex4:words:0:note":"きのう","grammar:535:ex4:words:0:pos":"noun","grammar:535:ex4:words:1:zh":"work","grammar:535:ex4:words:1:note":"しごと","grammar:535:ex4:words:1:pos":"noun","grammar:535:ex4:words:2:zh":"(nominative)","grammar:535:ex4:words:2:pos":"particle","grammar:535:ex4:words:3:zh":"late (adverb)","grammar:535:ex4:words:3:note":"おそく","grammar:535:ex4:words:3:pos":"adverb","grammar:535:ex4:words:4:zh":"finished","grammar:535:ex4:words:4:note":"おわりました","grammar:535:ex4:words:4:pos":"verb","grammar:535:ex4:points:0":"遅く終わる: to end late.","grammar:535:ex4:points:1":"終わる: to end (intransitive verb; the subject takes が).","grammar:535:ex5:trans":"Yesterday's dinner was delicious.","grammar:535:ex5:structure":"〜は美味しかった","grammar:535:ex5:words:0:zh":"yesterday","grammar:535:ex5:words:0:note":"きのう","grammar:535:ex5:words:0:pos":"noun","grammar:535:ex5:words:1:zh":"'s","grammar:535:ex5:words:1:pos":"particle","grammar:535:ex5:words:2:zh":"dinner","grammar:535:ex5:words:2:note":"ゆうしょく","grammar:535:ex5:words:2:pos":"noun","grammar:535:ex5:words:3:zh":"(topic)","grammar:535:ex5:words:3:pos":"particle","grammar:535:ex5:words:4:zh":"(past) was delicious","grammar:535:ex5:words:4:note":"おいしかった","grammar:535:ex5:words:4:pos":"adjective","grammar:535:ex5:points:0":"昨日の夕食: yesterday's dinner.","grammar:535:ex5:points:1":"美味しかった: was delicious (past).","exam:535:zh":"Today is Tuesday, so yesterday was Monday.","exam:535:why":"「昨日」 is yesterday, and the day before Tuesday is Monday. 「明日」 is tomorrow, which should be Wednesday."},"536":{"example:536:exzh":"He's about ten years old.","example:536:exzh2":"This job takes about an hour.","example:536:exzh3":"Let's meet around five today.","example:536:exzh4":"This room can hold about ten people.","example:536:exzh5":"Plants grow in about two months.","grammar:536:ex:trans":"He is about ten years old.","grammar:536:ex:structure":"〜ぐらいです","grammar:536:ex:explain":"The key point of this sentence is 「〜ぐらい／くらい」 (about, around). It follows a quantity word to show an approximate number or an estimate, so 「十歳ぐらい」 means about ten years old. The sentence-ending 「です」 states it as a judgment. 「彼は」 at the front marks the topic. The whole sentence means he is about ten years old. 「ぐらい」 and 「くらい」 mean the same thing and are interchangeable, used to express an imprecise quantity or degree. Distinguish it from 「しか」 and 「だけ」, which express limits: 「ぐらい」 simply marks a rough estimate of quantity, and it is a common word for estimating age, time, or amount.","grammar:536:ex:words:0:zh":"he","grammar:536:ex:words:0:note":"かれ","grammar:536:ex:words:0:pos":"pronoun","grammar:536:ex:words:1:zh":"(topic)","grammar:536:ex:words:1:pos":"particle","grammar:536:ex:words:2:zh":"ten years old","grammar:536:ex:words:2:note":"じゅっさい","grammar:536:ex:words:2:pos":"noun","grammar:536:ex:words:3:zh":"about","grammar:536:ex:words:3:pos":"particle","grammar:536:ex:words:4:zh":"(polite form)","grammar:536:ex:words:4:pos":"copula","grammar:536:ex:points:0":"❗〜ぐらい／くらい: about, around (an estimate).","grammar:536:ex:points:1":"十歳ぐらい: about ten years old.","grammar:536:ex2:trans":"This job takes about an hour.","grammar:536:ex2:structure":"〜ぐらいかかります","grammar:536:ex2:words:0:zh":"this","grammar:536:ex2:words:0:pos":"pre-noun adjectival","grammar:536:ex2:words:1:zh":"work","grammar:536:ex2:words:1:note":"しごと","grammar:536:ex2:words:1:pos":"noun","grammar:536:ex2:words:2:zh":"(object)","grammar:536:ex2:words:2:pos":"particle","grammar:536:ex2:words:3:zh":"(contrast)","grammar:536:ex2:words:3:pos":"particle","grammar:536:ex2:words:4:zh":"one hour","grammar:536:ex2:words:4:note":"いちじかん","grammar:536:ex2:words:4:pos":"noun","grammar:536:ex2:words:5:zh":"about","grammar:536:ex2:words:5:pos":"particle","grammar:536:ex2:words:6:zh":"to take (time)","grammar:536:ex2:words:6:pos":"verb","grammar:536:ex2:points:0":"一時間ぐらい: about an hour.","grammar:536:ex2:points:1":"〜に時間がかかる: to take time.","grammar:536:ex3:trans":"Let's meet around five today.","grammar:536:ex3:structure":"〜ぐらいに会いましょう","grammar:536:ex3:words:0:zh":"today","grammar:536:ex3:words:0:note":"きょう","grammar:536:ex3:words:0:pos":"noun","grammar:536:ex3:words:1:zh":"(topic)","grammar:536:ex3:words:1:pos":"particle","grammar:536:ex3:words:2:zh":"five o'clock","grammar:536:ex3:words:2:note":"ごじ","grammar:536:ex3:words:2:pos":"noun","grammar:536:ex3:words:3:zh":"about","grammar:536:ex3:words:3:pos":"particle","grammar:536:ex3:words:4:zh":"(point in time)","grammar:536:ex3:words:4:pos":"particle","grammar:536:ex3:words:5:zh":"let's meet","grammar:536:ex3:words:5:pos":"verb","grammar:536:ex3:points:0":"❗〜ぐらいに: around … (a point in time).","grammar:536:ex3:points:1":"五時ぐらい: around five.","grammar:536:ex4:trans":"This room can hold about ten people.","grammar:536:ex4:structure":"〜ぐらい入れます","grammar:536:ex4:words:0:zh":"this","grammar:536:ex4:words:0:pos":"pre-noun adjectival","grammar:536:ex4:words:1:zh":"room","grammar:536:ex4:words:1:note":"へや","grammar:536:ex4:words:1:pos":"noun","grammar:536:ex4:words:2:zh":"(topic)","grammar:536:ex4:words:2:pos":"particle","grammar:536:ex4:words:3:zh":"ten people","grammar:536:ex4:words:3:note":"じゅうにん","grammar:536:ex4:words:3:pos":"noun","grammar:536:ex4:words:4:zh":"about","grammar:536:ex4:words:4:pos":"particle","grammar:536:ex4:words:5:zh":"can hold","grammar:536:ex4:words:5:note":"はいれます","grammar:536:ex4:words:5:pos":"verb","grammar:536:ex4:points:0":"❗入れる: to let in, to hold (the potential form of 入る).","grammar:536:ex4:points:1":"十人ぐらい: about ten people.","grammar:536:ex5:trans":"Plants grow in about two months.","grammar:536:ex5:structure":"〜ぐらいで〜します","grammar:536:ex5:words:0:zh":"plant","grammar:536:ex5:words:0:note":"しょくぶつ","grammar:536:ex5:words:0:pos":"noun","grammar:536:ex5:words:1:zh":"(topic)","grammar:536:ex5:words:1:pos":"particle","grammar:536:ex5:words:2:zh":"two months","grammar:536:ex5:words:2:note":"にかげつ","grammar:536:ex5:words:2:pos":"noun","grammar:536:ex5:words:3:zh":"about","grammar:536:ex5:words:3:pos":"particle","grammar:536:ex5:words:4:zh":"(period)","grammar:536:ex5:words:4:pos":"particle","grammar:536:ex5:words:5:zh":"grow","grammar:536:ex5:words:5:pos":"verb","grammar:536:ex5:points:0":"❗〜ぐらいで: in about … (a time span).","grammar:536:ex5:points:1":"二ヶ月ぐらい: about two months."},"537":{"example:537:exzh":"This system is very convenient.","example:537:exzh2":"A new system was introduced.","example:537:exzh3":"A system problem occurred.","example:537:exzh4":"This system is used by many people.","example:537:exzh5":"The system needs to be updated."},"538":{"example:538:exzh":"Class starts at nine.","example:538:exzh2":"The event is scheduled to start.","example:538:exzh3":"A new life has begun.","example:538:exzh4":"Tell me what time it starts.","example:538:exzh5":"Please review before the exam starts.","grammar:538:ex:trans":"The class starts at nine.","grammar:538:ex:structure":"〜に始まります","grammar:538:ex:explain":"This sentence demonstrates the difference between transitive and intransitive verbs, the key point being 「始まる」. 「始まる」 is an intransitive verb meaning that something starts by itself, and its subject takes 「が」; here 「授業」 (the class) starts on its own, so 「始まる」 is used, in the polite form 「始まります」. In contrast, 「始める」 is a transitive verb meaning \"(a person) starts something.\" The time 「九時に」 is marked with 「に」. The whole sentence means \"The class starts at nine.\" To choose between them, ask whether the thing starts by itself (始まる) or a person actively starts it (始める).","grammar:538:ex:words:0:zh":"class","grammar:538:ex:words:0:note":"じゅぎょう","grammar:538:ex:words:0:pos":"noun","grammar:538:ex:words:1:zh":"(topic)","grammar:538:ex:words:1:pos":"particle","grammar:538:ex:words:2:zh":"nine o'clock","grammar:538:ex:words:2:note":"くじ","grammar:538:ex:words:2:pos":"noun","grammar:538:ex:words:3:zh":"(point in time)","grammar:538:ex:words:3:pos":"particle","grammar:538:ex:words:4:zh":"begins","grammar:538:ex:words:4:note":"はじまります","grammar:538:ex:words:4:pos":"verb","grammar:538:ex:points:0":"❗始まる (intransitive verb: to begin) vs 始める (transitive verb: to begin …).","grammar:538:ex:points:1":"九時に: at nine (time + に).","grammar:538:ex2:trans":"The event is scheduled to begin.","grammar:538:ex2:structure":"〜が始まる予定です","grammar:538:ex2:words:0:zh":"event","grammar:538:ex2:words:0:note":"loanword","grammar:538:ex2:words:0:pos":"noun","grammar:538:ex2:words:1:zh":"(nominative)","grammar:538:ex2:words:1:pos":"particle","grammar:538:ex2:words:2:zh":"begins","grammar:538:ex2:words:2:note":"はじまる","grammar:538:ex2:words:2:pos":"verb","grammar:538:ex2:words:3:zh":"plan","grammar:538:ex2:words:3:note":"よてい","grammar:538:ex2:words:3:pos":"noun","grammar:538:ex2:words:4:zh":"(polite form)","grammar:538:ex2:words:4:pos":"copula","grammar:538:ex2:points:0":"〜予定です: is scheduled to…","grammar:538:ex2:points:1":"始まる: to begin (intransitive verb).","grammar:538:ex3:trans":"A new life began.","grammar:538:ex3:structure":"〜が始まった","grammar:538:ex3:words:0:zh":"new","grammar:538:ex3:words:0:note":"あたらしい","grammar:538:ex3:words:0:pos":"adjective","grammar:538:ex3:words:1:zh":"life","grammar:538:ex3:words:1:note":"せいかつ","grammar:538:ex3:words:1:pos":"noun","grammar:538:ex3:words:2:zh":"(nominative)","grammar:538:ex3:words:2:pos":"particle","grammar:538:ex3:words:3:zh":"started","grammar:538:ex3:words:3:note":"はじまった","grammar:538:ex3:words:3:pos":"verb","grammar:538:ex3:points:0":"新しい生活が始まる: a new life begins.","grammar:538:ex3:points:1":"始まる → 始まった (plain past).","grammar:538:ex4:trans":"Tell me what time it starts.","grammar:538:ex4:structure":"〜のか教えて","grammar:538:ex4:words:0:zh":"what time","grammar:538:ex4:words:0:note":"なんじ","grammar:538:ex4:words:0:pos":"question word","grammar:538:ex4:words:1:zh":"(point in time)","grammar:538:ex4:words:1:pos":"particle","grammar:538:ex4:words:2:zh":"begins","grammar:538:ex4:words:2:note":"はじまる","grammar:538:ex4:words:2:pos":"verb","grammar:538:ex4:words:3:zh":"(question)","grammar:538:ex4:words:3:pos":"particle","grammar:538:ex4:words:4:zh":"tell","grammar:538:ex4:words:4:note":"おしえて","grammar:538:ex4:words:4:pos":"verb","grammar:538:ex4:points:0":"〜のか教えて: tell me … (nominalized question).","grammar:538:ex4:points:1":"何時に始まる: what time it starts.","grammar:538:ex5:trans":"Please review before the exam starts.","grammar:538:ex5:structure":"〜前に〜てください","grammar:538:ex5:words:0:zh":"test","grammar:538:ex5:words:0:note":"しけん","grammar:538:ex5:words:0:pos":"noun","grammar:538:ex5:words:1:zh":"(nominative)","grammar:538:ex5:words:1:pos":"particle","grammar:538:ex5:words:2:zh":"begins","grammar:538:ex5:words:2:note":"はじまる","grammar:538:ex5:words:2:pos":"verb","grammar:538:ex5:words:3:zh":"before","grammar:538:ex5:words:3:note":"まえに","grammar:538:ex5:words:3:pos":"particle","grammar:538:ex5:words:4:zh":"review","grammar:538:ex5:words:4:note":"ふくしゅうして","grammar:538:ex5:words:4:pos":"verb","grammar:538:ex5:words:5:zh":"please","grammar:538:ex5:words:5:pos":"auxiliary verb","grammar:538:ex5:points:0":"❗〜前に: before … (dictionary form of a verb + 前に).","grammar:538:ex5:points:1":"復習する → 復習して + ください.","exam:538:zh":"Let's take our seats before the movie starts and watch it from the beginning.","exam:538:why":"To watch a movie from the beginning, you have to be seated before it 「始まる」. 「終わる」 means to end, and sitting down just before it ends wouldn't let you watch from the start."},"539":{"example:539:exzh":"He learned from failure.","example:539:exzh2":"Failure is the mother of success.","example:539:exzh3":"We're not afraid of failure.","example:539:exzh4":"This plan could fail.","example:539:exzh5":"Let's think about why it failed.","grammar:539:ex:trans":"He learned from failure.","grammar:539:ex:structure":"〜から学びました","grammar:539:ex:explain":"The key point here is the particle 「から」 marking source or starting point. 「〜から学ぶ」 means \"to learn from …,\" with 「から」 indicating where the learning comes from—its starting point. 「失敗から学ぶ」 is \"to learn from failure.\" The verb 「学ぶ」 (to learn) in the polite past is 「学びました」. At the front, 「彼は」 marks the topic, and 「失敗（しっぱい）」 means failure. The whole sentence means \"He learned from failure.\" Besides meaning \"because,\" 「から」 often marks \"from …\" (a starting point or source); this is the latter.","grammar:539:ex:words:0:zh":"he","grammar:539:ex:words:0:note":"かれ","grammar:539:ex:words:0:pos":"pronoun","grammar:539:ex:words:1:zh":"(topic)","grammar:539:ex:words:1:pos":"particle","grammar:539:ex:words:2:zh":"failure","grammar:539:ex:words:2:note":"しっぱい","grammar:539:ex:words:2:pos":"noun","grammar:539:ex:words:3:zh":"from","grammar:539:ex:words:3:pos":"particle","grammar:539:ex:words:4:zh":"learned","grammar:539:ex:words:4:note":"まなびました","grammar:539:ex:words:4:pos":"verb","grammar:539:ex:points:0":"〜から学ぶ: to learn from … (から marks the source).","grammar:539:ex:points:1":"失敗（しっぱい）: failure.","grammar:539:ex2:trans":"Failure is the mother of success.","grammar:539:ex2:structure":"〜は〜のもとです","grammar:539:ex2:words:0:zh":"failure","grammar:539:ex2:words:0:note":"しっぱい","grammar:539:ex2:words:0:pos":"noun","grammar:539:ex2:words:1:zh":"(topic)","grammar:539:ex2:words:1:pos":"particle","grammar:539:ex2:words:2:zh":"success","grammar:539:ex2:words:2:note":"せいこう","grammar:539:ex2:words:2:pos":"noun","grammar:539:ex2:words:3:zh":"'s","grammar:539:ex2:words:3:pos":"particle","grammar:539:ex2:words:4:zh":"source","grammar:539:ex2:words:4:pos":"noun","grammar:539:ex2:words:5:zh":"is","grammar:539:ex2:words:5:pos":"copula","grammar:539:ex2:points:0":"失敗は成功のもと: failure is the mother of success (proverb).","grammar:539:ex2:points:1":"もと: source, foundation.","grammar:539:ex3:trans":"We're not afraid of failure.","grammar:539:ex3:structure":"〜を恐れない","grammar:539:ex3:words:0:zh":"we","grammar:539:ex3:words:0:note":"わたしたち","grammar:539:ex3:words:0:pos":"pronoun","grammar:539:ex3:words:1:zh":"(topic)","grammar:539:ex3:words:1:pos":"particle","grammar:539:ex3:words:2:zh":"failure","grammar:539:ex3:words:2:note":"しっぱい","grammar:539:ex3:words:2:pos":"noun","grammar:539:ex3:words:3:zh":"(object marker)","grammar:539:ex3:words:3:pos":"particle","grammar:539:ex3:words:4:zh":"not afraid of","grammar:539:ex3:words:4:note":"おそれない","grammar:539:ex3:words:4:pos":"verb","grammar:539:ex3:points:0":"失敗を恐れる: to be afraid of failure.","grammar:539:ex3:points:1":"恐れる → 恐れない (plain negative).","grammar:539:ex4:trans":"This plan may fail.","grammar:539:ex4:structure":"〜可能性があります","grammar:539:ex4:words:0:zh":"this","grammar:539:ex4:words:0:pos":"pre-noun adjectival","grammar:539:ex4:words:1:zh":"plan","grammar:539:ex4:words:1:note":"けいかく","grammar:539:ex4:words:1:pos":"noun","grammar:539:ex4:words:2:zh":"(topic)","grammar:539:ex4:words:2:pos":"particle","grammar:539:ex4:words:3:zh":"failure","grammar:539:ex4:words:3:note":"しっぱいする","grammar:539:ex4:words:3:pos":"verb","grammar:539:ex4:words:4:zh":"possibility","grammar:539:ex4:words:4:note":"かのうせい","grammar:539:ex4:words:4:pos":"noun","grammar:539:ex4:words:5:zh":"(nominative)","grammar:539:ex4:words:5:pos":"particle","grammar:539:ex4:words:6:zh":"there is / are","grammar:539:ex4:words:6:pos":"verb","grammar:539:ex4:points:0":"失敗する: to fail (noun + する).","grammar:539:ex4:points:1":"〜可能性があります: there's a possibility that …","grammar:539:ex5:trans":"Let's think about why it failed.","grammar:539:ex5:structure":"〜を考えましょう","grammar:539:ex5:words:0:zh":"that failed","grammar:539:ex5:words:0:note":"しっぱいした","grammar:539:ex5:words:0:pos":"verb","grammar:539:ex5:words:1:zh":"reason","grammar:539:ex5:words:1:note":"りゆう","grammar:539:ex5:words:1:pos":"noun","grammar:539:ex5:words:2:zh":"(object marker)","grammar:539:ex5:words:2:pos":"particle","grammar:539:ex5:words:3:zh":"let's think","grammar:539:ex5:words:3:note":"かんがえましょう","grammar:539:ex5:words:3:pos":"verb","grammar:539:ex5:points:0":"失敗した理由: the reason (it) failed (attributive modification).","grammar:539:ex5:points:1":"〜ましょう: a suggestion."},"540":{"example:540:exzh":"There are many options.","example:540:exzh2":"He made the right choice.","example:540:exzh3":"Making choices is important.","example:540:exzh4":"Be confident in your choice.","example:540:exzh5":"Choosing isn't easy."},"541":{"example:541:exzh":"I place my trust in him.","example:541:exzh2":"A relationship of trust is important.","example:541:exzh3":"That team is trustworthy.","example:541:exzh4":"Losing trust is easy.","example:541:exzh5":"There is deep trust between her and me."},"542":{"example:542:exzh":"The trip ended safely.","example:542:exzh2":"It's important to stay safe.","example:542:exzh3":"I'm grateful I could come back safely.","example:542:exzh4":"I hope you get home safely.","example:542:exzh5":"I confirmed that all was well."},"543":{"example:543:exzh":"He values his life.","example:543:exzh2":"Life comes only once.","example:543:exzh3":"It's important to enjoy life.","example:543:exzh4":"It's hard to avoid the suffering of life.","example:543:exzh5":"I'll do my best to protect life.","grammar:543:ex:trans":"He values life.","grammar:543:ex:structure":"〜を大切にしている","grammar:543:ex:explain":"This sentence uses the set phrase 「〜を大切にする」 (to value …). The thing valued is marked with 「を」, so 「人生を大切にする」 means to value life. 「大切にする」 is built from the na-adjective 「大切」 (important) plus 「にする」 and means to treat something as important, to cherish it. The ending 「大切にしている」 uses 「〜ている」 to show an ongoing attitude. The opening 「彼は」 sets the topic. The whole sentence means he values life. 「〜を大切にする」 is a common fixed way to say you care about someone or something.","grammar:543:ex:words:0:zh":"he","grammar:543:ex:words:0:note":"かれ","grammar:543:ex:words:0:pos":"pronoun","grammar:543:ex:words:1:zh":"(topic)","grammar:543:ex:words:1:pos":"particle","grammar:543:ex:words:2:zh":"life","grammar:543:ex:words:2:note":"じんせい","grammar:543:ex:words:2:pos":"noun","grammar:543:ex:words:3:zh":"(object marker)","grammar:543:ex:words:3:pos":"particle","grammar:543:ex:words:4:zh":"cherish","grammar:543:ex:words:4:note":"たいせつにしている","grammar:543:ex:words:4:pos":"verb","grammar:543:ex:points:0":"人生 (じんせい): life.","grammar:543:ex:points:1":"「〜を大切にする」: to cherish …","grammar:543:ex2:trans":"Life comes only once.","grammar:543:ex2:structure":"〜は一度きりです","grammar:543:ex2:words:0:zh":"life","grammar:543:ex2:words:0:note":"せい","grammar:543:ex2:words:0:pos":"noun","grammar:543:ex2:words:1:zh":"(topic)","grammar:543:ex2:words:1:pos":"particle","grammar:543:ex2:words:2:zh":"once","grammar:543:ex2:words:2:note":"いちど","grammar:543:ex2:words:2:pos":"noun","grammar:543:ex2:words:3:zh":"only","grammar:543:ex2:words:3:pos":"particle","grammar:543:ex2:words:4:zh":"(polite form)","grammar:543:ex2:words:4:pos":"copula","grammar:543:ex2:points:0":"〜きり: only … (一度きり = only once).","grammar:543:ex2:points:1":"生 (せい): life.","grammar:543:ex3:trans":"Enjoying life is important.","grammar:543:ex3:structure":"〜ことが大事です","grammar:543:ex3:words:0:zh":"life","grammar:543:ex3:words:0:note":"せい","grammar:543:ex3:words:0:pos":"noun","grammar:543:ex3:words:1:zh":"(object marker)","grammar:543:ex3:words:1:pos":"particle","grammar:543:ex3:words:2:zh":"enjoy","grammar:543:ex3:words:2:note":"たのしむ","grammar:543:ex3:words:2:pos":"verb","grammar:543:ex3:words:3:zh":"(nominalizer)","grammar:543:ex3:words:3:pos":"noun","grammar:543:ex3:words:4:zh":"(nominative)","grammar:543:ex3:words:4:pos":"particle","grammar:543:ex3:words:5:zh":"important","grammar:543:ex3:words:5:note":"だいじ","grammar:543:ex3:words:5:pos":"na-adjective","grammar:543:ex3:words:6:zh":"(polite form)","grammar:543:ex3:words:6:pos":"copula","grammar:543:ex3:points:0":"生を楽しむ: to enjoy life.","grammar:543:ex3:points:1":"〜ことが大事です: doing … is important.","grammar:543:ex4:trans":"Avoiding the suffering that comes with life is hard.","grammar:543:ex4:structure":"〜のは難しい","grammar:543:ex4:words:0:zh":"life","grammar:543:ex4:words:0:note":"せい","grammar:543:ex4:words:0:pos":"noun","grammar:543:ex4:words:1:zh":"'s","grammar:543:ex4:words:1:pos":"particle","grammar:543:ex4:words:2:zh":"suffering","grammar:543:ex4:words:2:note":"くるしみ","grammar:543:ex4:words:2:pos":"noun","grammar:543:ex4:words:3:zh":"(object marker)","grammar:543:ex4:words:3:pos":"particle","grammar:543:ex4:words:4:zh":"avoid","grammar:543:ex4:words:4:note":"さける","grammar:543:ex4:words:4:pos":"verb","grammar:543:ex4:words:5:zh":"(nominalizer)","grammar:543:ex4:words:5:pos":"particle","grammar:543:ex4:words:6:zh":"(topic)","grammar:543:ex4:words:6:pos":"particle","grammar:543:ex4:words:7:zh":"difficult","grammar:543:ex4:words:7:note":"むずかしい","grammar:543:ex4:words:7:pos":"adjective","grammar:543:ex4:points:0":"生の苦しみ: the suffering of life.","grammar:543:ex4:points:1":"〜のは難しい: doing … is hard.","grammar:543:ex5:trans":"I'll do my best to protect life.","grammar:543:ex5:structure":"〜ために〜します","grammar:543:ex5:words:0:zh":"life","grammar:543:ex5:words:0:note":"せい","grammar:543:ex5:words:0:pos":"noun","grammar:543:ex5:words:1:zh":"(object marker)","grammar:543:ex5:words:1:pos":"particle","grammar:543:ex5:words:2:zh":"protect","grammar:543:ex5:words:2:note":"まもる","grammar:543:ex5:words:2:pos":"verb","grammar:543:ex5:words:3:zh":"for the sake of","grammar:543:ex5:words:3:pos":"particle","grammar:543:ex5:words:4:zh":"effort","grammar:543:ex5:words:4:note":"どりょくします","grammar:543:ex5:words:4:pos":"verb","grammar:543:ex5:points:0":"〜ために: in order to….","grammar:543:ex5:points:1":"生を守る: to protect life."},"544":{"example:544:exzh":"This flower is beautiful.","example:544:exzh2":"Beautiful scenery stretches out.","example:544:exzh3":"She's very beautiful.","example:544:exzh4":"I listened to beautiful music.","example:544:exzh5":"I live in a beautiful town.","grammar:544:ex:trans":"This flower is beautiful.","grammar:544:ex:structure":"〜は美しいです","grammar:544:ex:explain":"This is an i-adjective predicate sentence, 「〜は美しいです」. 「美しい（うつくしい）」 is an i-adjective meaning beautiful or lovely, and it sounds more refined and poetic than 「きれい」. As a predicate it takes 「です」 directly to become the polite form. 「この花は」 at the front uses 「は」 to mark the topic, this flower. The whole sentence means this flower is beautiful. Note that 「美しい」 is an i-adjective (it modifies a noun directly, or takes です), whereas the similar-meaning 「きれい」 is a na-adjective (it needs な before a noun) — different parts of speech, different usage.","grammar:544:ex:words:0:zh":"this","grammar:544:ex:words:0:pos":"pre-noun adjectival","grammar:544:ex:words:1:zh":"flowers","grammar:544:ex:words:1:note":"はな","grammar:544:ex:words:1:pos":"noun","grammar:544:ex:words:2:zh":"(topic)","grammar:544:ex:words:2:pos":"particle","grammar:544:ex:words:3:zh":"beautiful","grammar:544:ex:words:3:note":"うつくしい","grammar:544:ex:words:3:pos":"adjective","grammar:544:ex:words:4:zh":"(polite form)","grammar:544:ex:words:4:pos":"copula","grammar:544:ex:points:0":"❗美しい（うつくしい）: beautiful, lovely (more refined than きれい).","grammar:544:ex:points:1":"この花: this flower.","grammar:544:ex2:trans":"A beautiful view spreads out.","grammar:544:ex2:structure":"〜が広がっています","grammar:544:ex2:words:0:zh":"beautiful","grammar:544:ex2:words:0:note":"うつくしい","grammar:544:ex2:words:0:pos":"adjective","grammar:544:ex2:words:1:zh":"scenery","grammar:544:ex2:words:1:note":"けしき","grammar:544:ex2:words:1:pos":"noun","grammar:544:ex2:words:2:zh":"(nominative)","grammar:544:ex2:words:2:pos":"particle","grammar:544:ex2:words:3:zh":"stretching out","grammar:544:ex2:words:3:note":"ひろがっています","grammar:544:ex2:words:3:pos":"verb","grammar:544:ex2:points:0":"❗広がる: to spread, to open up (intransitive verb).","grammar:544:ex2:points:1":"美しい景色: a beautiful view.","grammar:544:ex3:trans":"She is very beautiful.","grammar:544:ex3:structure":"〜はとても美しい","grammar:544:ex3:words:0:zh":"she","grammar:544:ex3:words:0:note":"かのじょ","grammar:544:ex3:words:0:pos":"pronoun","grammar:544:ex3:words:1:zh":"(topic)","grammar:544:ex3:words:1:pos":"particle","grammar:544:ex3:words:2:zh":"extremely","grammar:544:ex3:words:2:pos":"adverb","grammar:544:ex3:words:3:zh":"beautiful","grammar:544:ex3:words:3:note":"うつくしい","grammar:544:ex3:words:3:pos":"adjective","grammar:544:ex3:points:0":"とても美しい: very beautiful.","grammar:544:ex3:points:1":"彼女は美しい: she is beautiful.","grammar:544:ex4:trans":"I heard beautiful music.","grammar:544:ex4:structure":"〜を聞きました","grammar:544:ex4:words:0:zh":"beautiful","grammar:544:ex4:words:0:note":"うつくしい","grammar:544:ex4:words:0:pos":"adjective","grammar:544:ex4:words:1:zh":"music","grammar:544:ex4:words:1:note":"おんがく","grammar:544:ex4:words:1:pos":"noun","grammar:544:ex4:words:2:zh":"(object marker)","grammar:544:ex4:words:2:pos":"particle","grammar:544:ex4:words:3:zh":"heard","grammar:544:ex4:words:3:note":"ききました","grammar:544:ex4:words:3:pos":"verb","grammar:544:ex4:points:0":"美しい音楽: beautiful music.","grammar:544:ex4:points:1":"音楽を聞く: listen to music.","grammar:544:ex5:trans":"I live in a beautiful town.","grammar:544:ex5:structure":"〜に住んでいます","grammar:544:ex5:words:0:zh":"beautiful","grammar:544:ex5:words:0:note":"うつくしい","grammar:544:ex5:words:0:pos":"adjective","grammar:544:ex5:words:1:zh":"town","grammar:544:ex5:words:1:note":"まち","grammar:544:ex5:words:1:pos":"noun","grammar:544:ex5:words:2:zh":"(place of residence)","grammar:544:ex5:words:2:pos":"particle","grammar:544:ex5:words:3:zh":"live (there)","grammar:544:ex5:words:3:note":"すんでいます","grammar:544:ex5:words:3:pos":"verb","grammar:544:ex5:points:0":"美しい町: a beautiful town.","grammar:544:ex5:points:1":"〜に住む: to live in/at …"},"545":{"example:545:exzh":"Japan has many beautiful islands.","example:545:exzh2":"He grew up on a small island.","example:545:exzh3":"This island is popular as a tourist destination.","example:545:exzh4":"Transportation to the island is convenient.","example:545:exzh5":"When I visited the island, the sea was very beautiful.","grammar:545:ex:trans":"Japan has many beautiful islands.","grammar:545:ex:structure":"〜には〜があります (〜 has 〜)","grammar:545:ex:explain":"This sentence uses the pattern 「〜には〜があります」 for existence in a place. The location 「日本」 takes 「には」 (に + は, adding contrast or emphasis on in Japan). The thing that exists, 「島」 (island), takes 「が」, and the verb 「あります」 is used for inanimate things. In between, 「多くの美しい」 modifies 「島」: 「多くの」 (many) takes 「の」, while 「美しい」 (beautiful) attaches directly to the noun. The whole sentence means Japan has many beautiful islands. When you want to emphasize the location of existence, 「には」 is common—it adds a layer of emphasis that plain 「に」 doesn't have.","grammar:545:ex:words:0:zh":"Japan","grammar:545:ex:words:0:note":"にほん","grammar:545:ex:words:0:pos":"noun","grammar:545:ex:words:1:zh":"(location of existence)","grammar:545:ex:words:1:pos":"particle","grammar:545:ex:words:2:zh":"(contrast)","grammar:545:ex:words:2:pos":"particle","grammar:545:ex:words:3:zh":"a lot","grammar:545:ex:words:3:note":"おおく","grammar:545:ex:words:3:pos":"noun","grammar:545:ex:words:4:zh":"'s","grammar:545:ex:words:4:pos":"particle","grammar:545:ex:words:5:zh":"beautiful","grammar:545:ex:words:5:note":"うつくしい","grammar:545:ex:words:5:pos":"adjective","grammar:545:ex:words:6:zh":"island","grammar:545:ex:words:6:note":"しま","grammar:545:ex:words:6:pos":"noun","grammar:545:ex:words:7:zh":"(nominative)","grammar:545:ex:words:7:pos":"particle","grammar:545:ex:words:8:zh":"there is / are","grammar:545:ex:words:8:pos":"verb","grammar:545:ex:points:0":"島 (しま): island.","grammar:545:ex:points:1":"〜には〜がある: … has…, there is… in…","grammar:545:ex2:trans":"He grew up on a small island.","grammar:545:ex2:structure":"〜で育ちました","grammar:545:ex2:words:0:zh":"he","grammar:545:ex2:words:0:note":"かれ","grammar:545:ex2:words:0:pos":"pronoun","grammar:545:ex2:words:1:zh":"(topic)","grammar:545:ex2:words:1:pos":"particle","grammar:545:ex2:words:2:zh":"small","grammar:545:ex2:words:2:note":"ちいさな","grammar:545:ex2:words:2:pos":"pre-noun adjectival","grammar:545:ex2:words:3:zh":"island","grammar:545:ex2:words:3:note":"しま","grammar:545:ex2:words:3:pos":"noun","grammar:545:ex2:words:4:zh":"(place of the action)","grammar:545:ex2:words:4:pos":"particle","grammar:545:ex2:words:5:zh":"grew up","grammar:545:ex2:words:5:note":"そだちました","grammar:545:ex2:words:5:pos":"verb","grammar:545:ex2:points:0":"❗育つ (intransitive verb, to grow up) vs 育てる (transitive verb, to raise).","grammar:545:ex2:points:1":"小さな島で: on a small island (で for place).","grammar:545:ex3:trans":"This island is very popular as a tourist destination.","grammar:545:ex3:structure":"〜として人気です","grammar:545:ex3:words:0:zh":"this","grammar:545:ex3:words:0:pos":"pre-noun adjectival","grammar:545:ex3:words:1:zh":"island","grammar:545:ex3:words:1:note":"しま","grammar:545:ex3:words:1:pos":"noun","grammar:545:ex3:words:2:zh":"(topic)","grammar:545:ex3:words:2:pos":"particle","grammar:545:ex3:words:3:zh":"tourist destination","grammar:545:ex3:words:3:note":"かんこうち","grammar:545:ex3:words:3:pos":"noun","grammar:545:ex3:words:4:zh":"as","grammar:545:ex3:words:4:pos":"set phrase","grammar:545:ex3:words:5:zh":"popular","grammar:545:ex3:words:5:note":"にんき","grammar:545:ex3:words:5:pos":"noun","grammar:545:ex3:words:6:zh":"(polite form)","grammar:545:ex3:words:6:pos":"copula","grammar:545:ex3:points:0":"〜として: as … (role or capacity).","grammar:545:ex3:points:1":"人気です: is popular.","grammar:545:ex4:trans":"Transportation to the island is convenient.","grammar:545:ex4:structure":"〜への〜は便利です","grammar:545:ex4:words:0:zh":"island","grammar:545:ex4:words:0:note":"しま","grammar:545:ex4:words:0:pos":"noun","grammar:545:ex4:words:1:zh":"to","grammar:545:ex4:words:1:pos":"particle","grammar:545:ex4:words:2:zh":"'s","grammar:545:ex4:words:2:pos":"particle","grammar:545:ex4:words:3:zh":"transportation","grammar:545:ex4:words:3:note":"こうつう","grammar:545:ex4:words:3:pos":"noun","grammar:545:ex4:words:4:zh":"(topic)","grammar:545:ex4:words:4:pos":"particle","grammar:545:ex4:words:5:zh":"convenient","grammar:545:ex4:words:5:note":"べんり","grammar:545:ex4:words:5:pos":"na-adjective","grammar:545:ex4:words:6:zh":"(polite form)","grammar:545:ex4:words:6:pos":"copula","grammar:545:ex4:points:0":"島への交通: transportation to the island (へ + の modifies a noun).","grammar:545:ex4:points:1":"便利: convenient.","grammar:545:ex5:trans":"When I visited that island, the sea was very beautiful.","grammar:545:ex5:structure":"〜た時、〜でした","grammar:545:ex5:words:0:zh":"island","grammar:545:ex5:words:0:note":"しま","grammar:545:ex5:words:0:pos":"noun","grammar:545:ex5:words:1:zh":"(object marker)","grammar:545:ex5:words:1:pos":"particle","grammar:545:ex5:words:2:zh":"visited","grammar:545:ex5:words:2:note":"おとずれた","grammar:545:ex5:words:2:pos":"verb","grammar:545:ex5:words:3:zh":"time","grammar:545:ex5:words:3:note":"とき","grammar:545:ex5:words:3:pos":"noun","grammar:545:ex5:words:4:zh":"sea","grammar:545:ex5:words:4:note":"うみ","grammar:545:ex5:words:4:pos":"noun","grammar:545:ex5:words:5:zh":"(nominative)","grammar:545:ex5:words:5:pos":"particle","grammar:545:ex5:words:6:zh":"extremely","grammar:545:ex5:words:6:pos":"adverb","grammar:545:ex5:words:7:zh":"beautiful","grammar:545:ex5:words:7:pos":"na-adjective","grammar:545:ex5:words:8:zh":"(past) was","grammar:545:ex5:words:8:pos":"copula","grammar:545:ex5:points:0":"〜た時: when …","grammar:545:ex5:points:1":"訪れる: to visit."},"546":{"example:546:exzh":"There are customers in the restaurant.","example:546:exzh2":"Days with lots of customers are busy.","example:546:exzh3":"He is a guest at the hotel.","example:546:exzh4":"This shop has few customers.","example:546:exzh5":"I welcomed the guest.","grammar:546:ex:trans":"There are customers in the restaurant.","grammar:546:ex:structure":"〜に〜がいます","grammar:546:ex:explain":"This sentence uses the pattern 「〜に〜がいます」 for existence in a place. The location 「レストラン」 (restaurant) is marked with 「に」, and since the thing that exists—「客」 (customers)—is a person, the verb of existence for living things, 「います」, is used, with 「が」 marking it. The key word 「客」 (きゃく) means customer or guest. The whole sentence means there are customers in the restaurant. The key point here: because the thing that exists is a person, you use 「いる (います)」 rather than 「ある」 for inanimate things—location with 「に」 and the thing with 「が」 is the basic pairing for existence sentences.","grammar:546:ex:words:0:zh":"restaurant","grammar:546:ex:words:0:note":"loanword","grammar:546:ex:words:0:pos":"noun","grammar:546:ex:words:1:zh":"(location of existence)","grammar:546:ex:words:1:pos":"particle","grammar:546:ex:words:2:zh":"customer","grammar:546:ex:words:2:note":"きゃく","grammar:546:ex:words:2:pos":"noun","grammar:546:ex:words:3:zh":"(nominative)","grammar:546:ex:words:3:pos":"particle","grammar:546:ex:words:4:zh":"there is / are","grammar:546:ex:words:4:pos":"verb","grammar:546:ex:points:0":"客 (きゃく): customer (a person) → いる.","grammar:546:ex:points:1":"に＋がいます: there is (a person) in a place.","grammar:546:ex2:trans":"Days with lots of customers are busy.","grammar:546:ex2:structure":"〜が多い日は〜","grammar:546:ex2:words:0:zh":"customer","grammar:546:ex2:words:0:note":"きゃく","grammar:546:ex2:words:0:pos":"noun","grammar:546:ex2:words:1:zh":"(nominative)","grammar:546:ex2:words:1:pos":"particle","grammar:546:ex2:words:2:zh":"many","grammar:546:ex2:words:2:note":"おおい","grammar:546:ex2:words:2:pos":"adjective","grammar:546:ex2:words:3:zh":"day","grammar:546:ex2:words:3:note":"ひ","grammar:546:ex2:words:3:pos":"noun","grammar:546:ex2:words:4:zh":"(topic)","grammar:546:ex2:words:4:pos":"particle","grammar:546:ex2:words:5:zh":"busy","grammar:546:ex2:words:5:note":"いそがしい","grammar:546:ex2:words:5:pos":"adjective","grammar:546:ex2:points:0":"客が多い日: a day with many customers (noun-modifying clause).","grammar:546:ex2:points:1":"忙しい: busy.","grammar:546:ex3:trans":"He is a hotel guest.","grammar:546:ex3:structure":"〜は〜の客です","grammar:546:ex3:words:0:zh":"he","grammar:546:ex3:words:0:note":"かれ","grammar:546:ex3:words:0:pos":"pronoun","grammar:546:ex3:words:1:zh":"(topic)","grammar:546:ex3:words:1:pos":"particle","grammar:546:ex3:words:2:zh":"hotel","grammar:546:ex3:words:2:note":"loanword","grammar:546:ex3:words:2:pos":"noun","grammar:546:ex3:words:3:zh":"'s","grammar:546:ex3:words:3:pos":"particle","grammar:546:ex3:words:4:zh":"customer","grammar:546:ex3:words:4:note":"きゃく","grammar:546:ex3:words:4:pos":"noun","grammar:546:ex3:words:5:zh":"is","grammar:546:ex3:words:5:pos":"copula","grammar:546:ex3:points:0":"ホテルの客: a hotel guest.","grammar:546:ex3:points:1":"客: customer, guest.","grammar:546:ex4:trans":"This shop has few customers.","grammar:546:ex4:structure":"〜は〜が少ないです","grammar:546:ex4:words:0:zh":"this","grammar:546:ex4:words:0:pos":"pre-noun adjectival","grammar:546:ex4:words:1:zh":"store","grammar:546:ex4:words:1:note":"みせ","grammar:546:ex4:words:1:pos":"noun","grammar:546:ex4:words:2:zh":"(topic)","grammar:546:ex4:words:2:pos":"particle","grammar:546:ex4:words:3:zh":"customer","grammar:546:ex4:words:3:note":"きゃく","grammar:546:ex4:words:3:pos":"noun","grammar:546:ex4:words:4:zh":"(nominative)","grammar:546:ex4:words:4:pos":"particle","grammar:546:ex4:words:5:zh":"few","grammar:546:ex4:words:5:note":"すくない","grammar:546:ex4:words:5:pos":"adjective","grammar:546:ex4:words:6:zh":"(polite form)","grammar:546:ex4:words:6:pos":"copula","grammar:546:ex4:points:0":"客が少ない: there are few customers.","grammar:546:ex4:points:1":"この店: this shop.","grammar:546:ex5:trans":"I welcomed the guest.","grammar:546:ex5:structure":"〜をお迎えしました","grammar:546:ex5:words:0:zh":"I","grammar:546:ex5:words:0:note":"わたし","grammar:546:ex5:words:0:pos":"pronoun","grammar:546:ex5:words:1:zh":"(topic)","grammar:546:ex5:words:1:pos":"particle","grammar:546:ex5:words:2:zh":"customer","grammar:546:ex5:words:2:note":"おきゃくさま","grammar:546:ex5:words:2:pos":"noun","grammar:546:ex5:words:3:zh":"(object marker)","grammar:546:ex5:words:3:pos":"particle","grammar:546:ex5:words:4:zh":"welcomed","grammar:546:ex5:words:4:note":"おむかえしました (humble)","grammar:546:ex5:words:4:pos":"verb","grammar:546:ex5:points:0":"❗お客様: guest, customer (honorific).","grammar:546:ex5:points:1":"お迎えする: to welcome (お + verb + する, humble form)."},"547":{"example:547:exzh":"He has hidden talent.","example:547:exzh2":"It can be found in a hidden place.","example:547:exzh3":"I want to make a place to hide.","example:547:exzh4":"These are words with a hidden meaning.","example:547:exzh5":"The hidden facts came to light."},"548":{"example:548:exzh":"Please write your name and attach it.","example:548:exzh2":"We will assign someone to handle this matter.","example:548:exzh3":"He attached a tag to the sweater.","example:548:exzh4":"The price that was attached is high.","example:548:exzh5":"Please put the date on this memo.","grammar:548:ex:trans":"Please write your name and attach it.","grammar:548:ex:structure":"〜を書いて付けてください","grammar:548:ex:explain":"This sentence links two actions with two te-forms, and the key word is the transitive verb 「付ける」 (attach, add). The first half, 「書いて」, is the te-form of 「書く」 (write), meaning write (the name); it is followed by 「付けてください」, where 「付ける」 means attach or add, and 「付けて」 plus 「ください」 makes a request. So 「書いて付けてください」 means please write it and attach it. The object 「名前」 (name) takes 「を」. The whole sentence means please write your name and attach it. 「付ける」 is a transitive verb, paired with the intransitive 「付く」 (to be attached).","grammar:548:ex:words:0:zh":"name","grammar:548:ex:words:0:note":"なまえ","grammar:548:ex:words:0:pos":"noun","grammar:548:ex:words:1:zh":"(object marker)","grammar:548:ex:words:1:pos":"particle","grammar:548:ex:words:2:zh":"write","grammar:548:ex:words:2:note":"かいて","grammar:548:ex:words:2:pos":"verb","grammar:548:ex:words:3:zh":"attach","grammar:548:ex:words:3:note":"つけて","grammar:548:ex:words:3:pos":"verb","grammar:548:ex:words:4:zh":"please","grammar:548:ex:words:4:pos":"auxiliary verb","grammar:548:ex:points:0":"❗付ける（つける）: to attach, to add, to stick on.","grammar:548:ex:points:1":"書いて付ける: write and attach.","grammar:548:ex2:trans":"We'll assign someone to handle this matter.","grammar:548:ex2:structure":"〜に〜を付けます","grammar:548:ex2:words:0:zh":"this","grammar:548:ex2:words:0:pos":"pre-noun adjectival","grammar:548:ex2:words:1:zh":"matter","grammar:548:ex2:words:1:note":"けん","grammar:548:ex2:words:1:pos":"noun","grammar:548:ex2:words:2:zh":"(object)","grammar:548:ex2:words:2:pos":"particle","grammar:548:ex2:words:3:zh":"person in charge","grammar:548:ex2:words:3:note":"たんとう","grammar:548:ex2:words:3:pos":"noun","grammar:548:ex2:words:4:zh":"(object marker)","grammar:548:ex2:words:4:pos":"particle","grammar:548:ex2:words:5:zh":"assign","grammar:548:ex2:words:5:note":"つけます","grammar:548:ex2:words:5:pos":"verb","grammar:548:ex2:points:0":"❗担当を付ける: assign a person in charge.","grammar:548:ex2:points:1":"この件: this matter.","grammar:548:ex3:trans":"He attached a tag to the sweater.","grammar:548:ex3:structure":"〜に〜を付けた","grammar:548:ex3:words:0:zh":"he","grammar:548:ex3:words:0:note":"かれ","grammar:548:ex3:words:0:pos":"pronoun","grammar:548:ex3:words:1:zh":"(topic)","grammar:548:ex3:words:1:pos":"particle","grammar:548:ex3:words:2:zh":"sweater","grammar:548:ex3:words:2:note":"loanword","grammar:548:ex3:words:2:pos":"noun","grammar:548:ex3:words:3:zh":"(the surface it is attached to)","grammar:548:ex3:words:3:pos":"particle","grammar:548:ex3:words:4:zh":"tag","grammar:548:ex3:words:4:note":"loanword","grammar:548:ex3:words:4:pos":"noun","grammar:548:ex3:words:5:zh":"(object marker)","grammar:548:ex3:words:5:pos":"particle","grammar:548:ex3:words:6:zh":"attached","grammar:548:ex3:words:6:note":"つけた","grammar:548:ex3:words:6:pos":"verb","grammar:548:ex3:points:0":"❗〜に〜を付ける: attach … to … (the place it is attached to takes に).","grammar:548:ex3:points:1":"タグ: tag.","grammar:548:ex4:trans":"The marked price is high.","grammar:548:ex4:structure":"付けられた〜は〜です","grammar:548:ex4:words:0:zh":"attached (put on)","grammar:548:ex4:words:0:note":"つけられた","grammar:548:ex4:words:0:pos":"verb","grammar:548:ex4:words:1:zh":"price","grammar:548:ex4:words:1:note":"ねだん","grammar:548:ex4:words:1:pos":"noun","grammar:548:ex4:words:2:zh":"(topic)","grammar:548:ex4:words:2:pos":"particle","grammar:548:ex4:words:3:zh":"tall","grammar:548:ex4:words:3:note":"たかい","grammar:548:ex4:words:3:pos":"adjective","grammar:548:ex4:words:4:zh":"(polite form)","grammar:548:ex4:words:4:pos":"copula","grammar:548:ex4:points:0":"❗付けられた: was attached (passive form).","grammar:548:ex4:points:1":"値段が高い: the price is high.","grammar:548:ex5:trans":"Please put the date on this memo.","grammar:548:ex5:structure":"〜に〜を付けてください","grammar:548:ex5:words:0:zh":"this","grammar:548:ex5:words:0:pos":"pre-noun adjectival","grammar:548:ex5:words:1:zh":"memo","grammar:548:ex5:words:1:note":"loanword","grammar:548:ex5:words:1:pos":"noun","grammar:548:ex5:words:2:zh":"(the surface it is attached to)","grammar:548:ex5:words:2:pos":"particle","grammar:548:ex5:words:3:zh":"date","grammar:548:ex5:words:3:note":"ひづけ","grammar:548:ex5:words:3:pos":"noun","grammar:548:ex5:words:4:zh":"(object marker)","grammar:548:ex5:words:4:pos":"particle","grammar:548:ex5:words:5:zh":"put on","grammar:548:ex5:words:5:note":"つけて","grammar:548:ex5:words:5:pos":"verb","grammar:548:ex5:words:6:zh":"please","grammar:548:ex5:words:6:pos":"auxiliary verb","grammar:548:ex5:points:0":"❗日付を付ける: put a date on it.","grammar:548:ex5:points:1":"メモ: memo, note."},"549":{"example:549:exzh":"She is a lovely person.","example:549:exzh2":"Today is a lovely day, isn't it?","example:549:exzh3":"I think that dress is lovely.","example:549:exzh4":"Let's make some lovely memories.","example:549:exzh5":"I saw a lovely view.","grammar:549:ex:trans":"She is a wonderful person.","grammar:549:ex:structure":"〜は素敵な〜です","grammar:549:ex:explain":"This is a noun-predicate sentence using a na-adjective to modify a noun. 「素敵」 (すてき) is a na-adjective meaning great, lovely, charming, and it takes 「な」 when modifying the noun 「人」, giving 「素敵な人」 (a wonderful person). The opening 「彼女は」 uses 「は」 to set the topic, her, and the ending 「です」 makes the statement. The whole sentence means she is a wonderful person. 「素敵」 is a common word for praising someone or something as excellent and charming—remember it's a na-adjective, so it takes 「な」 before a noun (素敵な人 / 素敵な服).","grammar:549:ex:words:0:zh":"she","grammar:549:ex:words:0:note":"かのじょ","grammar:549:ex:words:0:pos":"pronoun","grammar:549:ex:words:1:zh":"(topic)","grammar:549:ex:words:1:pos":"particle","grammar:549:ex:words:2:zh":"wonderful","grammar:549:ex:words:2:note":"すてき","grammar:549:ex:words:2:pos":"na-adjective","grammar:549:ex:words:3:zh":"(attributive form)","grammar:549:ex:words:3:pos":"auxiliary verb","grammar:549:ex:words:4:zh":"person","grammar:549:ex:words:4:note":"ひと","grammar:549:ex:words:4:pos":"noun","grammar:549:ex:words:5:zh":"is","grammar:549:ex:words:5:pos":"copula","grammar:549:ex:points:0":"素敵 (すてき): great, lovely, charming (na-adjective).","grammar:549:ex:points:1":"素敵な人: a wonderful person.","grammar:549:ex2:trans":"Today is a lovely day, isn't it?","grammar:549:ex2:structure":"〜は素敵な〜ですね","grammar:549:ex2:words:0:zh":"today","grammar:549:ex2:words:0:note":"きょう","grammar:549:ex2:words:0:pos":"noun","grammar:549:ex2:words:1:zh":"(topic)","grammar:549:ex2:words:1:pos":"particle","grammar:549:ex2:words:2:zh":"wonderful","grammar:549:ex2:words:2:note":"すてき","grammar:549:ex2:words:2:pos":"na-adjective","grammar:549:ex2:words:3:zh":"(attributive form)","grammar:549:ex2:words:3:pos":"auxiliary verb","grammar:549:ex2:words:4:zh":"day","grammar:549:ex2:words:4:note":"ひ","grammar:549:ex2:words:4:pos":"noun","grammar:549:ex2:words:5:zh":"(polite form)","grammar:549:ex2:words:5:pos":"copula","grammar:549:ex2:words:6:zh":"right?","grammar:549:ex2:words:6:pos":"particle","grammar:549:ex2:points:0":"素敵な日: a lovely day.","grammar:549:ex2:points:1":"ね: seeking agreement.","grammar:549:ex3:trans":"I think that dress is lovely.","grammar:549:ex3:structure":"〜だと思います","grammar:549:ex3:words:0:zh":"that","grammar:549:ex3:words:0:pos":"pre-noun adjectival","grammar:549:ex3:words:1:zh":"dress","grammar:549:ex3:words:1:note":"loanword","grammar:549:ex3:words:1:pos":"noun","grammar:549:ex3:words:2:zh":"(topic)","grammar:549:ex3:words:2:pos":"particle","grammar:549:ex3:words:3:zh":"lovely","grammar:549:ex3:words:3:note":"すてき","grammar:549:ex3:words:3:pos":"na-adjective","grammar:549:ex3:words:4:zh":"is","grammar:549:ex3:words:4:pos":"copula","grammar:549:ex3:words:5:zh":"(quotation)","grammar:549:ex3:words:5:pos":"particle","grammar:549:ex3:words:6:zh":"think","grammar:549:ex3:words:6:note":"おもいます","grammar:549:ex3:words:6:pos":"verb","grammar:549:ex3:points:0":"〜だと思います: I think that … (quotation).","grammar:549:ex3:points:1":"素敵だ: is wonderful (plain form).","grammar:549:ex4:trans":"Let's make some wonderful memories together.","grammar:549:ex4:structure":"〜を作りましょう","grammar:549:ex4:words:0:zh":"wonderful","grammar:549:ex4:words:0:note":"すてき","grammar:549:ex4:words:0:pos":"na-adjective","grammar:549:ex4:words:1:zh":"(attributive form)","grammar:549:ex4:words:1:pos":"auxiliary verb","grammar:549:ex4:words:2:zh":"memories","grammar:549:ex4:words:2:note":"おもいで","grammar:549:ex4:words:2:pos":"noun","grammar:549:ex4:words:3:zh":"(object marker)","grammar:549:ex4:words:3:pos":"particle","grammar:549:ex4:words:4:zh":"let's make","grammar:549:ex4:words:4:note":"つくりましょう","grammar:549:ex4:words:4:pos":"verb","grammar:549:ex4:points:0":"素敵な思い出: wonderful memories.","grammar:549:ex4:points:1":"〜ましょう: a suggestion.","grammar:549:ex5:trans":"I saw a beautiful view.","grammar:549:ex5:structure":"〜を見ました","grammar:549:ex5:words:0:zh":"wonderful","grammar:549:ex5:words:0:note":"すてき","grammar:549:ex5:words:0:pos":"na-adjective","grammar:549:ex5:words:1:zh":"(attributive form)","grammar:549:ex5:words:1:pos":"auxiliary verb","grammar:549:ex5:words:2:zh":"scenery","grammar:549:ex5:words:2:note":"けしき","grammar:549:ex5:words:2:pos":"noun","grammar:549:ex5:words:3:zh":"(object marker)","grammar:549:ex5:words:3:pos":"particle","grammar:549:ex5:words:4:zh":"watched","grammar:549:ex5:words:4:note":"みました","grammar:549:ex5:words:4:pos":"verb","grammar:549:ex5:points:0":"素敵な景色: a beautiful view.","grammar:549:ex5:points:1":"見る→見ました."},"550":{"example:550:exzh":"He is still young.","example:550:exzh2":"Young people are the hope of the future.","example:550:exzh3":"I remembered the dreams I had when I was young.","example:550:exzh4":"What is the secret to staying young?","example:550:exzh5":"She looks young.","grammar:550:ex:trans":"He is still young.","grammar:550:ex:structure":"〜はまだ若いです","grammar:550:ex:explain":"This is an i-adjective predicate sentence, and the key is the adverb 「まだ」. 「まだ (still, yet)」 means a state continues and hasn't changed, so 「まだ若い」 means \"still young\". 「若い（わかい）」 is the i-adjective \"young\", and takes 「です」 in the polite form as a predicate. 「彼は」 marks the topic. The whole sentence is \"He is still young\". 「まだ」 emphasizes \"still … up to now\" and often goes with the affirmative (まだ若い = still young) or the negative (まだ〜ない = not yet …); here it is the affirmative use.","grammar:550:ex:words:0:zh":"he","grammar:550:ex:words:0:note":"かれ","grammar:550:ex:words:0:pos":"pronoun","grammar:550:ex:words:1:zh":"(topic)","grammar:550:ex:words:1:pos":"particle","grammar:550:ex:words:2:zh":"still / yet","grammar:550:ex:words:2:pos":"adverb","grammar:550:ex:words:3:zh":"young","grammar:550:ex:words:3:note":"わかい","grammar:550:ex:words:3:pos":"adjective","grammar:550:ex:words:4:zh":"(polite form)","grammar:550:ex:words:4:pos":"copula","grammar:550:ex:points:0":"❗若い（わかい）: young; まだ = still, yet.","grammar:550:ex:points:1":"若い: young.","grammar:550:ex2:trans":"Young people are the hope of the future.","grammar:550:ex2:structure":"い形容詞＋名詞は、〜の〜です","grammar:550:ex2:explain":"「若い」 is an i-adjective that attaches directly to 「人」 to form 「若い人」, with no need for 「な」. 「は」 brings young people up as the topic. 「未来の希望」 links \"future\" and \"hope\" with 「の」, meaning a hope connected to the future and placed in it. 「です」 completes the polite noun predicate, and the whole sentence positions young people as the hope of the future.","grammar:550:ex2:words:0:zh":"young","grammar:550:ex2:words:0:note":"わかい","grammar:550:ex2:words:0:pos":"i-adjective","grammar:550:ex2:words:1:zh":"person","grammar:550:ex2:words:1:note":"ひと","grammar:550:ex2:words:1:pos":"noun","grammar:550:ex2:words:2:zh":"(topic)","grammar:550:ex2:words:2:pos":"particle","grammar:550:ex2:words:3:zh":"the future","grammar:550:ex2:words:3:note":"みらい","grammar:550:ex2:words:3:pos":"noun","grammar:550:ex2:words:4:zh":"(links to a noun, showing relationship)","grammar:550:ex2:words:4:pos":"particle","grammar:550:ex2:words:5:zh":"hope","grammar:550:ex2:words:5:note":"きぼう","grammar:550:ex2:words:5:pos":"noun","grammar:550:ex2:words:6:zh":"is (polite ending)","grammar:550:ex2:words:6:pos":"auxiliary verb","grammar:550:ex2:points:0":"I-adjectives can modify nouns directly, which is why we say 「若い人」.","grammar:550:ex2:points:1":"「AはBです」 is used to state A's identity, nature, or position.","grammar:550:ex3:trans":"I remembered the dreams I had when I was young.","grammar:550:ex3:structure":"若い頃の〜を思い出しました","grammar:550:ex3:words:0:zh":"young","grammar:550:ex3:words:0:note":"わかい","grammar:550:ex3:words:0:pos":"adjective","grammar:550:ex3:words:1:zh":"time","grammar:550:ex3:words:1:note":"ころ","grammar:550:ex3:words:1:pos":"noun","grammar:550:ex3:words:2:zh":"'s","grammar:550:ex3:words:2:pos":"particle","grammar:550:ex3:words:3:zh":"dream","grammar:550:ex3:words:3:note":"ゆめ","grammar:550:ex3:words:3:pos":"noun","grammar:550:ex3:words:4:zh":"(object marker)","grammar:550:ex3:words:4:pos":"particle","grammar:550:ex3:words:5:zh":"remembered","grammar:550:ex3:words:5:note":"おもいだしました","grammar:550:ex3:words:5:pos":"verb","grammar:550:ex3:points:0":"❗若い頃: when young (若い＋頃); 夢を思い出す = to recall a dream.","grammar:550:ex3:points:1":"若い頃: when young.","grammar:550:ex4:trans":"What's the secret to staying young?","grammar:550:ex4:structure":"若さを保つ秘訣は〜","grammar:550:ex4:words:0:zh":"young","grammar:550:ex4:words:0:note":"わかさ","grammar:550:ex4:words:0:pos":"noun","grammar:550:ex4:words:1:zh":"(object marker)","grammar:550:ex4:words:1:pos":"particle","grammar:550:ex4:words:2:zh":"stay","grammar:550:ex4:words:2:note":"たもつ","grammar:550:ex4:words:2:pos":"verb","grammar:550:ex4:words:3:zh":"secret","grammar:550:ex4:words:3:note":"ひけつ","grammar:550:ex4:words:3:pos":"noun","grammar:550:ex4:words:4:zh":"(topic)","grammar:550:ex4:words:4:pos":"particle","grammar:550:ex4:words:5:zh":"what","grammar:550:ex4:words:5:note":"なん","grammar:550:ex4:words:5:pos":"pronoun","grammar:550:ex4:words:6:zh":"is","grammar:550:ex4:words:6:pos":"copula","grammar:550:ex4:words:7:zh":"(question)","grammar:550:ex4:words:7:pos":"particle","grammar:550:ex4:points:0":"❗若さ: youth, youthfulness (若い＋さ, nominalized); 保つ = to maintain.","grammar:550:ex4:points:1":"若さを保つ: to stay young.","grammar:550:ex5:trans":"She looks young.","grammar:550:ex5:structure":"〜は若く見えます","grammar:550:ex5:words:0:zh":"she","grammar:550:ex5:words:0:note":"かのじょ","grammar:550:ex5:words:0:pos":"pronoun","grammar:550:ex5:words:1:zh":"(topic)","grammar:550:ex5:words:1:pos":"particle","grammar:550:ex5:words:2:zh":"in a young way","grammar:550:ex5:words:2:note":"わかく","grammar:550:ex5:words:2:pos":"adjective","grammar:550:ex5:words:3:zh":"looks (like)","grammar:550:ex5:words:3:note":"みえます","grammar:550:ex5:words:3:pos":"verb","grammar:550:ex5:points:0":"❗〜く見える: to look … (若い→若く＋見える).","grammar:550:ex5:points:1":"若く見える: to look young."},"551":{"example:551:exzh":"I wrote a shopping list.","example:551:exzh2":"Please check this list.","example:551:exzh3":"I like making lists.","example:551:exzh4":"I put my friend's name on the list.","example:551:exzh5":"There are many items on this list.","grammar:551:ex:trans":"I wrote a shopping list.","grammar:551:ex:structure":"〜を書きました","grammar:551:ex:explain":"This is a transitive sentence, 「〜を書きました」. The transitive verb 「書く」 (to write) has the polite past form 「書きました」, formed by changing 「く→き」 and adding ました. The object 「買い物リスト」 (shopping list) is marked with 「を」 and is made of 「買い物」 (shopping) plus the loanword 「リスト」 (list). The whole sentence means I wrote a shopping list. The masu-form of 「書く」 is 「書きます」 and the past is 「書きました」—memorize this rule for godan verbs ending in 「く」: 「く→き」 before the masu-form.","grammar:551:ex:words:0:zh":"shopping","grammar:551:ex:words:0:note":"かいもの","grammar:551:ex:words:0:pos":"noun","grammar:551:ex:words:1:zh":"list","grammar:551:ex:words:1:note":"loanword","grammar:551:ex:words:1:pos":"noun","grammar:551:ex:words:2:zh":"(object marker)","grammar:551:ex:words:2:pos":"particle","grammar:551:ex:words:3:zh":"wrote","grammar:551:ex:words:3:note":"かきました","grammar:551:ex:words:3:pos":"verb","grammar:551:ex:points:0":"買い物リスト: shopping list.","grammar:551:ex:points:1":"書く → 書きました.","grammar:551:ex2:trans":"Please check this list.","grammar:551:ex2:structure":"〜をチェックしてください","grammar:551:ex2:words:0:zh":"this","grammar:551:ex2:words:0:pos":"pre-noun adjectival","grammar:551:ex2:words:1:zh":"list","grammar:551:ex2:words:1:note":"loanword","grammar:551:ex2:words:1:pos":"noun","grammar:551:ex2:words:2:zh":"(object marker)","grammar:551:ex2:words:2:pos":"particle","grammar:551:ex2:words:3:zh":"check","grammar:551:ex2:words:3:pos":"verb","grammar:551:ex2:words:4:zh":"please","grammar:551:ex2:words:4:pos":"auxiliary verb","grammar:551:ex2:points:0":"チェックする: to check (loanword + する).","grammar:551:ex2:points:1":"このリスト: this list.","grammar:551:ex3:trans":"I like making lists.","grammar:551:ex3:structure":"〜のが好きです","grammar:551:ex3:words:0:zh":"list","grammar:551:ex3:words:0:note":"loanword","grammar:551:ex3:words:0:pos":"noun","grammar:551:ex3:words:1:zh":"(object marker)","grammar:551:ex3:words:1:pos":"particle","grammar:551:ex3:words:2:zh":"do","grammar:551:ex3:words:2:note":"つくる","grammar:551:ex3:words:2:pos":"verb","grammar:551:ex3:words:3:zh":"(nominalizer)","grammar:551:ex3:words:3:pos":"particle","grammar:551:ex3:words:4:zh":"(object)","grammar:551:ex3:words:4:pos":"particle","grammar:551:ex3:words:5:zh":"to like","grammar:551:ex3:words:5:note":"すき","grammar:551:ex3:words:5:pos":"na-adjective","grammar:551:ex3:words:6:zh":"(polite form)","grammar:551:ex3:words:6:pos":"copula","grammar:551:ex3:points:0":"リストを作る: to make a list.","grammar:551:ex3:points:1":"〜のが好き: to like doing…","grammar:551:ex4:trans":"I put a friend's name on the list.","grammar:551:ex4:structure":"〜を〜に入れました","grammar:551:ex4:words:0:zh":"friend","grammar:551:ex4:words:0:note":"ともだち","grammar:551:ex4:words:0:pos":"noun","grammar:551:ex4:words:1:zh":"'s","grammar:551:ex4:words:1:pos":"particle","grammar:551:ex4:words:2:zh":"name","grammar:551:ex4:words:2:note":"なまえ","grammar:551:ex4:words:2:pos":"noun","grammar:551:ex4:words:3:zh":"(object marker)","grammar:551:ex4:words:3:pos":"particle","grammar:551:ex4:words:4:zh":"list","grammar:551:ex4:words:4:note":"loanword","grammar:551:ex4:words:4:pos":"noun","grammar:551:ex4:words:5:zh":"(the destination point)","grammar:551:ex4:words:5:pos":"particle","grammar:551:ex4:words:6:zh":"put in","grammar:551:ex4:words:6:note":"いれました","grammar:551:ex4:words:6:pos":"verb","grammar:551:ex4:points:0":"〜をリストに入れる: to add … to a list (に marks where it goes).","grammar:551:ex4:points:1":"入れる: to put in (transitive verb).","grammar:551:ex5:trans":"There are many items on this list.","grammar:551:ex5:structure":"〜には〜があります (〜 has 〜)","grammar:551:ex5:words:0:zh":"this","grammar:551:ex5:words:0:pos":"pre-noun adjectival","grammar:551:ex5:words:1:zh":"list","grammar:551:ex5:words:1:note":"loanword","grammar:551:ex5:words:1:pos":"noun","grammar:551:ex5:words:2:zh":"(location of existence)","grammar:551:ex5:words:2:pos":"particle","grammar:551:ex5:words:3:zh":"(contrast)","grammar:551:ex5:words:3:pos":"particle","grammar:551:ex5:words:4:zh":"a lot","grammar:551:ex5:words:4:pos":"adverb","grammar:551:ex5:words:5:zh":"'s","grammar:551:ex5:words:5:pos":"particle","grammar:551:ex5:words:6:zh":"project","grammar:551:ex5:words:6:note":"こうもく","grammar:551:ex5:words:6:pos":"noun","grammar:551:ex5:words:7:zh":"(nominative)","grammar:551:ex5:words:7:pos":"particle","grammar:551:ex5:words:8:zh":"there is / are","grammar:551:ex5:words:8:pos":"verb","grammar:551:ex5:points:0":"リストには: on the list (には = に + は).","grammar:551:ex5:points:1":"項目: item."},"552":{"example:552:exzh":"I imagined things about the future.","example:552:exzh2":"Please use your imagination.","example:552:exzh3":"That imagination was wonderful.","example:552:exzh4":"It turned out just as I imagined.","example:552:exzh5":"It was an experience beyond imagination."},"553":{"example:553:exzh":"He noticed the mistake.","example:553:exzh2":"It is difficult to notice this problem.","example:553:exzh3":"Thank you for noticing.","example:553:exzh4":"I noticed my own feelings.","example:553:exzh5":"Time passed before I noticed."},"555":{"example:555:exzh":"He really is an idiot.","example:555:exzh2":"That can't be true.","example:555:exzh3":"Please don't make fun of me.","example:555:exzh4":"Don't make fun of your friends.","example:555:exzh5":"Don't do anything stupid.","grammar:555:ex:trans":"He really is an idiot.","grammar:555:ex:structure":"〜は本当に馬鹿だ","grammar:555:ex:explain":"This is a noun-predicate sentence, and the key points are the adverb 「本当に」 and the nuance of the wording. 「本当に」 (really, truly) modifies what follows and adds emphasis. The key word 「馬鹿」 (ばか) means fool or idiot; it is also often written 「バカ」, sounds stronger and insulting, so be careful about the situation when using it. 「だ」 is the plain-form copula. 「彼は」 at the front marks the topic. The whole sentence means he really is an idiot. This is an emotional plain-form sentence, and 「本当に馬鹿だ」 is blunt, so avoid 「馬鹿」 in formal or polite settings.","grammar:555:ex:words:0:zh":"he","grammar:555:ex:words:0:note":"かれ","grammar:555:ex:words:0:pos":"pronoun","grammar:555:ex:words:1:zh":"(topic)","grammar:555:ex:words:1:pos":"particle","grammar:555:ex:words:2:zh":"really","grammar:555:ex:words:2:note":"ほんとうに","grammar:555:ex:words:2:pos":"adverb","grammar:555:ex:words:3:zh":"fool","grammar:555:ex:words:3:note":"ばか","grammar:555:ex:words:3:pos":"noun","grammar:555:ex:words:4:zh":"is","grammar:555:ex:words:4:pos":"copula","grammar:555:ex:points:0":"❗馬鹿 (ばか): fool, idiot (also written 「バカ」; stronger tone, use with care).","grammar:555:ex:points:1":"馬鹿: idiot.","grammar:555:ex2:trans":"There's no way something that ridiculous could happen.","grammar:555:ex2:structure":"そんな馬鹿なことはない","grammar:555:ex2:words:0:zh":"such","grammar:555:ex2:words:0:pos":"pre-noun adjectival","grammar:555:ex2:words:1:zh":"ridiculous","grammar:555:ex2:words:1:note":"ばか","grammar:555:ex2:words:1:pos":"na-adjective","grammar:555:ex2:words:2:zh":"(attributive form)","grammar:555:ex2:words:2:pos":"auxiliary verb","grammar:555:ex2:words:3:zh":"thing / matter","grammar:555:ex2:words:3:pos":"noun","grammar:555:ex2:words:4:zh":"(topic)","grammar:555:ex2:words:4:pos":"particle","grammar:555:ex2:words:5:zh":"don't have","grammar:555:ex2:words:5:pos":"adjective","grammar:555:ex2:points:0":"❗馬鹿な: ridiculous, absurd (馬鹿＋な); 馬鹿なことはない＝there's no such nonsense.","grammar:555:ex2:points:1":"馬鹿な: ridiculous.","grammar:555:ex3:trans":"Please don't look down on me.","grammar:555:ex3:structure":"馬鹿にしないでください","grammar:555:ex3:words:0:zh":"don't look down on","grammar:555:ex3:words:0:note":"ばかにしないで","grammar:555:ex3:words:0:pos":"verb","grammar:555:ex3:words:1:zh":"please","grammar:555:ex3:words:1:pos":"auxiliary verb","grammar:555:ex3:points:0":"❗馬鹿にする: look down on, make fun of (idiomatic); 〜ないでください＝please don't …","grammar:555:ex3:points:1":"馬鹿にする: look down on.","grammar:555:ex4:trans":"Don't make fun of your friends.","grammar:555:ex4:structure":"〜を馬鹿にするな","grammar:555:ex4:words:0:zh":"friend","grammar:555:ex4:words:0:note":"ともだち","grammar:555:ex4:words:0:pos":"noun","grammar:555:ex4:words:1:zh":"(object marker)","grammar:555:ex4:words:1:pos":"particle","grammar:555:ex4:words:2:zh":"make fun of","grammar:555:ex4:words:2:note":"ばかにする","grammar:555:ex4:words:2:pos":"verb","grammar:555:ex4:words:3:zh":"(prohibition)","grammar:555:ex4:words:3:pos":"particle","grammar:555:ex4:points:0":"❗〜を馬鹿にする: mock, belittle …; verb＋な＝prohibitive (don't …).","grammar:555:ex4:points:1":"馬鹿にするな: don't look down on.","grammar:555:ex5:trans":"Don't do anything stupid.","grammar:555:ex5:structure":"馬鹿なことをしないで","grammar:555:ex5:words:0:zh":"stupid","grammar:555:ex5:words:0:note":"ばか","grammar:555:ex5:words:0:pos":"na-adjective","grammar:555:ex5:words:1:zh":"(attributive form)","grammar:555:ex5:words:1:pos":"auxiliary verb","grammar:555:ex5:words:2:zh":"thing / matter","grammar:555:ex5:words:2:pos":"noun","grammar:555:ex5:words:3:zh":"(object marker)","grammar:555:ex5:words:3:pos":"particle","grammar:555:ex5:words:4:zh":"don't do (it)","grammar:555:ex5:words:4:pos":"verb","grammar:555:ex5:points:0":"❗馬鹿なことをする: do something stupid; 〜しないで＝don't …","grammar:555:ex5:points:1":"馬鹿なこと: something stupid."},"556":{"example:556:exzh":"I lost my key.","example:556:exzh2":"Which door does this key fit?","example:556:exzh3":"Please lock the door.","example:556:exzh4":"I heard the sound of a key.","example:556:exzh5":"I'm looking for my key.","grammar:556:ex:trans":"I've gone and lost the key.","grammar:556:ex:structure":"noun＋を＋verbました. 「失くす」 = to lose (a transitive verb).","grammar:556:ex:explain":"This is a transitive-verb sentence of the form noun＋を＋verbました, and the key word is 「失くす」. 「失くす」 (なくす) is a transitive verb meaning to lose something (by accident), so the thing lost is marked with 「を」 and the polite past form is 「失くしました」. Here 「鍵を失くす」 means to lose a key. The whole sentence means I lost the key. Note that 「失くす」 is transitive (a person loses something), in contrast with the intransitive 「無くなる」 (something is gone) — here the emphasis is that you lost it yourself.","grammar:556:ex:words:0:zh":"key","grammar:556:ex:words:0:note":"かぎ","grammar:556:ex:words:0:pos":"noun","grammar:556:ex:words:1:zh":"(object marker)","grammar:556:ex:words:1:pos":"particle","grammar:556:ex:words:2:zh":"lost","grammar:556:ex:words:2:note":"なくしました","grammar:556:ex:words:2:pos":"verb","grammar:556:ex:points:0":"失くす: to lose, to misplace","grammar:556:ex:points:1":"鍵をなくす: to lose a key","grammar:556:ex2:trans":"Which door does this key fit?","grammar:556:ex2:structure":"この＋noun＋は＋どの＋noun＋に＋合いますか. 「〜に合う」 = to fit, to match…","grammar:556:ex2:words:0:zh":"this","grammar:556:ex2:words:0:pos":"pre-noun adjectival","grammar:556:ex2:words:1:zh":"key","grammar:556:ex2:words:1:note":"かぎ","grammar:556:ex2:words:1:pos":"noun","grammar:556:ex2:words:2:zh":"(topic marker)","grammar:556:ex2:words:2:pos":"particle","grammar:556:ex2:words:3:zh":"which one","grammar:556:ex2:words:3:pos":"pre-noun adjectival","grammar:556:ex2:words:4:zh":"door","grammar:556:ex2:words:4:note":"loanword","grammar:556:ex2:words:4:pos":"noun","grammar:556:ex2:words:5:zh":"(object)","grammar:556:ex2:words:5:pos":"particle","grammar:556:ex2:words:6:zh":"does it fit?","grammar:556:ex2:words:6:note":"あいますか","grammar:556:ex2:words:6:pos":"verb","grammar:556:ex2:points:0":"〜に合う: to fit…, to match","grammar:556:ex2:points:1":"どの＋noun: which…","grammar:556:ex3:trans":"Please lock the door.","grammar:556:ex3:structure":"〔鍵をかける〕＋てください. 「鍵をかける」 is the set phrase for to lock.","grammar:556:ex3:words:0:zh":"lock","grammar:556:ex3:words:0:note":"かぎ","grammar:556:ex3:words:0:pos":"noun","grammar:556:ex3:words:1:zh":"(object marker)","grammar:556:ex3:words:1:pos":"particle","grammar:556:ex3:words:2:zh":"lock","grammar:556:ex3:words:2:note":"かけて; 鍵をかける = to lock, te-form","grammar:556:ex3:words:2:pos":"verb","grammar:556:ex3:words:3:zh":"please","grammar:556:ex3:words:3:note":"〜てください","grammar:556:ex3:words:3:pos":"verb","grammar:556:ex3:points:0":"鍵をかける: to lock (a set collocation)","grammar:556:ex3:points:1":"〜てください: please do…","grammar:556:ex4:trans":"I heard the sound of a key.","grammar:556:ex4:structure":"〔nounの音〕＋が＋聞こえた. 「聞こえる」 means to hear naturally, and the thing heard takes が.","grammar:556:ex4:words:0:zh":"key","grammar:556:ex4:words:0:note":"かぎ","grammar:556:ex4:words:0:pos":"noun","grammar:556:ex4:words:1:zh":"'s","grammar:556:ex4:words:1:pos":"particle","grammar:556:ex4:words:2:zh":"voice","grammar:556:ex4:words:2:note":"おと","grammar:556:ex4:words:2:pos":"noun","grammar:556:ex4:words:3:zh":"(nominative)","grammar:556:ex4:words:3:pos":"particle","grammar:556:ex4:words:4:zh":"could hear (past)","grammar:556:ex4:words:4:note":"きこえた","grammar:556:ex4:words:4:pos":"verb","grammar:556:ex4:points:0":"聞こえる: to be audible, to hear naturally","grammar:556:ex4:points:1":"鍵の音: the sound of a key","grammar:556:ex5:trans":"I'm looking for my key.","grammar:556:ex5:structure":"〜は＋〔自分の鍵〕＋を＋探している. 「自分の」 = one's own.","grammar:556:ex5:words:0:zh":"I","grammar:556:ex5:words:0:note":"わたし","grammar:556:ex5:words:0:pos":"pronoun","grammar:556:ex5:words:1:zh":"(topic marker)","grammar:556:ex5:words:1:pos":"particle","grammar:556:ex5:words:2:zh":"oneself","grammar:556:ex5:words:2:note":"じぶん","grammar:556:ex5:words:2:pos":"pronoun","grammar:556:ex5:words:3:zh":"'s","grammar:556:ex5:words:3:pos":"particle","grammar:556:ex5:words:4:zh":"key","grammar:556:ex5:words:4:note":"かぎ","grammar:556:ex5:words:4:pos":"noun","grammar:556:ex5:words:5:zh":"(object marker)","grammar:556:ex5:words:5:pos":"particle","grammar:556:ex5:words:6:zh":"is looking for","grammar:556:ex5:words:6:note":"さがしている; 〜ている marks an ongoing action","grammar:556:ex5:words:6:pos":"verb","grammar:556:ex5:points:0":"自分の: one's own","grammar:556:ex5:points:1":"〜を探している: is looking for…"},"558":{"example:558:exzh":"Anyway, let's go!","example:558:exzh2":"You should try it anyway.","example:558:exzh3":"Anyway, there's no time.","example:558:exzh4":"Let's just give it a try anyway.","example:558:exzh5":"Anyway, let's get started now."},"560":{"example:560:exzh":"You must submit proof.","example:560:exzh2":"That proof is valid.","example:560:exzh3":"I got a certificate.","example:560:exzh4":"I need proof.","example:560:exzh5":"Please show me the proof."},"562":{"example:562:exzh":"She is a cute girl.","example:562:exzh2":"There are many girls at school.","example:562:exzh3":"That girl is my friend.","example:562:exzh4":"A girl is playing.","example:562:exzh5":"I like girls.","grammar:562:ex:trans":"She is a cute girl.","grammar:562:ex:structure":"〜は〜女の子です","grammar:562:ex:explain":"This is a noun-predicate sentence using an i-adjective to modify a noun. 「可愛い」 (かわいい) is an i-adjective meaning cute, and it attaches directly to the noun 「女の子」 to form 「可愛い女の子」 (a cute girl)—i-adjectives need no extra character before a noun. The key word 「女の子」 is made of 「女」 + 「の」 + 「子」 and means girl. The opening 「彼女は」 sets the topic, and the ending 「です」 makes the statement. The whole sentence means she is a cute girl. I-adjectives attach directly to nouns, unlike na-adjectives, which need 「な」.","grammar:562:ex:words:0:zh":"she","grammar:562:ex:words:0:note":"かのじょ","grammar:562:ex:words:0:pos":"pronoun","grammar:562:ex:words:1:zh":"(topic)","grammar:562:ex:words:1:pos":"particle","grammar:562:ex:words:2:zh":"cute","grammar:562:ex:words:2:note":"かわいい","grammar:562:ex:words:2:pos":"adjective","grammar:562:ex:words:3:zh":"girl","grammar:562:ex:words:3:note":"おんなのこ","grammar:562:ex:words:3:pos":"noun","grammar:562:ex:words:4:zh":"is","grammar:562:ex:words:4:pos":"copula","grammar:562:ex:points:0":"女の子 (おんなのこ): girl (女 + の + 子).","grammar:562:ex:points:1":"可愛い女の子: a cute girl.","grammar:562:ex2:trans":"There are many girls at school.","grammar:562:ex2:structure":"〜には〜がいる","grammar:562:ex2:words:0:zh":"school","grammar:562:ex2:words:0:note":"がっこう","grammar:562:ex2:words:0:pos":"noun","grammar:562:ex2:words:1:zh":"(location of existence)","grammar:562:ex2:words:1:pos":"particle","grammar:562:ex2:words:2:zh":"(contrast)","grammar:562:ex2:words:2:pos":"particle","grammar:562:ex2:words:3:zh":"girl","grammar:562:ex2:words:3:note":"おんなのこ","grammar:562:ex2:words:3:pos":"noun","grammar:562:ex2:words:4:zh":"(nominative)","grammar:562:ex2:words:4:pos":"particle","grammar:562:ex2:words:5:zh":"a lot","grammar:562:ex2:words:5:pos":"adverb","grammar:562:ex2:words:6:zh":"there is / are","grammar:562:ex2:words:6:pos":"verb","grammar:562:ex2:points:0":"女の子 (a person) → いる.","grammar:562:ex2:points:1":"〜には〜がいる: there is (a person) in …","grammar:562:ex3:trans":"That girl is my friend.","grammar:562:ex3:structure":"〜は〜です","grammar:562:ex3:words:0:zh":"that","grammar:562:ex3:words:0:pos":"pre-noun adjectival","grammar:562:ex3:words:1:zh":"girl","grammar:562:ex3:words:1:note":"おんなのこ","grammar:562:ex3:words:1:pos":"noun","grammar:562:ex3:words:2:zh":"(topic)","grammar:562:ex3:words:2:pos":"particle","grammar:562:ex3:words:3:zh":"friend","grammar:562:ex3:words:3:note":"ともだち","grammar:562:ex3:words:3:pos":"noun","grammar:562:ex3:words:4:zh":"is","grammar:562:ex3:words:4:pos":"copula","grammar:562:ex3:points:0":"その女の子: that girl.","grammar:562:ex3:points:1":"友達：friend.","grammar:562:ex4:trans":"A girl is playing.","grammar:562:ex4:structure":"〜が遊んでいる","grammar:562:ex4:words:0:zh":"girl","grammar:562:ex4:words:0:note":"おんなのこ","grammar:562:ex4:words:0:pos":"noun","grammar:562:ex4:words:1:zh":"(nominative)","grammar:562:ex4:words:1:pos":"particle","grammar:562:ex4:words:2:zh":"playing","grammar:562:ex4:words:2:note":"あそんでいる","grammar:562:ex4:words:2:pos":"verb","grammar:562:ex4:points:0":"〜ている: ongoing action.","grammar:562:ex4:points:1":"女の子が遊ぶ: a girl plays.","grammar:562:ex5:trans":"I like girls.","grammar:562:ex5:structure":"〜が好きです","grammar:562:ex5:words:0:zh":"I","grammar:562:ex5:words:0:note":"わたし","grammar:562:ex5:words:0:pos":"pronoun","grammar:562:ex5:words:1:zh":"(topic)","grammar:562:ex5:words:1:pos":"particle","grammar:562:ex5:words:2:zh":"girl","grammar:562:ex5:words:2:note":"おんなのこ","grammar:562:ex5:words:2:pos":"noun","grammar:562:ex5:words:3:zh":"(object)","grammar:562:ex5:words:3:pos":"particle","grammar:562:ex5:words:4:zh":"to like","grammar:562:ex5:words:4:note":"すき","grammar:562:ex5:words:4:pos":"na-adjective","grammar:562:ex5:words:5:zh":"(polite form)","grammar:562:ex5:words:5:pos":"copula","grammar:562:ex5:points:0":"The object of 「好き」 takes が.","grammar:562:ex5:points:1":"女の子が好き: to like girls.","exam:562:zh":"My little sister is still a five-year-old girl.","exam:562:why":"「女の子」 refers to a girl. 「女の人」 usually means an adult woman, which doesn't suit a five-year-old little sister here."},"564":{"example:564:exzh":"I dislike spicy food.","example:564:exzh2":"He dislikes dogs.","example:564:exzh3":"Please don't do the things I dislike.","example:564:exzh4":"I dislike bitter medicine.","example:564:exzh5":"She dislikes that movie.","grammar:564:ex:trans":"I don't like spicy food.","grammar:564:ex:structure":"〜は〜が嫌いです","grammar:564:ex:explain":"This sentence uses the pattern 「〜は〜が嫌いです」 for likes and dislikes. Note that the thing you dislike takes 「が」, not 「を」: 「辛い食べ物が嫌い」 means to dislike spicy food. 「嫌い」 (きらい) is a na-adjective meaning disliked, the target takes 「が」, and adding 「です」 makes it polite. The sentence uses 「は」 to set the broad topic, 「私」 (I), and 「が」 to single out the thing disliked. 「辛い」 (spicy) is an i-adjective modifying 「食べ物」 (food). The whole sentence means I don't like spicy food. The key point is that the target of likes and dislikes (好き／嫌い) takes 「が」.","grammar:564:ex:words:0:zh":"I","grammar:564:ex:words:0:note":"わたし","grammar:564:ex:words:0:pos":"pronoun","grammar:564:ex:words:1:zh":"(topic)","grammar:564:ex:words:1:pos":"particle","grammar:564:ex:words:2:zh":"spicy","grammar:564:ex:words:2:note":"からい","grammar:564:ex:words:2:pos":"adjective","grammar:564:ex:words:3:zh":"food","grammar:564:ex:words:3:note":"たべもの","grammar:564:ex:words:3:pos":"noun","grammar:564:ex:words:4:zh":"(object)","grammar:564:ex:words:4:pos":"particle","grammar:564:ex:words:5:zh":"unpleasant, annoying","grammar:564:ex:words:5:note":"きらい","grammar:564:ex:words:5:pos":"na-adjective","grammar:564:ex:words:6:zh":"(polite form)","grammar:564:ex:words:6:pos":"copula","grammar:564:ex:points:0":"❗嫌い (きらい): to dislike, to not like (na-adjective); the target takes が.","grammar:564:ex:points:1":"辛い食べ物: spicy food.","grammar:564:ex2:trans":"He doesn't like dogs.","grammar:564:ex2:structure":"〜が嫌いだ","grammar:564:ex2:words:0:zh":"he","grammar:564:ex2:words:0:note":"かれ","grammar:564:ex2:words:0:pos":"pronoun","grammar:564:ex2:words:1:zh":"(topic)","grammar:564:ex2:words:1:pos":"particle","grammar:564:ex2:words:2:zh":"dog","grammar:564:ex2:words:2:note":"いぬ","grammar:564:ex2:words:2:pos":"noun","grammar:564:ex2:words:3:zh":"(object)","grammar:564:ex2:words:3:pos":"particle","grammar:564:ex2:words:4:zh":"unpleasant, annoying","grammar:564:ex2:words:4:note":"きらい","grammar:564:ex2:words:4:pos":"na-adjective","grammar:564:ex2:words:5:zh":"is","grammar:564:ex2:words:5:pos":"copula","grammar:564:ex2:points:0":"犬が嫌い: to dislike dogs (the target takes が).","grammar:564:ex2:points:1":"嫌いだ: to dislike (plain form).","grammar:564:ex3:trans":"Please don't do things I dislike.","grammar:564:ex3:structure":"〜なことをしないでください","grammar:564:ex3:words:0:zh":"unpleasant, annoying","grammar:564:ex3:words:0:note":"きらい","grammar:564:ex3:words:0:pos":"na-adjective","grammar:564:ex3:words:1:zh":"(attributive form)","grammar:564:ex3:words:1:pos":"auxiliary verb","grammar:564:ex3:words:2:zh":"thing / matter","grammar:564:ex3:words:2:pos":"noun","grammar:564:ex3:words:3:zh":"(object marker)","grammar:564:ex3:words:3:pos":"particle","grammar:564:ex3:words:4:zh":"don't do (it)","grammar:564:ex3:words:4:pos":"verb","grammar:564:ex3:words:5:zh":"please","grammar:564:ex3:words:5:pos":"auxiliary verb","grammar:564:ex3:points:0":"嫌いなこと: things you dislike (な + noun).","grammar:564:ex3:points:1":"「〜ないでください」: please don't …","grammar:564:ex4:trans":"I don't like bitter medicine.","grammar:564:ex4:structure":"〜が嫌いです","grammar:564:ex4:words:0:zh":"bitter","grammar:564:ex4:words:0:note":"にがい","grammar:564:ex4:words:0:pos":"adjective","grammar:564:ex4:words:1:zh":"medicine","grammar:564:ex4:words:1:note":"くすり","grammar:564:ex4:words:1:pos":"noun","grammar:564:ex4:words:2:zh":"(object)","grammar:564:ex4:words:2:pos":"particle","grammar:564:ex4:words:3:zh":"unpleasant, annoying","grammar:564:ex4:words:3:note":"きらい","grammar:564:ex4:words:3:pos":"na-adjective","grammar:564:ex4:words:4:zh":"(polite form)","grammar:564:ex4:words:4:pos":"copula","grammar:564:ex4:points:0":"苦い薬: bitter medicine.","grammar:564:ex4:points:1":"薬が嫌い: to dislike medicine.","grammar:564:ex5:trans":"She doesn't like that movie.","grammar:564:ex5:structure":"〜が嫌いです","grammar:564:ex5:words:0:zh":"she","grammar:564:ex5:words:0:note":"かのじょ","grammar:564:ex5:words:0:pos":"pronoun","grammar:564:ex5:words:1:zh":"(topic)","grammar:564:ex5:words:1:pos":"particle","grammar:564:ex5:words:2:zh":"that","grammar:564:ex5:words:2:pos":"pre-noun adjectival","grammar:564:ex5:words:3:zh":"movie","grammar:564:ex5:words:3:note":"えいが","grammar:564:ex5:words:3:pos":"noun","grammar:564:ex5:words:4:zh":"(object)","grammar:564:ex5:words:4:pos":"particle","grammar:564:ex5:words:5:zh":"unpleasant, annoying","grammar:564:ex5:words:5:note":"きらい","grammar:564:ex5:words:5:pos":"na-adjective","grammar:564:ex5:words:6:zh":"(polite form)","grammar:564:ex5:words:6:pos":"copula","grammar:564:ex5:points:0":"映画が嫌い: to dislike the movie.","grammar:564:ex5:points:1":"その映画: that movie.","exam:564:zh":"I don't like fish, so I don't want to eat fish dishes.","exam:564:why":"「嫌い」 means to dislike, which matches the following 「食べたくありません」. 「好き」 means to like, the opposite."},"565":{"example:565:exzh":"That book has great value.","example:565:exzh2":"Values differ from person to person.","example:565:exzh3":"His opinion is valuable.","example:565:exzh4":"Finding the value in life is important.","example:565:exzh5":"This jewel has great value."},"567":{"example:567:exzh":"I'm from California.","example:567:exzh2":"This state has many tourist attractions.","example:567:exzh3":"State laws can differ.","example:567:exzh4":"Do you know the names of the US states?","example:567:exzh5":"The climate in this state is warm."},"568":{"example:568:exzh":"This piece of clothing is very cute.","example:568:exzh2":"I like buying clothes.","example:568:exzh3":"I feel good when I put on new clothes.","example:568:exzh4":"It's important to pay attention to your clothing.","example:568:exzh5":"She has stylish clothes.","grammar:568:ex:trans":"This piece of clothing is really cute.","grammar:568:ex:structure":"〜はとても〜です","grammar:568:ex:explain":"This is an i-adjective predicate sentence, 「〜はとても〜です」. 「かわいい」 (cute) is an i-adjective; as the predicate it takes 「です」 to become polite, and the degree adverb 「とても」 (very) modifies it. The opening 「この服は」 uses 「は」 to mark the topic, this piece of clothing. The keyword 「服（ふく）」 means clothes. The whole sentence means This piece of clothing is really cute. This is the typical structure of topic は + degree adverb + i-adjective です, the same type as the earlier 「この映画は面白いです」, used to evaluate something while adding a degree of intensity.","grammar:568:ex:words:0:zh":"this","grammar:568:ex:words:0:pos":"pre-noun adjectival","grammar:568:ex:words:1:zh":"clothes","grammar:568:ex:words:1:note":"ふく","grammar:568:ex:words:1:pos":"noun","grammar:568:ex:words:2:zh":"(topic)","grammar:568:ex:words:2:pos":"particle","grammar:568:ex:words:3:zh":"extremely","grammar:568:ex:words:3:pos":"adverb","grammar:568:ex:words:4:zh":"cute","grammar:568:ex:words:4:pos":"adjective","grammar:568:ex:words:5:zh":"(polite form)","grammar:568:ex:words:5:pos":"copula","grammar:568:ex:points:0":"服（ふく）: clothes.","grammar:568:ex:points:1":"かわいい: cute.","grammar:568:ex2:trans":"I like buying clothes.","grammar:568:ex2:structure":"〜のが好きです","grammar:568:ex2:words:0:zh":"clothes","grammar:568:ex2:words:0:note":"ふく","grammar:568:ex2:words:0:pos":"noun","grammar:568:ex2:words:1:zh":"(object marker)","grammar:568:ex2:words:1:pos":"particle","grammar:568:ex2:words:2:zh":"buy","grammar:568:ex2:words:2:note":"かう","grammar:568:ex2:words:2:pos":"verb","grammar:568:ex2:words:3:zh":"(nominalizer)","grammar:568:ex2:words:3:pos":"particle","grammar:568:ex2:words:4:zh":"(object)","grammar:568:ex2:words:4:pos":"particle","grammar:568:ex2:words:5:zh":"to like","grammar:568:ex2:words:5:note":"すき","grammar:568:ex2:words:5:pos":"na-adjective","grammar:568:ex2:words:6:zh":"(polite form)","grammar:568:ex2:words:6:pos":"copula","grammar:568:ex2:points:0":"服を買う: to buy clothes.","grammar:568:ex2:points:1":"〜のが好き: to like doing…","grammar:568:ex3:trans":"Putting on new clothes puts me in a good mood.","grammar:568:ex3:structure":"〜たら〜がいい","grammar:568:ex3:words:0:zh":"new","grammar:568:ex3:words:0:note":"あたらしい","grammar:568:ex3:words:0:pos":"adjective","grammar:568:ex3:words:1:zh":"clothes","grammar:568:ex3:words:1:note":"ふく","grammar:568:ex3:words:1:pos":"noun","grammar:568:ex3:words:2:zh":"(object marker)","grammar:568:ex3:words:2:pos":"particle","grammar:568:ex3:words:3:zh":"when you put on","grammar:568:ex3:words:3:note":"きたら","grammar:568:ex3:words:3:pos":"verb","grammar:568:ex3:words:4:zh":"feeling","grammar:568:ex3:words:4:note":"きぶん","grammar:568:ex3:words:4:pos":"noun","grammar:568:ex3:words:5:zh":"(nominative)","grammar:568:ex3:words:5:pos":"particle","grammar:568:ex3:words:6:zh":"good","grammar:568:ex3:words:6:pos":"adjective","grammar:568:ex3:points:0":"〜たら: after (finishing) … (conditional).","grammar:568:ex3:points:1":"服を着る: to put on clothes; 気分がいい: to feel good.","grammar:568:ex4:trans":"Being mindful of your clothing matters.","grammar:568:ex4:structure":"〜に気を使うことは大事です","grammar:568:ex4:words:0:zh":"clothing","grammar:568:ex4:words:0:note":"ふくそう","grammar:568:ex4:words:0:pos":"noun","grammar:568:ex4:words:1:zh":"(object)","grammar:568:ex4:words:1:pos":"particle","grammar:568:ex4:words:2:zh":"be mindful of","grammar:568:ex4:words:2:note":"きをつかう","grammar:568:ex4:words:2:pos":"set phrase","grammar:568:ex4:words:3:zh":"(nominalizer)","grammar:568:ex4:words:3:pos":"noun","grammar:568:ex4:words:4:zh":"(topic)","grammar:568:ex4:words:4:pos":"particle","grammar:568:ex4:words:5:zh":"important","grammar:568:ex4:words:5:note":"だいじ","grammar:568:ex4:words:5:pos":"na-adjective","grammar:568:ex4:words:6:zh":"(polite form)","grammar:568:ex4:words:6:pos":"copula","grammar:568:ex4:points:0":"〜に気を使う: to be mindful of …, to pay attention to … (the object takes に).","grammar:568:ex4:points:1":"服装: clothing, outfit.","grammar:568:ex5:trans":"She has stylish clothes.","grammar:568:ex5:structure":"〜を持っている","grammar:568:ex5:words:0:zh":"she","grammar:568:ex5:words:0:note":"かのじょ","grammar:568:ex5:words:0:pos":"pronoun","grammar:568:ex5:words:1:zh":"(topic)","grammar:568:ex5:words:1:pos":"particle","grammar:568:ex5:words:2:zh":"stylish","grammar:568:ex5:words:2:pos":"na-adjective","grammar:568:ex5:words:3:zh":"(attributive form)","grammar:568:ex5:words:3:pos":"auxiliary verb","grammar:568:ex5:words:4:zh":"clothes","grammar:568:ex5:words:4:note":"ふく","grammar:568:ex5:words:4:pos":"noun","grammar:568:ex5:words:5:zh":"(object marker)","grammar:568:ex5:words:5:pos":"particle","grammar:568:ex5:words:6:zh":"own, have","grammar:568:ex5:words:6:note":"もっている","grammar:568:ex5:words:6:pos":"verb","grammar:568:ex5:points:0":"おしゃれな服: stylish clothes (な + noun).","grammar:568:ex5:points:1":"〜を持っている: to have….","exam:568:zh":"I washed clothes like shirts and sweaters.","exam:568:why":"Shirts and sweaters are both 「服」. 「帽子」 is something you wear too, but it can't be the general word for shirts and sweaters."},"569":{"example:569:exzh":"Our future is bright.","example:569:exzh2":"Make plans for the future.","example:569:exzh3":"I'm interested in the technology of the future.","example:569:exzh4":"He believes in the future.","example:569:exzh5":"I have high expectations for the future of education."},"570":{"example:570:exzh":"Please be sure to come tomorrow.","example:570:exzh2":"To succeed, effort is absolutely necessary.","example:570:exzh3":"She always keeps her promises.","example:570:exzh4":"To get a good score on the test, you absolutely need to study.","example:570:exzh5":"Even if I'm late, I will definitely contact you.","grammar:570:ex:trans":"Please be sure to come tomorrow.","grammar:570:ex:structure":"必ず〜てください","grammar:570:ex:explain":"This is the request pattern 「〜てください」, and the key adverb is 「必ず」. 「必ず（かならず）」 means be sure to, without fail; it stresses certainty and obligation and strengthens the request. The te-form of 「来る」 (to come) is 「来て」, which with 「ください」 becomes please come, and adding 「必ず」 gives please be sure to come. The opening 「明日は」 is the time word tomorrow. The whole sentence means Please be sure to come tomorrow. 「必ず」 has a careful, earnest tone, so it is more emphatic than a plain 「〜てください」.","grammar:570:ex:words:0:zh":"tomorrow","grammar:570:ex:words:0:note":"あした","grammar:570:ex:words:0:pos":"noun","grammar:570:ex:words:1:zh":"(topic)","grammar:570:ex:words:1:pos":"particle","grammar:570:ex:words:2:zh":"definitely","grammar:570:ex:words:2:note":"かならず","grammar:570:ex:words:2:pos":"adverb","grammar:570:ex:words:3:zh":"come","grammar:570:ex:words:3:note":"きて","grammar:570:ex:words:3:pos":"verb","grammar:570:ex:words:4:zh":"please","grammar:570:ex:words:4:pos":"auxiliary verb","grammar:570:ex:points:0":"❗必ず: be sure to, without fail (emphasizes certainty).","grammar:570:ex:points:1":"来る→来て＋ください.","grammar:570:ex2:trans":"To succeed, effort is absolutely necessary.","grammar:570:ex2:structure":"〜ためには必ず〜が必要です","grammar:570:ex2:words:0:zh":"success","grammar:570:ex2:words:0:note":"せいこうする","grammar:570:ex2:words:0:pos":"verb","grammar:570:ex2:words:1:zh":"for the sake of","grammar:570:ex2:words:1:pos":"set phrase","grammar:570:ex2:words:2:zh":"definitely","grammar:570:ex2:words:2:note":"かならず","grammar:570:ex2:words:2:pos":"adverb","grammar:570:ex2:words:3:zh":"effort","grammar:570:ex2:words:3:note":"どりょく","grammar:570:ex2:words:3:pos":"noun","grammar:570:ex2:words:4:zh":"(nominative)","grammar:570:ex2:words:4:pos":"particle","grammar:570:ex2:words:5:zh":"necessary","grammar:570:ex2:words:5:note":"ひつよう","grammar:570:ex2:words:5:pos":"na-adjective","grammar:570:ex2:words:6:zh":"(polite form)","grammar:570:ex2:words:6:pos":"copula","grammar:570:ex2:points:0":"〜ためには: in order to ….","grammar:570:ex2:points:1":"必ず〜が必要: … is absolutely necessary.","grammar:570:ex3:trans":"She always keeps her promises.","grammar:570:ex3:structure":"必ず〜ます","grammar:570:ex3:words:0:zh":"she","grammar:570:ex3:words:0:note":"かのじょ","grammar:570:ex3:words:0:pos":"pronoun","grammar:570:ex3:words:1:zh":"(topic)","grammar:570:ex3:words:1:pos":"particle","grammar:570:ex3:words:2:zh":"definitely","grammar:570:ex3:words:2:note":"かならず","grammar:570:ex3:words:2:pos":"adverb","grammar:570:ex3:words:3:zh":"appointment","grammar:570:ex3:words:3:note":"やくそく","grammar:570:ex3:words:3:pos":"noun","grammar:570:ex3:words:4:zh":"(object marker)","grammar:570:ex3:words:4:pos":"particle","grammar:570:ex3:words:5:zh":"obey","grammar:570:ex3:words:5:note":"まもります","grammar:570:ex3:words:5:pos":"verb","grammar:570:ex3:points:0":"必ず〜守る: to always keep (a promise).","grammar:570:ex3:points:1":"約束を守る: to keep a promise.","grammar:570:ex4:trans":"To get a good score on the exam, studying is absolutely necessary.","grammar:570:ex4:structure":"〜には必ず〜が必要です","grammar:570:ex4:words:0:zh":"test","grammar:570:ex4:words:0:note":"しけん","grammar:570:ex4:words:0:pos":"noun","grammar:570:ex4:words:1:zh":"(scope)","grammar:570:ex4:words:1:pos":"particle","grammar:570:ex4:words:2:zh":"good","grammar:570:ex4:words:2:pos":"adjective","grammar:570:ex4:words:3:zh":"score","grammar:570:ex4:words:3:note":"てん","grammar:570:ex4:words:3:pos":"noun","grammar:570:ex4:words:4:zh":"(object marker)","grammar:570:ex4:words:4:pos":"particle","grammar:570:ex4:words:5:zh":"obtain","grammar:570:ex4:words:5:note":"とる","grammar:570:ex4:words:5:pos":"verb","grammar:570:ex4:words:6:zh":"for the sake of","grammar:570:ex4:words:6:pos":"particle","grammar:570:ex4:words:7:zh":"definitely","grammar:570:ex4:words:7:note":"かならず","grammar:570:ex4:words:7:pos":"adverb","grammar:570:ex4:words:8:zh":"study","grammar:570:ex4:words:8:note":"べんきょう","grammar:570:ex4:words:8:pos":"noun","grammar:570:ex4:words:9:zh":"(nominative)","grammar:570:ex4:words:9:pos":"particle","grammar:570:ex4:words:10:zh":"necessary","grammar:570:ex4:words:10:note":"ひつよう","grammar:570:ex4:words:10:pos":"na-adjective","grammar:570:ex4:words:11:zh":"(polite form)","grammar:570:ex4:words:11:pos":"copula","grammar:570:ex4:points:0":"〜には: in order to ….","grammar:570:ex4:points:1":"いい点を取る: to get a good score.","grammar:570:ex5:trans":"Even if it gets late, I'll definitely get in touch.","grammar:570:ex5:structure":"〜ても必ず〜します","grammar:570:ex5:words:0:zh":"even if it gets late","grammar:570:ex5:words:0:note":"おそくなっても","grammar:570:ex5:words:0:pos":"verb","grammar:570:ex5:words:1:zh":"definitely","grammar:570:ex5:words:1:note":"かならず","grammar:570:ex5:words:1:pos":"adverb","grammar:570:ex5:words:2:zh":"contact","grammar:570:ex5:words:2:note":"れんらくします","grammar:570:ex5:words:2:pos":"verb","grammar:570:ex5:points:0":"〜ても: even if ….","grammar:570:ex5:points:1":"必ず連絡する: to be sure to get in touch."},"571":{"example:571:exzh":"That building is tall.","example:571:exzh2":"There are many companies inside the building.","example:571:exzh3":"This building was newly built.","example:571:exzh4":"The view from the building's rooftop is wonderful.","example:571:exzh5":"There is a building near the house.","grammar:571:ex:trans":"That building is tall.","grammar:571:ex:structure":"〜は高いです","grammar:571:ex:explain":"This is an i-adjective predicate sentence, 「〜は高いです」. 「高い（たかい）」 is an i-adjective; here it means tall (of a structure), and as the predicate it takes 「です」 to become polite. The opening 「あのビルは」 uses 「は」 to mark the topic, that building, and 「あの」 is the far demonstrative that. The keyword 「ビル」 is the loanword building, meaning a building or office building. The whole sentence means That building is tall. Note that 「高い」 can mean both tall and expensive, but describing a building it naturally means tall.","grammar:571:ex:words:0:zh":"that","grammar:571:ex:words:0:pos":"pre-noun adjectival","grammar:571:ex:words:1:zh":"building","grammar:571:ex:words:1:note":"loanword","grammar:571:ex:words:1:pos":"noun","grammar:571:ex:words:2:zh":"(topic)","grammar:571:ex:words:2:pos":"particle","grammar:571:ex:words:3:zh":"tall","grammar:571:ex:words:3:note":"たかい","grammar:571:ex:words:3:pos":"adjective","grammar:571:ex:words:4:zh":"(polite form)","grammar:571:ex:words:4:pos":"copula","grammar:571:ex:points:0":"ビル: building, office building (from the English word building).","grammar:571:ex:points:1":"高い: tall, high.","grammar:571:ex2:trans":"There are many companies inside the building.","grammar:571:ex2:structure":"〜には〜があります (〜 has 〜)","grammar:571:ex2:words:0:zh":"building","grammar:571:ex2:words:0:note":"loanword","grammar:571:ex2:words:0:pos":"noun","grammar:571:ex2:words:1:zh":"'s","grammar:571:ex2:words:1:pos":"particle","grammar:571:ex2:words:2:zh":"inside","grammar:571:ex2:words:2:note":"なか","grammar:571:ex2:words:2:pos":"noun","grammar:571:ex2:words:3:zh":"(location of existence)","grammar:571:ex2:words:3:pos":"particle","grammar:571:ex2:words:4:zh":"(contrast)","grammar:571:ex2:words:4:pos":"particle","grammar:571:ex2:words:5:zh":"company","grammar:571:ex2:words:5:note":"かいしゃ","grammar:571:ex2:words:5:pos":"noun","grammar:571:ex2:words:6:zh":"(nominative)","grammar:571:ex2:words:6:pos":"particle","grammar:571:ex2:words:7:zh":"a lot","grammar:571:ex2:words:7:pos":"adverb","grammar:571:ex2:words:8:zh":"there is / are","grammar:571:ex2:words:8:pos":"verb","grammar:571:ex2:points:0":"ビルの中に: inside the building.","grammar:571:ex2:points:1":"〜には〜がある: … has…, there is… in…","grammar:571:ex3:trans":"This building was newly built.","grammar:571:ex3:structure":"〜が建てられました","grammar:571:ex3:words:0:zh":"this","grammar:571:ex3:words:0:pos":"pre-noun adjectival","grammar:571:ex3:words:1:zh":"building","grammar:571:ex3:words:1:note":"loanword","grammar:571:ex3:words:1:pos":"noun","grammar:571:ex3:words:2:zh":"(topic)","grammar:571:ex3:words:2:pos":"particle","grammar:571:ex3:words:3:zh":"newly","grammar:571:ex3:words:3:note":"あたらしく","grammar:571:ex3:words:3:pos":"adverb","grammar:571:ex3:words:4:zh":"was built","grammar:571:ex3:words:4:note":"たてられました (passive)","grammar:571:ex3:words:4:pos":"verb","grammar:571:ex3:points:0":"建てられる: to be built (passive; 建てる→建てられる).","grammar:571:ex3:points:1":"新しく: newly.","grammar:571:ex4:trans":"The view from the rooftop of the building is wonderful.","grammar:571:ex4:structure":"〜からの〜は〜です","grammar:571:ex4:words:0:zh":"building","grammar:571:ex4:words:0:note":"loanword","grammar:571:ex4:words:0:pos":"noun","grammar:571:ex4:words:1:zh":"'s","grammar:571:ex4:words:1:pos":"particle","grammar:571:ex4:words:2:zh":"rooftop","grammar:571:ex4:words:2:note":"おくじょう","grammar:571:ex4:words:2:pos":"noun","grammar:571:ex4:words:3:zh":"from","grammar:571:ex4:words:3:pos":"particle","grammar:571:ex4:words:4:zh":"'s","grammar:571:ex4:words:4:pos":"particle","grammar:571:ex4:words:5:zh":"scenery","grammar:571:ex4:words:5:note":"けしき","grammar:571:ex4:words:5:pos":"noun","grammar:571:ex4:words:6:zh":"(topic)","grammar:571:ex4:words:6:pos":"particle","grammar:571:ex4:words:7:zh":"great","grammar:571:ex4:words:7:note":"すばらしい","grammar:571:ex4:words:7:pos":"adjective","grammar:571:ex4:words:8:zh":"(polite form)","grammar:571:ex4:words:8:pos":"copula","grammar:571:ex4:points:0":"〜からの景色: the view from … (から + の modifies a noun).","grammar:571:ex4:points:1":"屋上: rooftop, top floor.","grammar:571:ex5:trans":"There is a building near home.","grammar:571:ex5:structure":"〜にあります","grammar:571:ex5:words:0:zh":"house","grammar:571:ex5:words:0:note":"いえ","grammar:571:ex5:words:0:pos":"noun","grammar:571:ex5:words:1:zh":"'s","grammar:571:ex5:words:1:pos":"particle","grammar:571:ex5:words:2:zh":"nearby","grammar:571:ex5:words:2:note":"ちかく","grammar:571:ex5:words:2:pos":"noun","grammar:571:ex5:words:3:zh":"(location of existence)","grammar:571:ex5:words:3:pos":"particle","grammar:571:ex5:words:4:zh":"building","grammar:571:ex5:words:4:note":"loanword","grammar:571:ex5:words:4:pos":"noun","grammar:571:ex5:words:5:zh":"(nominative)","grammar:571:ex5:words:5:pos":"particle","grammar:571:ex5:words:6:zh":"there is / are","grammar:571:ex5:words:6:pos":"verb","grammar:571:ex5:points:0":"家の近く: near home.","grammar:571:ex5:points:1":"〜にあります: be at/in … (inanimate things).","exam:571:zh":"The company is on the eighth floor of a ten-story building in front of the station.","exam:571:why":"「ビル」 means building, and it fits with 「十階建て」 and 「八階」. 「部屋」 is a room, which doesn't itself have an eighth floor."},"572":{"example:572:exzh":"I've met him before.","example:572:exzh2":"Have you seen this movie before?","example:572:exzh3":"There used to be a school here.","example:572:exzh4":"I don't remember much about the past.","example:572:exzh5":"He has grown more than before."},"573":{"example:573:exzh":"He took that opportunity away.","example:573:exzh2":"The scenery captivates my heart.","example:573:exzh3":"Seizing power is not easy.","example:573:exzh4":"That movie grabbed my attention.","example:573:exzh5":"She took his love away from him."},"574":{"example:574:exzh":"He is like a hero.","example:574:exzh2":"It was just like a dream.","example:574:exzh3":"A view just like a movie.","example:574:exzh4":"She looks just like an angel.","example:574:exzh5":"His story sounded as if it were true."},"575":{"example:575:exzh":"He told a lie.","example:575:exzh2":"That story is a lie.","example:575:exzh3":"Lying is not good.","example:575:exzh4":"It's hard to see through a lie.","example:575:exzh5":"Her lie was easily found out.","grammar:575:ex:trans":"He told a lie.","grammar:575:ex:structure":"〜をついた","grammar:575:ex:explain":"This sentence uses the fixed collocation 「ウソをつく」 (to tell a lie). 「ウソ」 (a lie) takes 「を」, and the verb is 「つく」; the two form a set phrase, so Japanese does not use 「言う」 for telling a lie but 「つく」. The ta-form 「ついた」 marks the past. The opening 「彼は」 marks the topic. The whole sentence means He told a lie. This is an idiom to memorize as a whole: the 「つく」 of 「ウソをつく」 is related to the 「つく」 of 「息をつく」 (to take a breath), both meaning to give off or produce some action, so don't replace it with another verb.","grammar:575:ex:words:0:zh":"he","grammar:575:ex:words:0:note":"かれ","grammar:575:ex:words:0:pos":"pronoun","grammar:575:ex:words:1:zh":"(topic)","grammar:575:ex:words:1:pos":"particle","grammar:575:ex:words:2:zh":"lie","grammar:575:ex:words:2:note":"うそ","grammar:575:ex:words:2:pos":"noun","grammar:575:ex:words:3:zh":"(object marker)","grammar:575:ex:words:3:pos":"particle","grammar:575:ex:words:4:zh":"tell (a lie)","grammar:575:ex:words:4:note":"ついた","grammar:575:ex:words:4:pos":"verb","grammar:575:ex:points:0":"❗ウソをつく: to tell a lie (fixed phrase; uses つく).","grammar:575:ex:points:1":"つく→ついた (plain past).","grammar:575:ex2:trans":"That story is a lie.","grammar:575:ex2:structure":"〜はウソだ","grammar:575:ex2:words:0:zh":"that","grammar:575:ex2:words:0:pos":"pre-noun adjectival","grammar:575:ex2:words:1:zh":"story","grammar:575:ex2:words:1:note":"はなし","grammar:575:ex2:words:1:pos":"noun","grammar:575:ex2:words:2:zh":"(topic)","grammar:575:ex2:words:2:pos":"particle","grammar:575:ex2:words:3:zh":"lie","grammar:575:ex2:words:3:note":"うそ","grammar:575:ex2:words:3:pos":"noun","grammar:575:ex2:words:4:zh":"is","grammar:575:ex2:words:4:pos":"copula","grammar:575:ex2:points:1":"その話はウソ: that story is a lie.","grammar:575:ex3:trans":"Telling lies is not good.","grammar:575:ex3:structure":"〜のは良くない","grammar:575:ex3:words:0:zh":"lie","grammar:575:ex3:words:0:note":"うそ","grammar:575:ex3:words:0:pos":"noun","grammar:575:ex3:words:1:zh":"(object marker)","grammar:575:ex3:words:1:pos":"particle","grammar:575:ex3:words:2:zh":"tell","grammar:575:ex3:words:2:pos":"verb","grammar:575:ex3:words:3:zh":"(nominalizer)","grammar:575:ex3:words:3:pos":"particle","grammar:575:ex3:words:4:zh":"(topic)","grammar:575:ex3:words:4:pos":"particle","grammar:575:ex3:words:5:zh":"bad / not good","grammar:575:ex3:words:5:note":"よくない","grammar:575:ex3:words:5:pos":"adjective","grammar:575:ex3:points:0":"ウソをつく: to tell a lie.","grammar:575:ex3:points:1":"〜のは良くない: it's not good to ….","grammar:575:ex4:trans":"Seeing through a lie is difficult.","grammar:575:ex4:structure":"〜のは難しい","grammar:575:ex4:words:0:zh":"lie","grammar:575:ex4:words:0:note":"うそ","grammar:575:ex4:words:0:pos":"noun","grammar:575:ex4:words:1:zh":"(object marker)","grammar:575:ex4:words:1:pos":"particle","grammar:575:ex4:words:2:zh":"see through","grammar:575:ex4:words:2:note":"みぬく","grammar:575:ex4:words:2:pos":"verb","grammar:575:ex4:words:3:zh":"(nominalizer)","grammar:575:ex4:words:3:pos":"particle","grammar:575:ex4:words:4:zh":"(topic)","grammar:575:ex4:words:4:pos":"particle","grammar:575:ex4:words:5:zh":"difficult","grammar:575:ex4:words:5:note":"むずかしい","grammar:575:ex4:words:5:pos":"adjective","grammar:575:ex4:points:0":"ウソを見抜く: to see through a lie.","grammar:575:ex4:points:1":"見抜く: to see through, to spot.","grammar:575:ex5:trans":"Her lie was easily found out.","grammar:575:ex5:structure":"〜は〜ばれた","grammar:575:ex5:words:0:zh":"she","grammar:575:ex5:words:0:note":"かのじょ","grammar:575:ex5:words:0:pos":"pronoun","grammar:575:ex5:words:1:zh":"'s","grammar:575:ex5:words:1:pos":"particle","grammar:575:ex5:words:2:zh":"lie","grammar:575:ex5:words:2:note":"うそ","grammar:575:ex5:words:2:pos":"noun","grammar:575:ex5:words:3:zh":"(topic)","grammar:575:ex5:words:3:pos":"particle","grammar:575:ex5:words:4:zh":"easily","grammar:575:ex5:words:4:note":"かんたんに","grammar:575:ex5:words:4:pos":"adverb","grammar:575:ex5:words:5:zh":"was found out","grammar:575:ex5:words:5:pos":"verb","grammar:575:ex5:points:0":"ばれる: (of a secret or lie) to come to light, to be found out.","grammar:575:ex5:points:1":"簡単に: easily (na-adjective + に)."},"576":{"example:576:exzh":"We leave at three.","example:576:exzh2":"We plan to go as a group of three.","example:576:exzh3":"I came here three years ago.","example:576:exzh4":"A triangle has three sides.","example:576:exzh5":"We're going on a trip in three months.","grammar:576:ex:trans":"We depart at three o'clock.","grammar:576:ex:structure":"〔number〕時に＋verb","grammar:576:ex:explain":"「三」 is read さん and is the most basic number; with counters it is usually read as is, as in 「三時（さんじ）」 and 「三人（さんにん）」. With some counters, though, the sound changes, for example 「三本（さんぼん）」 and 「三階（さんがい）」, so you have to memorize them one by one. In this sentence 「三時に」 specifies the departure time, 「に」 marks the time point, and 「出発します」 uses the masu-form to talk about a planned schedule.","grammar:576:ex:words:0:zh":"three","grammar:576:ex:words:0:note":"さん","grammar:576:ex:words:0:pos":"numeral","grammar:576:ex:words:1:zh":"o'clock","grammar:576:ex:words:1:note":"じ","grammar:576:ex:words:1:pos":"suffix","grammar:576:ex:words:2:zh":"(point in time)","grammar:576:ex:words:2:pos":"particle","grammar:576:ex:words:3:zh":"depart","grammar:576:ex:words:3:note":"しゅっぱつします; masu-form","grammar:576:ex:words:3:pos":"verb","grammar:576:ex:points:0":"「三時」: 「三」 is read さん, followed by 「時（じ）」 to mean the hour; note that four o'clock is 「よじ」 and nine o'clock is 「くじ」, while three o'clock has no special reading.","grammar:576:ex:points:1":"After a specific time, 「に」 marks the point in time when the action happens.","grammar:576:ex:points:2":"「出発します」 is the masu-form of 出発する and here expresses something scheduled to happen.","grammar:576:ex2:trans":"We're planning to go as a group of three.","grammar:576:ex2:structure":"〜人で〜つもりです","grammar:576:ex2:words:0:zh":"three people","grammar:576:ex2:words:0:note":"さんにん","grammar:576:ex2:words:0:pos":"noun","grammar:576:ex2:words:1:zh":"(the whole group)","grammar:576:ex2:words:1:pos":"particle","grammar:576:ex2:words:2:zh":"go","grammar:576:ex2:words:2:note":"いく","grammar:576:ex2:words:2:pos":"verb","grammar:576:ex2:words:3:zh":"intend to","grammar:576:ex2:words:3:pos":"noun","grammar:576:ex2:words:4:zh":"(polite form)","grammar:576:ex2:words:4:pos":"copula","grammar:576:ex2:points:0":"三人（さんにん）: three people.","grammar:576:ex2:points:1":"〜つもりです: intend to ….","grammar:576:ex3:trans":"I came here three years ago.","grammar:576:ex3:structure":"〜前に来ました","grammar:576:ex3:words:0:zh":"three years ago","grammar:576:ex3:words:0:note":"さんねんまえ","grammar:576:ex3:words:0:pos":"noun","grammar:576:ex3:words:1:zh":"(point in time)","grammar:576:ex3:words:1:pos":"particle","grammar:576:ex3:words:2:zh":"here","grammar:576:ex3:words:2:pos":"pronoun","grammar:576:ex3:words:3:zh":"(destination)","grammar:576:ex3:words:3:pos":"particle","grammar:576:ex3:words:4:zh":"came","grammar:576:ex3:words:4:note":"きました","grammar:576:ex3:words:4:pos":"verb","grammar:576:ex3:points:0":"三年前に: three years ago (time point + に).","grammar:576:ex3:points:1":"来る → 来ました.","grammar:576:ex4:trans":"A triangle has three sides.","grammar:576:ex4:structure":"〜は〜がある","grammar:576:ex4:words:0:zh":"triangle","grammar:576:ex4:words:0:note":"さんかくけい","grammar:576:ex4:words:0:pos":"noun","grammar:576:ex4:words:1:zh":"(topic)","grammar:576:ex4:words:1:pos":"particle","grammar:576:ex4:words:2:zh":"three","grammar:576:ex4:words:2:note":"みっつ","grammar:576:ex4:words:2:pos":"noun","grammar:576:ex4:words:3:zh":"'s","grammar:576:ex4:words:3:pos":"particle","grammar:576:ex4:words:4:zh":"side","grammar:576:ex4:words:4:note":"へん","grammar:576:ex4:words:4:pos":"noun","grammar:576:ex4:words:5:zh":"(nominative)","grammar:576:ex4:words:5:pos":"particle","grammar:576:ex4:words:6:zh":"there is / are","grammar:576:ex4:words:6:pos":"verb","grammar:576:ex4:points:0":"三角形: triangle (三 + 角形).","grammar:576:ex4:points:1":"三つの辺: three sides.","grammar:576:ex5:trans":"We'll go on a trip in three months.","grammar:576:ex5:structure":"〜後に〜します","grammar:576:ex5:words:0:zh":"three months later","grammar:576:ex5:words:0:note":"さんかげつご","grammar:576:ex5:words:0:pos":"noun","grammar:576:ex5:words:1:zh":"(point in time)","grammar:576:ex5:words:1:pos":"particle","grammar:576:ex5:words:2:zh":"travel / trip","grammar:576:ex5:words:2:note":"りょこうします","grammar:576:ex5:words:2:pos":"verb","grammar:576:ex5:points:0":"三ヶ月後: three months later.","grammar:576:ex5:points:1":"旅行する: travel.","exam:576:zh":"I bought one apple and then two more, so there are three in total.","exam:576:why":"One plus two makes 「三」 in total. 「二」 only counts the ones bought later."},"578":{"example:578:exzh":"This is seriously interesting!","example:578:exzh2":"Let's seriously go!","example:578:exzh3":"He's seriously kind.","example:578:exzh4":"I need to think about it seriously.","example:578:exzh5":"This is seriously the best!"},"579":{"example:579:exzh":"My parents support me.","example:579:exzh2":"His parents are very kind.","example:579:exzh3":"I'm traveling with my parents.","example:579:exzh4":"My parents moved last year.","example:579:exzh5":"I'm grateful to my parents.","grammar:579:ex:trans":"My parents support me.","grammar:579:ex:structure":"〜を〜てくれます","grammar:579:ex:explain":"The key point of this sentence is the giving-and-receiving verb 「〜てくれる」. 「〜てくれる」 means someone does something for me or my side, with the sense that the other person is doing me a favor and I benefit. Here 「支えてくれます」 means they give me their support: the te-form of 「支える」 (to support) plus 「くれます」. The object 「私」 (me) takes 「を」. The opening 「両親」 (parents) is the subject. The whole sentence means My parents support me. 「〜てくれる」 stresses that the favor flows from someone else to me, and it is an important part of Japanese giving-and-receiving expressions.","grammar:579:ex:words:0:zh":"parents","grammar:579:ex:words:0:note":"りょうしん","grammar:579:ex:words:0:pos":"noun","grammar:579:ex:words:1:zh":"(topic)","grammar:579:ex:words:1:pos":"particle","grammar:579:ex:words:2:zh":"I","grammar:579:ex:words:2:note":"わたし","grammar:579:ex:words:2:pos":"pronoun","grammar:579:ex:words:3:zh":"(object marker)","grammar:579:ex:words:3:pos":"particle","grammar:579:ex:words:4:zh":"support","grammar:579:ex:words:4:note":"ささえて","grammar:579:ex:words:4:pos":"verb","grammar:579:ex:words:5:zh":"(for me)","grammar:579:ex:words:5:pos":"auxiliary verb","grammar:579:ex:points:0":"❗〜てくれる: (someone) does … for me (giving and receiving).","grammar:579:ex:points:1":"両親（りょうしん）: (both) parents.","grammar:579:ex2:trans":"His parents are kind.","grammar:579:ex2:structure":"〜は〜です","grammar:579:ex2:words:0:zh":"he","grammar:579:ex2:words:0:note":"かれ","grammar:579:ex2:words:0:pos":"pronoun","grammar:579:ex2:words:1:zh":"'s","grammar:579:ex2:words:1:pos":"particle","grammar:579:ex2:words:2:zh":"parents","grammar:579:ex2:words:2:note":"りょうしん","grammar:579:ex2:words:2:pos":"noun","grammar:579:ex2:words:3:zh":"(topic)","grammar:579:ex2:words:3:pos":"particle","grammar:579:ex2:words:4:zh":"kind","grammar:579:ex2:words:4:note":"やさしい","grammar:579:ex2:words:4:pos":"adjective","grammar:579:ex2:words:5:zh":"(polite form)","grammar:579:ex2:words:5:pos":"copula","grammar:579:ex2:points:0":"彼の両親: his parents.","grammar:579:ex2:points:1":"優しい: gentle, kind.","grammar:579:ex3:trans":"I'm going on a trip with my parents.","grammar:579:ex3:structure":"〜と一緒に旅行します","grammar:579:ex3:words:0:zh":"parents","grammar:579:ex3:words:0:note":"りょうしん","grammar:579:ex3:words:0:pos":"noun","grammar:579:ex3:words:1:zh":"with","grammar:579:ex3:words:1:pos":"particle","grammar:579:ex3:words:2:zh":"together","grammar:579:ex3:words:2:note":"いっしょに","grammar:579:ex3:words:2:pos":"adverb","grammar:579:ex3:words:3:zh":"travel / trip","grammar:579:ex3:words:3:note":"りょこうします","grammar:579:ex3:words:3:pos":"verb","grammar:579:ex3:points:0":"〜と一緒に: together with…","grammar:579:ex3:points:1":"両親と: with one's parents.","grammar:579:ex4:trans":"My parents moved last year.","grammar:579:ex4:structure":"〜は〜に引っ越しました","grammar:579:ex4:words:0:zh":"parents","grammar:579:ex4:words:0:note":"りょうしん","grammar:579:ex4:words:0:pos":"noun","grammar:579:ex4:words:1:zh":"(topic)","grammar:579:ex4:words:1:pos":"particle","grammar:579:ex4:words:2:zh":"last year","grammar:579:ex4:words:2:note":"きょねん","grammar:579:ex4:words:2:pos":"noun","grammar:579:ex4:words:3:zh":"(point in time)","grammar:579:ex4:words:3:pos":"particle","grammar:579:ex4:words:4:zh":"moved","grammar:579:ex4:words:4:note":"ひっこしました","grammar:579:ex4:words:4:pos":"verb","grammar:579:ex4:points:0":"引っ越す: to move house.","grammar:579:ex4:points:1":"去年に: last year (time point).","grammar:579:ex5:trans":"I'm grateful to my parents.","grammar:579:ex5:structure":"〜に感謝しています","grammar:579:ex5:words:0:zh":"I","grammar:579:ex5:words:0:note":"わたし","grammar:579:ex5:words:0:pos":"pronoun","grammar:579:ex5:words:1:zh":"(topic)","grammar:579:ex5:words:1:pos":"particle","grammar:579:ex5:words:2:zh":"parents","grammar:579:ex5:words:2:note":"りょうしん","grammar:579:ex5:words:2:pos":"noun","grammar:579:ex5:words:3:zh":"(object)","grammar:579:ex5:words:3:pos":"particle","grammar:579:ex5:words:4:zh":"am grateful","grammar:579:ex5:words:4:note":"かんしゃしています","grammar:579:ex5:words:4:pos":"verb","grammar:579:ex5:points:0":"〜に感謝する: to be grateful for …","grammar:579:ex5:points:1":"両親に: to one's parents."},"580":{"example:580:exzh":"I have a headache.","example:580:exzh2":"When my stomach hurts, I take medicine.","example:580:exzh3":"Doesn't it hurt?","example:580:exzh4":"She said her hand hurts.","example:580:exzh5":"That injury looks painful.","grammar:580:ex:trans":"I have a headache.","grammar:580:ex:structure":"noun＋が＋i-adjective＋です. With the sensation adjective 「痛い」, the body part takes が.","grammar:580:ex:explain":"This sentence shows that with adjectives of bodily sensation, the body part takes 「が」. 「痛い」 (painful) is an i-adjective of sensation, and the part that hurts is marked with 「が」, so 「頭が痛い」 means my head hurts; adding 「です」 makes it polite. The whole sentence means I have a headache. It works the same way as 「足が痛い」 in sentence 418 earlier: whichever part of the body feels bad takes 「が」. The fixed Japanese pattern for describing physical discomfort is part＋が＋痛い／かゆい and other sensation adjectives — just remember that the sensation takes 「が」.","grammar:580:ex:words:0:zh":"head","grammar:580:ex:words:0:note":"あたま","grammar:580:ex:words:0:pos":"noun","grammar:580:ex:words:1:zh":"(nominative)","grammar:580:ex:words:1:pos":"particle","grammar:580:ex:words:2:zh":"painful","grammar:580:ex:words:2:note":"いたい","grammar:580:ex:words:2:pos":"adjective","grammar:580:ex:words:3:zh":"(polite form)","grammar:580:ex:words:3:pos":"copula","grammar:580:ex:points:0":"痛い: painful (the part takes が: 頭が痛い)","grammar:580:ex:points:1":"i-adjective polite form: 痛いです","grammar:580:ex2:trans":"When my stomach hurts, I take medicine.","grammar:580:ex2:structure":"〔〜が痛いとき〕＋は、薬を飲みます. 「〜とき」 means when…, and it follows the plain form.","grammar:580:ex2:words:0:zh":"stomach","grammar:580:ex2:words:0:note":"おなか","grammar:580:ex2:words:0:pos":"noun","grammar:580:ex2:words:1:zh":"(nominative)","grammar:580:ex2:words:1:pos":"particle","grammar:580:ex2:words:2:zh":"painful","grammar:580:ex2:words:2:note":"いたい","grammar:580:ex2:words:2:pos":"adjective","grammar:580:ex2:words:3:zh":"time","grammar:580:ex2:words:3:pos":"noun","grammar:580:ex2:words:4:zh":"(topic marker)","grammar:580:ex2:words:4:pos":"particle","grammar:580:ex2:words:5:zh":"medicine","grammar:580:ex2:words:5:note":"くすり","grammar:580:ex2:words:5:pos":"noun","grammar:580:ex2:words:6:zh":"(object marker)","grammar:580:ex2:words:6:pos":"particle","grammar:580:ex2:words:7:zh":"take (medicine)","grammar:580:ex2:words:7:note":"のみます; 薬を飲む = to take medicine","grammar:580:ex2:words:7:pos":"verb","grammar:580:ex2:points:0":"〜とき: when… (follows the plain / attributive form)","grammar:580:ex2:points:1":"薬を飲む: to take medicine (uses 飲む)","grammar:580:ex3:trans":"Doesn't it hurt?","grammar:580:ex3:structure":"i-adjective negative＋ですか. 「痛くない」 is the negative form of 「痛い」.","grammar:580:ex3:words:0:zh":"it doesn't hurt","grammar:580:ex3:words:0:note":"いたくない; i-adjective negative","grammar:580:ex3:words:0:pos":"adjective","grammar:580:ex3:words:1:zh":"(polite form)","grammar:580:ex3:words:1:pos":"copula","grammar:580:ex3:words:2:zh":"(question)","grammar:580:ex3:words:2:pos":"particle","grammar:580:ex3:points:0":"i-adjective negative: 痛い→痛くない","grammar:580:ex3:points:1":"〜ないですか: isn't it…?","grammar:580:ex4:trans":"She said her hand hurt.","grammar:580:ex4:structure":"〜は＋〔手が痛い〕＋と＋言った. 「と」 quotes what was said.","grammar:580:ex4:words:0:zh":"she","grammar:580:ex4:words:0:note":"かのじょ","grammar:580:ex4:words:0:pos":"pronoun","grammar:580:ex4:words:1:zh":"(topic marker)","grammar:580:ex4:words:1:pos":"particle","grammar:580:ex4:words:2:zh":"hand","grammar:580:ex4:words:2:note":"て","grammar:580:ex4:words:2:pos":"noun","grammar:580:ex4:words:3:zh":"(nominative)","grammar:580:ex4:words:3:pos":"particle","grammar:580:ex4:words:4:zh":"painful","grammar:580:ex4:words:4:note":"いたい","grammar:580:ex4:words:4:pos":"adjective","grammar:580:ex4:words:5:zh":"(quotation)","grammar:580:ex4:words:5:pos":"particle","grammar:580:ex4:words:6:zh":"said","grammar:580:ex4:words:6:note":"いった","grammar:580:ex4:words:6:pos":"verb","grammar:580:ex4:points:0":"〜と言った: said that… (quotation)","grammar:580:ex4:points:1":"手が痛い: the hand hurts","grammar:580:ex5:trans":"That injury looks painful.","grammar:580:ex5:structure":"〜は＋〜そう＋ですね. 「i-adjective minus い＋そう」 expresses appearance: looks…","grammar:580:ex5:words:0:zh":"that","grammar:580:ex5:words:0:pos":"pre-noun adjectival","grammar:580:ex5:words:1:zh":"scar","grammar:580:ex5:words:1:note":"けが","grammar:580:ex5:words:1:pos":"noun","grammar:580:ex5:words:2:zh":"(topic marker)","grammar:580:ex5:words:2:pos":"particle","grammar:580:ex5:words:3:zh":"looks painful","grammar:580:ex5:words:3:note":"いたそう; i-adjective minus い＋そう, appearance","grammar:580:ex5:words:3:pos":"adjective","grammar:580:ex5:words:4:zh":"(polite form)","grammar:580:ex5:words:4:pos":"copula","grammar:580:ex5:words:5:zh":"right?","grammar:580:ex5:words:5:pos":"particle","grammar:580:ex5:points:0":"i-adjective＋そう: looks… (痛い→痛そう)","grammar:580:ex5:points:1":"ね: sentence-final particle seeking agreement"},"591":{"example:591:exzh":"I never thought he would come.","example:591:exzh2":"I never thought something like this would happen.","example:591:exzh3":"I can't believe you knew about that too?","example:591:exzh4":"I can't believe it.","example:591:exzh5":"I never thought it would end this quickly."},"599":{"example:599:exzh":"A new hero appeared.","example:599:exzh2":"He suddenly appeared.","example:599:exzh3":"A castle appeared out of the fog.","example:599:exzh4":"A big rainbow appeared in the sky.","example:599:exzh5":"The insect that appeared was rare."}};